window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0054", [{"word":"identification","ipa_uk":"/aɪˌdentɪfɪˈkeɪʃn/","ipa_us":"/aɪˌdentɪfɪˈkeɪʃn/","definition_zh":"识别；身份的确认；身份证件；认同；（生物学）物种鉴定","definition_en":"the act of recognizing something or establishing who someone is, the document that proves identity, or a feeling of belonging with another person or group","core_image":"把一样陌生的东西放到已知的格子里，两者严丝合缝地对上","scene":"The botanist spent the morning on the identification of a moss she had never seen before.","sceneCN":"这里 identification 是「物种鉴定」（第 5 个义项：把标本对到已知学名）；句意：植物学家花了一上午鉴定一种她从没见过的苔藓。图中可辨识物件：放大镜、压在纸上的苔藓标本、翻开的名录。","pos":[{"tag":"n.","zh":"识别；确认身份；身份证件；认同"}],"collocations":[{"phrase":"photo identification","zh":"带照片的身份证件"},{"phrase":"identification card","zh":"身份证；证件卡"},{"phrase":"species identification","zh":"物种鉴定"},{"phrase":"identification with","zh":"对……的认同"},{"phrase":"positive identification","zh":"确凿的身份确认"},{"phrase":"identification number","zh":"身份编号"}],"forms":[{"label":"单数","form":"identification"},{"label":"复数（多份证件或多重识别）","form":"identifications"},{"label":"动词","form":"identify"}],"derivatives":[{"word":"identify","pos":"v.","zh":"认出；确认；把……等同于"},{"word":"identity","pos":"n.","zh":"身份；特性；同一性"},{"word":"identical","pos":"adj.","zh":"完全相同的"},{"word":"identifier","pos":"n.","zh":"标识符；识别标志"}],"senses":[{"no":"01","title":"Recognizing something as known","titleCN":"把某物认出来","definition":"the act of recognizing something and placing it in a known category","definitionCN":"认出某物并把它归入已知类别的行为","example":"The identification of the unknown mineral took two days.","exampleCN":"鉴定这种未知矿物花了两天。","why":"Idem means 'same' and facere means 'make'. To identify is literally to make one thing the same as a known thing, and the noun names that matching act.","whyCN":"idem 意为“相同”，facere 意为“使”。identify 字面上就是使一物与已知之物相同，这个名词命名的正是那次配对动作。"},{"no":"02","title":"Establishing who a person is","titleCN":"确认某人的身份","definition":"the process of determining the name or identity of a person","definitionCN":"确定某人姓名或身份的过程","example":"Identification of the passenger was delayed for hours.","exampleCN":"确认这名乘客的身份被耽搁了数小时。","why":"The same matching act now runs between a face and a record. The word keeps the legal and administrative tone of a file being checked.","whyCN":"同一个配对动作现在发生在面孔与档案之间。这个词保留了核对档案时的法律与行政语气。"},{"no":"03","title":"A document proving who you are","titleCN":"证明身份的证件","definition":"an official document such as a card or passport that proves a person's identity","definitionCN":"身份证、护照等证明个人身份的官方文件","example":"You need two forms of identification to enter the building.","exampleCN":"进入这栋楼需要出示两份身份证件。","why":"The abstract act is compressed into a paper object: the card stands in for the matching so that a stranger can check it quickly.","whyCN":"抽象的配对行为被压缩成一张纸：卡片代替了核对过程，让陌生人也能快速查验。"},{"no":"04","title":"Feeling at one with someone","titleCN":"对他人或群体的认同","definition":"a feeling of closeness in which one shares another person's situation or group's character","definitionCN":"分享他人处境或群体特质、感到亲近的情感","example":"Her identification with the villagers grew during the drought.","exampleCN":"在干旱期间，她对村民的认同感增强了。","why":"Here the 'same-making' happens inside the self: the boundary between you and another group is treated as if it could be removed.","whyCN":"这里的“使相同”发生在自我内部：你与另一个群体之间的边界被当作可以撤除。"},{"no":"05","title":"Matching a specimen to a species","titleCN":"生物学中的物种鉴定","definition":"in biology, the determination of the species to which a specimen belongs","definitionCN":"生物学中确定标本所属物种的工作","example":"Correct identification of the beetle depended on the shape of its antennae.","exampleCN":"正确鉴定这种甲虫取决于其触角形状。","why":"Taxonomy is matching at its purest: the specimen must be made the same as a named type, and the noun records that forensic sorting.","whyCN":"分类学是最纯粹的配对：标本必须与命名模式相同，这个名词记录的就是这种辨类工作。"},{"no":"06","title":"Treating two things as one","titleCN":"逻辑与数学中的视为等同","definition":"in logic and mathematics, the act of treating two distinct expressions or objects as the same","definitionCN":"逻辑与数学中把两个不同表达式或对象当作同一的做法","example":"Identification of the two variables shortened the proof.","exampleCN":"把两个变量视为等同，使证明变短了。","why":"The original sense 'make same' is used technically: two symbols are declared to stand for one object, and the proof proceeds as if there were no gap.","whyCN":"原义“使相同”被技术化使用：两个符号被宣布代表同一个对象，证明便当作不存在间隙那样推进。"},{"no":"07","title":"A mark that identifies","titleCN":"起识别作用的标识","definition":"a label, colour code or mark attached to something so that it can be recognized","definitionCN":"附着于某物、使其可被识别的标签、色码或标记","example":"Each blood sample has a colour-coded identification.","exampleCN":"每份血样都有彩色编码的识别标识。","why":"The abstract act becomes a visible object again. The mark carries the matching information so that the match can be repeated by anyone.","whyCN":"抽象行为再次变成可见的东西。标识承载配对信息，使任何人都能重复这次配对。"},{"no":"08","title":"Taking on another's role in the mind","titleCN":"心理学中的认同机制","definition":"in psychology, the unconscious adoption of another person's characteristics or role","definitionCN":"心理学中无意识地吸收他人特质或角色的过程","example":"Identification with the hero lets the reader feel his fear.","exampleCN":"对主人公的认同让读者感受到他的恐惧。","why":"Psychoanalysis borrowed the everyday sense and made it unconscious: the self quietly makes itself the same as a model, without announcing the copy.","whyCN":"精神分析借用了日常义并使之无意识化：自我悄悄把自己变得与某个榜样相同，却不宣布这次模仿。"}],"etymology":{"intro":{"en":"Identification is a Medieval Latin verb wearing a French noun suffix: idem 'same' plus facere 'make' produced identificare, and French turned it into identification. Every sense still performs the same little operation, making one thing equal to another.","cn":"identification 是拉丁动词披着法语名词后缀：idem“相同”加 facere“使”构成 identificare，法语再把它变成 identification。每个义项都仍在做同一个小动作——使一物等于另一物。"},"items":[{"era":"PIE *dhe- (reconstructed form)","en":"The root behind facere, 'to make or put', is reconstructed as *dhe- and is generally believed to underlie Latin facere, Greek tithenai and English do.","cn":"facere“做、放置”背后的词根被重构为 *dhe-，一般认为是拉丁语 facere、希腊语 tithenai 与英语 do 的共同来源。"},{"era":"LATIN idem + facere","en":"Idem, 'the same', joined facere, 'to make', in the Medieval Latin verb identificare, 'to make the same'. The compound is late and technical, not classical.","cn":"idem“相同”与 facere“使”在中古拉丁动词 identificare“使相同”中结合。这个复合词出现较晚，属技术用语，并非古典拉丁造词。"},{"era":"LATIN -ficare / -ficatio","en":"The suffix -ficare built verbs meaning 'to make', as in aedificare and modificare. Its noun partner -ficatio produced abstract nouns of making.","cn":"后缀 -ficare 构成意为“使……”的动词，如 aedificare、modificare；其名词伙伴 -ficatio 造出表示“使之”的抽象名词。"},{"era":"17C. FRENCH identification","en":"French formed identification as an administrative and philosophical term. English adopted it in the 17th century, first for the act of treating things as the same.","cn":"法语把 identification 造成行政与哲学术语。英语在 17 世纪借入，最初指“把事物视为同一”的行为。"},{"era":"19C. POLICE AND SCIENCE","en":"Police records and taxonomic botany gave the word its everyday and scientific senses: identifying a suspect, identifying a specimen. The document sense follows from police practice.","cn":"警务档案与植物分类学赋予这个词日常义与科学义：确认嫌疑人、鉴定标本。证件义则从警务实践中派生。"},{"era":"20C. PSYCHOLOGY","en":"Psychoanalysis added the inward sense, identification with a person or group. The word now names both an external check and an internal bond.","cn":"精神分析补充了向内的义项：对某人或某群体的认同。这个词现在同时命名外部核对与内部联结。"}]},"similar":{"note":{"en":"The look-alike group separates the verb, the two nouns and the adjective built on idem. The meaning group compares words for checking, recognizing and belonging.","cn":"形近组区分同一 idem 词基上的动词、两个名词与形容词；词义组比较表示核对、认出与归属的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"identify","ipa":"/aɪˈdentɪfaɪ/","tag":"verb","definition":"to recognize, to establish who someone is, or to treat two things as the same. It is the action behind every sense of the noun.","definitionCN":"认出、确认身份或把两物视为相同。它是名词各义项背后的动作。"},{"word":"identity","ipa":"/aɪˈdentəti/","tag":"noun","definition":"who or what a person or thing is, or the sameness of two things. It names the result, not the checking process.","definitionCN":"人或物是谁、是什么，或两物之间的一致。它命名结果，而非核对过程。"},{"word":"identical","ipa":"/aɪˈdentɪkl/","tag":"adjective","definition":"exactly the same. It states the equality that identification tries to establish, without any act of checking.","definitionCN":"完全相同的。它陈述 identification 试图建立的相等，却不含核对动作。"}]},{"heading":"NEAR MEANING","entries":[{"word":"recognition","ipa":"/ˌrekəɡˈnɪʃn/","tag":"noticing again","definition":"the act of knowing that something seen or heard before is familiar. It starts from memory, while identification starts from a record or a category.","definitionCN":"认出见过或听过之物为熟悉的。它从记忆出发，而 identification 从档案或类别出发。"},{"word":"verification","ipa":"/ˌverɪfɪˈkeɪʃn/","tag":"checking truth","definition":"the act of proving that a claim or document is true. It tests accuracy, while identification establishes who or what something is.","definitionCN":"证明某个说法或文件为真的行为。它检验准确性，而 identification 确定其身份或类别。"},{"word":"authentication","ipa":"/ˌɔːθentɪˈkeɪʃn/","tag":"proving genuine","definition":"the process of proving that something is genuine, especially a signature or a digital user. It certifies origin rather than category.","definitionCN":"证明某物为真品的过程，尤指签名或数字用户。它认证来源，而非归类。"},{"word":"affiliation","ipa":"/əˌfɪliˈeɪʃn/","tag":"belonging to a body","definition":"the state of being officially connected with an organization. It is close to sense 04 but names membership, not felt closeness.","definitionCN":"与某组织正式联系的状态。它接近第 4 义项，但指成员身份，而非情感上的亲近。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks build the word from idem 'same' plus facere 'make', then let the matching image cover documents, species and groups.","cn":"这些记忆钩从 idem“相同”加 facere“使”搭起这个词，再用配对意象覆盖证件、物种与群体。"},"normal":[{"en":"Split it as idem + facere: make the same. Identification is same-making turned into a noun.","cn":"拆成 idem 加 facere：使相同。identification 就是“使相同”变成名词。"},{"en":"Picture a passport photo being laid over a face: the two shapes must line up exactly.","cn":"想象把护照照片盖到一张脸上：两个轮廓必须严丝合缝地重合。"},{"en":"In biology the same lining-up happens between a specimen and a named type.","cn":"生物学中同一种重合发生在标本与命名模式之间。"},{"en":"When you feel identification with a group, you quietly lay your own shape over theirs.","cn":"当你对某个群体产生认同时，你是悄悄把自己的轮廓盖到他们的轮廓上。"},{"en":"Remember the chain: identify the thing, then show identification, then feel identification.","cn":"记住这条链：先 identify 认出来，再出示 identification 证件，最后产生 identification 认同。"}],"abstract":[{"en":"Keep one operation in mind: two things are placed on top of each other until the seam disappears.","cn":"只记一个动作：两样东西被叠在一起，直到接缝消失。"},{"en":"Treat the word as the formal name for 'this is that': every sense says an unknown equals a known.","cn":"把这个词当作“此即彼”的正式名称：每个义项都在说未知等于已知。"},{"en":"Notice that even the feeling of belonging is described as a matching, not as a gift.","cn":"注意连归属感也被描述成一次配对，而不是一份礼物。"}]},"examples":[{"en":"Accurate identification of the disease depends on early testing.","cn":"准确识别这种疾病取决于早期检测。"},{"en":"Please bring photo identification to the interview.","cn":"面试时请携带带照片的身份证件。"},{"en":"The children's identification with their new school grew quickly.","cn":"孩子们对新学校的认同感很快增强了。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“挨得替非可伸”：窗口前挨个递上证件，工作人员伸手核对，才能确认身份。","word":"identification"},"root":"中古拉丁 identificare“使相同”（idem 相同 + facere 使），名词形式 identificatio 经法语 identification 进入英语；核心是“把未知之物对到已知之物”。","sensesIntro":{"en":"One Latin phrase, 'make the same', runs through all eight senses. A mineral is matched to a category, a face to a record, a card to a person, a reader to a hero, a beetle to a species, a symbol to another symbol, a mark to an object. Identification is always a joining operation, never a discovery from nothing.","cn":"一句拉丁语“使相同”贯穿八个义项：矿物对到类别，面孔对到档案，证件对到本人，读者对到主人公，甲虫对到物种，符号对到符号，标识对到物件。identification 始终是一次接合动作，而不是凭空发现。"},"semanticMap":{"core":{"en":"Making one thing equal to another so that the pair can be treated as one.","cn":"使一物等于另一物，从而可以把这一对当作一体。"},"chain":["MATCH","SAME","MAKE","NAME","PROVE","BELONG"],"branches":[{"senses":"S1 · S2","en":"CHECKING: a thing or a person is matched to a known record.","cn":"核对：某物或某人被对到已知档案。"},{"senses":"S3 · S7","en":"OBJECTS: the match is carried by a card or a mark.","cn":"物件：配对由证件或标识承载。"},{"senses":"S4 · S8","en":"INWARD: the self makes itself the same as a person or group.","cn":"向内：自我把自己变得与某人或某群体相同。"},{"senses":"S5","en":"SCIENCE: a specimen is matched to a named species.","cn":"科学：标本被对到命名物种。"},{"senses":"S6","en":"LOGIC: two expressions are declared to stand for one object.","cn":"逻辑：两个表达式被宣布代表同一个对象。"}]},"affixes":{"intro":{"en":"Identification stacks idem, the verb-forming -ficare and the noun suffix -atio. The items below show the same base with other endings and show what happens when the 'same' is claimed too strongly.","cn":"identification 叠了 idem、动词后缀 -ficare 与名词后缀 -atio。下列条目展示同一词基配其他词尾，并展示“相同”被说得过头时的结果。"},"latinIntro":{"en":"The Latin entries give the pronoun and the verb behind the compound. They explain why a word about identity also yields words about being identical.","cn":"拉丁语条目给出复合词背后的代词与动词。它们解释了为什么一个关于身份的词同时产生“完全相同”的词族。"},"items":[{"word":"identification","structure":"identificare + -atio (process noun)","meaning":"the act of recognizing or proving identity","meaningCN":"识别或证明身份的行为","example":"Identification of the remains took weeks.","exampleCN":"遗骸的身份确认花了数周。"},{"word":"identify","structure":"Medieval Latin identificare","meaning":"to recognize; to establish; to treat as the same","meaningCN":"认出；确认；视为相同","example":"Can you identify the author of this note?","exampleCN":"你能认出这张便条的作者吗？"},{"word":"identity","structure":"Late Latin identitas, from idem","meaning":"who or what someone is; sameness","meaningCN":"身份；同一性","example":"The thief hid his identity for years.","exampleCN":"那个窃贼隐藏身份多年。"},{"word":"identical","structure":"Medieval Latin identicus + -al","meaning":"exactly the same","meaningCN":"完全相同的","example":"The twins wore identical coats.","exampleCN":"这对双胞胎穿着完全相同的外套。"},{"word":"identifier","structure":"identify + -er (agent noun)","meaning":"a symbol or mark that names an item","meaningCN":"命名某项事物的符号或标记","example":"Each record has a unique identifier.","exampleCN":"每条记录都有唯一标识符。"},{"word":"identifiable","structure":"identify + -able (capability suffix)","meaning":"able to be recognized","meaningCN":"可被认出的","example":"The object was barely identifiable.","exampleCN":"那件东西几乎无法辨认。"},{"word":"unidentifiable","structure":"un- (negation) + identifiable","meaning":"impossible to recognize","meaningCN":"无法辨认的","example":"An unidentifiable smell filled the room.","exampleCN":"一股无法辨认的气味充满了房间。"},{"word":"identically","structure":"identical + -ly (adverb)","meaning":"in exactly the same way","meaningCN":"以完全相同的方式","example":"Both machines were identically set up.","exampleCN":"两台机器以完全相同的方式设置。"}],"latinEntries":[{"word":"idem","structure":"pronoun, undeclined","meaning":"the same","meaningCN":"同一个；相同的"},{"word":"facere","structure":"3rd conjugation verb","meaning":"to make, to do","meaningCN":"做；制造"},{"word":"identitas","structure":"idem + -itas (abstract noun)","meaning":"sameness; identity","meaningCN":"相同性；身份"}]}},{"word":"ideological","ipa_uk":"/ˌaɪdiəˈlɒdʒɪkl/","ipa_us":"/ˌaɪdiəˈlɑːdʒɪkl/","definition_zh":"意识形态的；观念体系的；带有政治立场的；教条化的","definition_en":"relating to a system of ideas and beliefs, especially one that shapes political or social action","core_image":"一副有色眼镜：同样的世界，透过它只剩一种颜色","scene":"The debate was settled on ideological grounds long before any data were examined.","sceneCN":"这里 ideological 是「以观念体系为根据的」（第 2 个义项：政策与判断建立在信念体系上）；句意：这场争论早在检查任何数据之前，就按意识形态立场定下了。图中可辨识物件：两把对立摆放的椅子、标着两种颜色的旗子、被推到一旁的图表。","pos":[{"tag":"adj.","zh":"意识形态的；观念体系的；带政治色彩的"}],"collocations":[{"phrase":"ideological grounds","zh":"意识形态方面的理由"},{"phrase":"ideological divide","zh":"意识形态分歧"},{"phrase":"ideological purity","zh":"意识形态的纯粹性"},{"phrase":"ideological commitment","zh":"意识形态上的承诺"},{"phrase":"ideological bias","zh":"观念偏见"},{"phrase":"ideological struggle","zh":"意识形态斗争"}],"forms":[{"label":"原级","form":"ideological"},{"label":"比较级","form":"more ideological"},{"label":"最高级","form":"most ideological"},{"label":"副词","form":"ideologically"}],"derivatives":[{"word":"ideology","pos":"n.","zh":"意识形态；观念体系"},{"word":"ideologue","pos":"n.","zh":"意识形态拥护者；理论空谈者"},{"word":"ideological","pos":"adj.","zh":"意识形态的"},{"word":"ideologically","pos":"adv.","zh":"从意识形态上"}],"senses":[{"no":"01","title":"Belonging to a system of ideas","titleCN":"与观念体系相关的","definition":"relating to a structured set of ideas about how society should work","definitionCN":"与社会应如何运转的一整套观念相关的","example":"The two camps are separated by an ideological wall.","exampleCN":"两个阵营被一堵意识形态的墙隔开。","why":"Ideology was coined as the 'science of ideas'. Its adjective simply says that something belongs to that layer of thought rather than to facts.","whyCN":"ideology 当初被造为“观念的科学”。其形容词只是说明某物属于思想这一层，而不属于事实层。"},{"no":"02","title":"Founded on belief rather than evidence","titleCN":"以信念体系为根据的","definition":"based on a set of beliefs that is accepted in advance of evidence","definitionCN":"建立在先于证据就被接受的信念之上的","example":"The reform was ideological rather than practical.","exampleCN":"这项改革是意识形态驱动的，而非出于实际需要。","why":"The word marks the point where a conclusion comes from a creed instead of a measurement. Belief is placed at the front of the sentence.","whyCN":"这个词标记了一个转折点：结论来自信条而非测量。信念被放到了句子的最前面。"},{"no":"03","title":"Doctrinaire, in a critical tone","titleCN":"被批评为教条化的","definition":"used critically to mean driven by doctrine and closed to contrary facts","definitionCN":"带批评意味，指被教条驱动、对相反事实封闭","example":"Critics dismissed the plan as purely ideological.","exampleCN":"批评者把该计划斥为纯属教条。","why":"Napoleon turned the word ideology into a sneer two centuries ago. The adjective inherited that sneer and can now accuse someone of preferring theory to reality.","whyCN":"两百年前拿破仑把 ideology 变成了讥讽语。这个形容词继承了那种讥讽，如今可以指责任某人宁可要理论也不要现实。"},{"no":"04","title":"Carrying a clear political colour","titleCN":"带有明确政治立场的","definition":"showing a recognizable political alignment in content or tone","definitionCN":"在内容或语气上显出可辨识的政治归属","example":"The newspaper has a clear ideological line.","exampleCN":"这份报纸有明确的意识形态路线。","why":"A 'line' is the visual form of the word: ideas arranged along one direction, so that readers can see which side a text stands on.","whyCN":"“路线”是这个词的可视形态：观念沿一个方向排开，读者因此看得出文本站在哪一边。"},{"no":"05","title":"Belonging to the early study of ideas","titleCN":"观念学意义上的（学术史）","definition":"in the history of thought, relating to the project of analysing the origin of ideas","definitionCN":"在思想史中，与分析观念起源的学术计划相关的","example":"The term first appears in the ideological writings of the 1790s.","exampleCN":"该词最早出现在 18 世纪 90 年代的观念学著作中。","why":"Destutt de Tracy wanted a natural science of ideas. The adjective still carries that cool, analytical tone when historians use it.","whyCN":"德斯蒂·德·特拉西想建立一门关于观念的自然科学。历史学者使用这个形容词时，仍带着那种冷静的分析语气。"},{"no":"06","title":"Expressing cultural values","titleCN":"体现文化价值取向的","definition":"encoding the values and assumptions of a culture rather than being neutral","definitionCN":"编码了某种文化的价值与预设，而非中立","example":"Textbooks are never ideologically neutral.","exampleCN":"教科书从来不是意识形态中立的。","why":"The word is used to deny neutrality: what looks like plain description already carries a set of values, as a lens carries a tint.","whyCN":"这个词被用来否认中立：看似平直的描述其实已经带着一套价值，就像镜片带着颜色。"},{"no":"07","title":"Serving to mobilize support","titleCN":"用于宣传动员的","definition":"used to rally people around a cause or to justify a political programme","definitionCN":"用来围绕某个事业动员群众或为政治纲领辩护的","example":"The broadcast served an ideological purpose more than a news one.","exampleCN":"这档广播更多服务于宣传目的，而非新闻目的。","why":"Here ideas become a tool. The adjective names the function of the message rather than its content.","whyCN":"这里的观念变成了工具。这个形容词命名的是讯息的功能，而不是其内容。"},{"no":"08","title":"A difference of theory, not of persons","titleCN":"理论观念层面的分歧","definition":"describing a disagreement that rests on theory rather than personal feeling","definitionCN":"描述建立在理论而非个人情感之上的分歧","example":"Their quarrel was ideological, not personal.","exampleCN":"他们的争执是观念层面的，不是私人恩怨。","why":"The sentence uses the adjective to move a conflict up one level, from faces to frameworks, where it can be argued instead of felt.","whyCN":"这句话用这个形容词把冲突抬高一层，从面孔升到框架，使它可以被辩论而不只是被感受。"}],"etymology":{"intro":{"en":"Ideological descends from a word invented in Paris in 1796. Destutt de Tracy joined Greek idea 'form, appearance' to -logia 'study' and called his project idéologie, the science of ideas. Napoleon turned the name into an insult, and the adjective inherited both the analytical and the sneering tone.","cn":"ideological 源于 1796 年巴黎造出的一个词。德斯蒂·德·特拉西把希腊语 idea“形相、外观”与 -logia“研究”结合，称自己的计划为 idéologie，即观念的科学。拿破仑把这个名称变成骂人的话，形容词同时继承了分析语气与讥讽语气。"},"items":[{"era":"PIE *weyd- (reconstructed form)","en":"The Greek verb idein, 'to see', is generally traced to a root reconstructed as *weyd-, 'to see, to know', which also underlies Latin videre and English wit.","cn":"希腊语动词 idein“看见”一般被追溯到重构词根 *weyd-“看见、知道”，它也是拉丁语 videre 与英语 wit 的来源。"},{"era":"GREEK ἰδέα","en":"Idea meant 'form, shape, appearance', then in Plato 'the eternal form perceived by the mind'. The visual origin is still audible in the word.","cn":"idea 意为“形相、形状、外观”，在柏拉图那里指“由心智观看到的永恒形式”。视觉来源至今仍能从词里听出来。"},{"era":"GREEK -λογία","en":"-Logia, from logos 'word, account, reasoned discourse', built names for fields of study. Joined to idea it produced a 'study of ideas'.","cn":"-logia 来自 logos“言说、论述、理性话语”，用于构成学科名称。与 idea 结合，就产生“关于观念的研究”。"},{"era":"1796 FRENCH idéologie","en":"Destutt de Tracy coined idéologie for a proposed science that would trace ideas to sensations. He meant it as neutral physiology of thought.","cn":"德斯蒂·德·特拉西造出 idéologie，指一门把观念追溯到感觉的科学。他本意是价值中立的思维生理学。"},{"era":"19C. ENGLISH, VIA NAPOLEON'S INSULT","en":"Napoleon mocked the idéologues as empty theorists, and the word spread with that stain. English took ideological in the early 19th century with both meanings alive.","cn":"拿破仑嘲笑这些观念学者是空谈理论家，这个词便带着这层污迹传播开来。英语在 19 世纪初借入 ideological 时，两种含义都还活着。"},{"era":"20C. POLITICS AND SOCIAL SCIENCE","en":"Political science generalized the adjective to any belief system that guides action. The neutral and the critical uses now sit side by side.","cn":"政治学把这个形容词推广到任何指导行动的信念体系。中立用法与批评用法如今并列存在。"}]},"similar":{"note":{"en":"The look-alike group separates the noun, the person and the adjective built on idea. The meaning group compares words about belief, doctrine and political alignment.","cn":"形近组区分 idea 词基上的名词、人物名词与形容词；词义组比较表示信念、教义与政治归属的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"ideology","ipa":"/ˌaɪdiˈɒlədʒi/","tag":"noun","definition":"a system of ideas and beliefs, especially one that guides political action. It is the thing the adjective describes.","definitionCN":"一套观念与信念，尤指指导政治行动的体系。它正是形容词所描述的对象。"},{"word":"ideologue","ipa":"/ˌaɪdiˈɒɡ/","tag":"person noun","definition":"a person who holds and defends a rigid set of ideas. It names a believer, not a quality.","definitionCN":"坚持并捍卫一套僵硬观念的人。它指信奉者本人，而非性质。"},{"word":"ideal","ipa":"/aɪˈdiːl/","tag":"adjective and noun","definition":"perfect, or a standard of perfection. It shares the 'form' root but means excellence, not a political creed.","definitionCN":"完美的，或完美的标准。它与“形相”词根同源，但指卓越，而非政治信条。"}]},{"heading":"NEAR MEANING","entries":[{"word":"political","ipa":"/pəˈlɪtɪkl/","tag":"about power","definition":"relating to government, parties or the distribution of power. It is broader: a policy can be political without resting on a creed.","definitionCN":"与政府、政党或权力分配有关的。它更宽：一项政策可以是政治的，却不必建立在信条上。"},{"word":"doctrinal","ipa":"/dɒkˈtraɪnl/","tag":"about doctrine","definition":"relating to an official body of teaching, especially in religion. It stresses authorized teaching, while ideological stresses a social creed.","definitionCN":"与官方教导体系有关的，尤指宗教。它强调被认可的教义，而 ideological 强调社会信条。"},{"word":"partisan","ipa":"/pɑːˈtɪzən/","tag":"taking sides","definition":"strongly attached to one party or cause. It adds loyalty to the idea, where ideological may be merely descriptive.","definitionCN":"坚定附属于某一党派或事业的。它在观念之外加上忠诚，而 ideological 可能只是描述性的。"},{"word":"philosophical","ipa":"/fɪˈlɒsəfɪkl/","tag":"about thought","definition":"relating to philosophy or to a calm attitude to life. It points to reasoned inquiry, not to a programme of action.","definitionCN":"与哲学有关的，或指对生活的平静态度。它指向理性探究，而非行动纲领。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks build ideological from idea plus -logy, then let the tinted-lens image cover policy, textbooks, broadcasts and personal quarrels.","cn":"这些记忆钩从 idea 加 -logy 搭起 ideological，再用“有色镜片”意象覆盖政策、教科书、广播与私人争执。"},"normal":[{"en":"See idea + -logical: a logic built on ideas rather than on data.","cn":"看成 idea 加 logical：一套建立在观念而非数据上的逻辑。"},{"en":"Picture tinted glasses: the world is unchanged, but everything looks one colour.","cn":"想象有色眼镜：世界没变，但一切都成了一个颜色。"},{"en":"When a report explains facts, it is descriptive; when it starts from a creed, it is ideological.","cn":"报告解释事实时是描述性的；从信条出发时就是意识形态的。"},{"en":"Remember Napoleon's sneer: the word can be a neutral label or a sharp accusation.","cn":"记住拿破仑的讥讽：这个词既可以是中立标签，也可以是尖锐指责。"},{"en":"Link it to the pair: ideology is the system, ideological is the quality, ideologue is the person.","cn":"连成一组：ideology 是体系，ideological 是性质，ideologue 是人。"}],"abstract":[{"en":"Keep one image: a frame placed over the world before anything is allowed to be seen.","cn":"只记一个意象：在看世界之前，先罩上一个框架。"},{"en":"Treat the word as a warning that the explanation arrived before the evidence.","cn":"把这个词当作一个提醒：解释先于证据到达。"},{"en":"Notice that the same word can describe and accuse; only context decides which.","cn":"注意同一个词既能描述也能指责，只有语境决定是哪一种。"}]},"examples":[{"en":"The split in the party was ideological rather than personal.","cn":"该党的分裂是意识形态上的，而非私人恩怨。"},{"en":"Any curriculum carries an ideological load, however neutral it looks.","cn":"任何课程都承担着意识形态负荷，无论它看起来多中立。"},{"en":"They refused the offer for purely ideological reasons.","cn":"他们纯因意识形态理由拒绝了这项提议。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“爱迪优乐极可”：爱迪生式的乐观逻辑推到极致，就成了只讲观念的 ideological。","word":"ideological"},"root":"法语 idéologie（1796 年德斯蒂·德·特拉西造词），由希腊语 ἰδέα“形相、外观”（来自 idein 看见）加 -λογία“学科”构成；形容词 ideological 由 idéologie 加 -al 派生，19 世纪初进入英语。","sensesIntro":{"en":"The word began as the name of a science of ideas and became a label for any creed that guides action. Its eight senses move from neutral membership ('belonging to a system of ideas') to sharp criticism ('doctrinaire'). What stays constant is the image of a frame placed in front of the world: the frame can be a research programme, a party line, a textbook's assumptions or a sneer.","cn":"这个词起初是一门观念科学的名称，后来成了任何指导行动的信条之名。八个义项从中立的归属（“属于一套观念”）一路走到尖锐批评（“教条化”）。不变的是“框架挡在世界之前”的意象：这个框架可以是研究计划、党派路线、教科书的预设，也可以是一声讥讽。"},"semanticMap":{"core":{"en":"A frame of ideas standing between a person and the facts.","cn":"一套观念框架，立在人与事实之间。"},"chain":["IDEA","SYSTEM","BELIEF","ALIGN","MOBILIZE","DOCTRINE"],"branches":[{"senses":"S1 · S5","en":"ORIGIN: the study of ideas and its neutral, analytical use.","cn":"起源：观念之学及其中立、分析的用法。"},{"senses":"S2 · S8","en":"BASIS: conclusions drawn from belief, and disputes argued on theory.","cn":"根据：从信念得出的结论，以及按理论争论的分歧。"},{"senses":"S3","en":"CRITICISM: doctrine closed to contrary facts.","cn":"批评：对相反事实封闭的教条。"},{"senses":"S4 · S7","en":"POLITICS: a line taken, a message used to rally support.","cn":"政治：选定的路线，以及用来动员支持的讯息。"},{"senses":"S6","en":"CULTURE: values carried by texts that look neutral.","cn":"文化：看似中立的文本所携带的价值。"}]},"affixes":{"intro":{"en":"Ideological is idea plus the combining form -logical. The items below show the noun, the person and the neutral adjective that share the same Greek base, and show how far the 'study' suffix spreads.","cn":"ideological 是 idea 加组合形式 -logical。下列条目展示共享同一希腊词基的名词、人物名词与中性形容词，并展示“学科”后缀扩散得有多远。"},"latinIntro":{"en":"The Latin entries are few because the word was coined in French from Greek parts. Latin idea is itself a borrowing of Greek ἰδέα, which is exactly the point: the concept travelled through Latin without a Latin root of its own.","cn":"拉丁语条目较少，因为这个词是法语用希腊成分造的。拉丁语 idea 本身就是希腊语 ἰδέα 的借词，这恰恰说明了要点：这个概念经由拉丁语传递，却没有自己的拉丁词根。"},"items":[{"word":"ideological","structure":"ideology + -ical (adjective suffix)","meaning":"relating to a system of ideas","meaningCN":"与观念体系有关的","example":"The conflict has an ideological dimension.","exampleCN":"这场冲突有意识形态维度。"},{"word":"ideology","structure":"French idéologie, from Greek idea + -logia","meaning":"a system of ideas and beliefs","meaningCN":"一套观念与信念体系","example":"The party's ideology has changed since the 1980s.","exampleCN":"该党的意识形态自 1980 年代以来已改变。"},{"word":"ideologue","structure":"French idéologue, from idéologie","meaning":"a rigid defender of a doctrine","meaningCN":"僵硬捍卫某教条的人","example":"He was a party ideologue rather than a manager.","exampleCN":"他是党的理论家，而不是管理者。"},{"word":"idea","structure":"Greek ἰδέα, through Latin idea","meaning":"a thought or a mental form","meaningCN":"想法；心智中的形相","example":"The idea came to her in the shower.","exampleCN":"这个想法是她在淋浴时想到的。"},{"word":"ideal","structure":"Late Latin idealis, from idea","meaning":"a standard of perfection","meaningCN":"完美的标准","example":"The design aims at an ideal of simplicity.","exampleCN":"这个设计追求一种简洁的理想。"},{"word":"idealism","structure":"ideal + -ism (system suffix)","meaning":"the belief that reality is grounded in mind","meaningCN":"认为实在以心灵为基础的信念","example":"German idealism reshaped philosophy.","exampleCN":"德国唯心主义重塑了哲学。"},{"word":"ideologically","structure":"ideological + -ly (adverb)","meaning":"from the standpoint of a belief system","meaningCN":"从信念体系的立场看","example":"The paper is ideologically committed.","exampleCN":"这家报纸在意识形态上有明确承诺。"},{"word":"ideational","structure":"idea + -tional (adjective suffix)","meaning":"relating to the forming of ideas","meaningCN":"与观念形成有关的","example":"Ideational fluency is tested by listing uses.","exampleCN":"观念流畅性通过列举用途来测试。"}],"latinEntries":[{"word":"idea","structure":"Latin borrowing of Greek ἰδέα","meaning":"form, appearance, notion","meaningCN":"形相；外观；观念"},{"word":"idealis","structure":"Medieval Latin, idea + -alis","meaning":"existing in idea or ideal form","meaningCN":"存在于观念或理想形态中的"}]}},{"word":"illustration","ipa_uk":"/ˌɪləˈstreɪʃn/","ipa_us":"/ˌɪləˈstreɪʃn/","definition_zh":"插图；图解；例证；举例说明","definition_en":"a picture that explains or decorates a text, or an example used to make a statement clear","core_image":"一束光打到例子上，原本抽象的规则忽然看得见","scene":"The field guide explains each species with a careful illustration of its leaves and flowers.","sceneCN":"这里 illustration 是「书中的插图」（第 1 个义项：解释或装饰文字的图画）；句意：这本野外指南用精细的叶与花的插图来说明每个物种。图中可辨识物件：翻开的图鉴、一支放大绘制的花、旁边的文字块。","pos":[{"tag":"n.","zh":"插图；图解；例证；说明"}],"collocations":[{"phrase":"book illustration","zh":"书籍插图"},{"phrase":"by way of illustration","zh":"作为例证"},{"phrase":"a clear illustration of","zh":"对……的清楚例证"},{"phrase":"botanical illustration","zh":"植物学插图"},{"phrase":"illustration and text","zh":"插图与文字"},{"phrase":"serve as an illustration","zh":"充当例证"}],"forms":[{"label":"单数","form":"illustration"},{"label":"复数","form":"illustrations"},{"label":"动词","form":"illustrate"}],"derivatives":[{"word":"illustrate","pos":"v.","zh":"说明；举例；给……加插图"},{"word":"illustrative","pos":"adj.","zh":"说明性的；作为例证的"},{"word":"illustrator","pos":"n.","zh":"插画家"},{"word":"illustrious","pos":"adj.","zh":"杰出的；著名的"}],"senses":[{"no":"01","title":"A picture inside a text","titleCN":"书刊中的插图","definition":"a drawing or picture that accompanies and explains or decorates a text","definitionCN":"伴随文字、用于解释或装饰的图画","example":"Every chapter opens with a full-page illustration.","exampleCN":"每一章都以一幅整页插图开篇。","why":"Illustrare meant 'to light up'. A picture lights up a page: it makes the words visible in another medium.","whyCN":"illustrare 意为“照亮”。插图就是把书页照亮：它让文字以另一种媒介变得可见。"},{"no":"02","title":"An example that clarifies","titleCN":"用以说明的例证","definition":"a case or example offered to make a general statement understandable","definitionCN":"为使一般性陈述易于理解而给出的案例或例子","example":"He offered the drought as an illustration of poor planning.","exampleCN":"他以这场干旱作为规划不善的例证。","why":"The 'lighting up' now falls on an abstract rule: the example is the lamp placed beside a sentence that would otherwise stay dark.","whyCN":"这里的“照亮”落在抽象规则上：例子就是一盏放在句子旁边的灯，否则那句句子会一直暗着。"},{"no":"03","title":"The act of making something clear","titleCN":"阐明、说明的行为","definition":"the activity of explaining or clarifying a subject","definitionCN":"解释或澄清某个主题的活动","example":"The lecture relied on illustration rather than formal proof.","exampleCN":"这场讲座靠阐明而非形式证明。","why":"The suffix -ation turns the verb into a process noun, so the word can name the whole activity of shedding light, not just the lamp.","whyCN":"后缀 -ation 把动词变成过程名词，所以这个词可以命名整个“投光”活动，而不只是那盏灯。"},{"no":"04","title":"A diagram of how something works","titleCN":"示意性图解","definition":"a technical drawing that shows the parts or working of an object","definitionCN":"显示某物部件或运作方式的技术图","example":"The cross-section illustration shows each layer of the wall.","exampleCN":"剖面图解展示了墙体的每一层。","why":"Technical use narrows the picture to structure: the drawing is not decoration but a map of parts, drawn so that the unseen can be inspected.","whyCN":"技术用法把图画收窄到结构：这不是装饰，而是部件地图，画出来是为了检查看不见的部分。"},{"no":"05","title":"A drawn record in science","titleCN":"科学著作中的图示","definition":"a precise drawing that records the features of a specimen","definitionCN":"精确记录标本特征的绘图","example":"The botanical illustration records every vein of the leaf.","exampleCN":"这幅植物学图示记录了叶片的每一条叶脉。","why":"Before photography, the illustration was the scientific record. The word carries that responsibility: the drawing must be accurate enough to stand in for the object.","whyCN":"在摄影术之前，图示就是科学记录。这个词承担着那份责任：图必须准确到可以代替实物。"},{"no":"06","title":"A telling case of a trend","titleCN":"能说明趋势的典型事例","definition":"a case that is typical enough to stand for a wider pattern","definitionCN":"足以代表更广模式的典型事例","example":"Her career is an illustration of how effort and luck combine.","exampleCN":"她的职业生涯说明了努力与运气如何结合。","why":"Here the example is not chosen to decorate but to be representative. One case is lit up so that the whole pattern becomes visible.","whyCN":"这里的例子不是用来装点，而是用来代表整体。一个案例被照亮，整个模式就变得可见。"},{"no":"07","title":"Artwork made for publication","titleCN":"出版物中的美术插图","definition":"the artistic drawings or pictures commissioned for a magazine or book","definitionCN":"为杂志或书籍委托创作的艺术图画","example":"The magazine's illustrations set its visual tone.","exampleCN":"这家杂志的插图定下了它的视觉基调。","why":"Commercial art gave the word its professional sense: illustration became a trade, with illustrators as the people who light up pages for a living.","whyCN":"商业美术赋予这个词职业义：illustration 成了一种行当，插画家就是以照亮书页为生的人。"},{"no":"08","title":"Exemplifying as a rhetorical move","titleCN":"修辞上的例示手法","definition":"in writing and speech, the technique of supporting a claim with instances","definitionCN":"在写作与言谈中，用实例支撑论断的技巧","example":"Illustration by anecdote is his favourite device.","exampleCN":"用轶事来例示是他最爱的修辞手法。","why":"Rhetoric names the move separately: the speaker does not merely give an example but organizes the argument around lit-up instances.","whyCN":"修辞学把这个动作单独命名：说话者不只是给个例子，而是围绕被照亮的实例来组织论证。"}],"etymology":{"intro":{"en":"Illustration comes from Latin illustrare, 'to light up, to make bright, to make clear'. The word begins with light and ends with explanation: a picture or an example is a lamp held next to something we could not otherwise see.","cn":"illustration 来自拉丁语 illustrare“照亮、使明亮、使清楚”。这个词以光开始，以解释结束：一幅图或一个例子，就是一盏举在我们原本看不见之处的灯。"},"items":[{"era":"LATIN lustrare (source uncertain)","en":"Lustrare meant 'to purify, to illuminate'. Its link to lustrum, the five-year purification census, is generally accepted, but whether the 'light' sense grew out of the rite or out of an older root for brightness is uncertain.","cn":"lustrare 意为“净化、照亮”。它与 lustrum（五年一次的净化户籍仪式）的联系一般被接受，但“明亮”义是出于仪式还是出自更早的“光亮”词根，来源不确定。"},{"era":"LATIN in- + lustrare","en":"The prefix in- here is intensive rather than negative: illustrare is 'to throw light upon', not 'to light badly'. English in- in this word never means 'not'.","cn":"这里的 in- 是加强前缀而非否定前缀：illustrare 是“把光照上去”，不是“照得不好”。这个词里的 in- 从不表示“不”。"},{"era":"LATIN illustris / illustratio","en":"Illustris meant 'bright, clear, famous', the source of English illustrious. The noun illustratio named the act of making bright or clear.","cn":"illustris 意为“明亮的、清楚的、著名的”，是英语 illustrious 的来源。名词 illustratio 指使明亮或使清楚的行为。"},{"era":"14C. FRENCH illustration","en":"Old French illustration named spiritual enlightenment before it named a picture. Middle English used the word for 'a making clear' in learned writing.","cn":"古法语 illustration 最早指精神上的启迪，之后才指图画。中古英语在学术写作中用这个词表示“阐明”。"},{"era":"17C.–18C. THE PICTURE SENSE","en":"Printing and engraving gave the word its everyday meaning: an illustration is a picture printed beside the text. Booksellers advertised 'with illustrations' as a selling point.","cn":"印刷与版画赋予这个词日常义：illustration 是印在文字旁的画。书商把“附插图”当作卖点来宣传。"},{"era":"19C. SCIENCE AND PRESS","en":"Botanical and anatomical illustration became a profession, and the illustrated magazine made the word part of popular culture.","cn":"植物学与解剖学插图成为专业，画报则让这个词进入大众文化。"}]},"similar":{"note":{"en":"The look-alike group separates the verb, the adjective and the famous cousin all built on the same Latin light-root. The meaning group compares kinds of visual and verbal explanation.","cn":"形近组区分同一拉丁“光”词根上的动词、形容词与那位著名的远亲；词义组比较不同形式的视觉与言语说明。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"illustrate","ipa":"/ɪˈlʌstreɪt/","tag":"verb","definition":"to explain with examples or to add pictures to a text. It is the action behind the noun.","definitionCN":"用例子说明，或给文字加插图。它是名词背后的动作。"},{"word":"illustrative","ipa":"/ɪˈlʌstrətɪv/","tag":"adjective","definition":"serving as an example or explanation. It describes the function of a case, not the artwork itself.","definitionCN":"起例证或说明作用的。它描述案例的功能，而非图画作品。"},{"word":"illustrious","ipa":"/ɪˈlʌstriəs/","tag":"adjective","definition":"famous and respected. It keeps only the 'bright' half of the Latin word and has lost the teaching function.","definitionCN":"著名且受人尊敬的。它只保留了拉丁词中“明亮”的一半，已丢掉教学功能。"}]},{"heading":"NEAR MEANING","entries":[{"word":"picture","ipa":"/ˈpɪktʃə/","tag":"general image","definition":"any image of something. It is the broad word; an illustration is a picture with a job to do in a text.","definitionCN":"任何事物的图像。它是宽泛的词；illustration 是在文本中承担任务的图画。"},{"word":"diagram","ipa":"/ˈdaɪəɡræm/","tag":"schematic drawing","definition":"a simplified drawing showing structure or relations. It is a kind of illustration, but always technical and never decorative.","definitionCN":"显示结构或关系的简化图。它是插图的一种，但始终技术化，从不装饰。"},{"word":"example","ipa":"/ɪɡˈzɑːmpl/","tag":"instance","definition":"a single case offered as evidence. It is the verbal counterpart of sense 02, without the image of light.","definitionCN":"作为证据给出的单个案例。它是第 2 义项在言语上的对应词，但不带“光”的意象。"},{"word":"depiction","ipa":"/dɪˈpɪkʃn/","tag":"portrayal","definition":"the act of representing something in words or images. It stresses representation, while illustration stresses explanation.","definitionCN":"用文字或图像表现某物的行为。它强调表现，而 illustration 强调解释。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks build illustration from Latin lustrare, 'to light', and let the lamp image cover pictures, examples, diagrams and rhetoric.","cn":"这些记忆钩从拉丁语 lustrare“照亮”搭起 illustration，再用“灯”的意象覆盖图画、例子、图解与修辞。"},"normal":[{"en":"Remember in- + lustrare: to throw light on. Illustration is light thrown, then frozen into a picture.","cn":"记住 in- 加 lustrare：把光照上去。illustration 就是投出去的光，后来凝固成一幅画。"},{"en":"Picture a lamp held beside a difficult sentence: that lamp is the example.","cn":"想象一盏灯举在难句旁边：这盏灯就是例子。"},{"en":"In a manual, the diagram is the lamp aimed at the machine's inside.","cn":"在手册里，图解就是把灯照向机器内部。"},{"en":"Before photography, a botanical drawing was the light that let faraway readers see the plant.","cn":"在摄影之前，植物绘图就是让远方读者看见那株植物的光。"},{"en":"Remember the family: illustrate the verb, illustration the noun, illustrious the one who only kept the shine.","cn":"记住这一家：illustrate 是动词，illustration 是名词，illustrious 只留下了光亮。"}],"abstract":[{"en":"Keep one operation: something invisible is given a surface on which it can be seen.","cn":"只记一个动作：给看不见的东西一个可供观看的表面。"},{"en":"Treat every sense as the same question: what is being lit, and for whom?","cn":"把每个义项都当作同一个问题：照亮的是什么，照给谁看？"},{"en":"Notice that decoration and explanation use the same word; only the purpose differs.","cn":"注意装饰与解释用的是同一个词，差别只在目的。"}]},"examples":[{"en":"The textbook uses diagrams by way of illustration.","cn":"这本教科书用图解作为说明。"},{"en":"His failure is an illustration of how quickly markets can turn.","cn":"他的失败说明了市场能多快转向。"},{"en":"The illustrator spent a year on the plates for the atlas.","cn":"这位插画家花了一年绘制图集的图版。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“一乐死吹神”：一图在手，乐得直吹，把道理照得神清气爽——插图就是那盏灯。","word":"illustration"},"root":"拉丁语 illustrare“照亮、使清楚”（in- 加强 + lustrare 照亮），名词 illustratio；经法语 illustration 进入英语，先指“阐明”，17 世纪后固定为“插图”。lustrare 与 lustrum 的关系存在争议，已标注存疑。","sensesIntro":{"en":"Everything here is a lamp. In one sense the lamp is a printed picture; in another it is an example, a diagram, a botanical drawing, a representative career or a rhetorical device. The eight senses differ in what is being lit and who holds the light, not in the operation itself.","cn":"这里的一切都是一盏灯。在一个义项里，灯是印出的图画；在另一个义项里，灯是一个例子、一张图解、一幅植物绘图、一段有代表性的经历，或一种修辞手法。八个义项的差别只在于照亮什么、谁举着灯，而不在动作本身。"},"semanticMap":{"core":{"en":"Throwing light on something so that it becomes visible to another mind.","cn":"把光照在某物上，使它对另一颗心灵变得可见。"},"chain":["LIGHT","SHOW","CLARIFY","PICTURE","EXAMPLE","EXPLAIN"],"branches":[{"senses":"S1 · S7","en":"PAGES: printed artwork that decorates or explains a text.","cn":"书页：装饰或解释文本的印刷图画。"},{"senses":"S2 · S6","en":"CASES: an instance lit up so a rule or trend becomes visible.","cn":"案例：被照亮的一个实例，使规则或趋势可见。"},{"senses":"S3 · S8","en":"ACTS: the activity of clarifying, in a lecture or in an argument.","cn":"行为：在讲座或论证中澄清的过程。"},{"senses":"S4","en":"STRUCTURE: a technical drawing of parts and workings.","cn":"结构：显示部件与运作的技术图。"},{"senses":"S5","en":"SCIENCE: a drawing precise enough to replace the specimen.","cn":"科学：精确到可以代替标本的绘图。"}]},"affixes":{"intro":{"en":"Illustration is in- plus lustrare plus -ation. The items below show the verb, the adjective, the artist and the famous cousin, and show how the same light-root produces words about fame.","cn":"illustration 是 in- 加 lustrare 再加 -ation。下列条目展示动词、形容词、插画家与那位著名的远亲，并展示同一“光”词根如何造出关于名声的词。"},"latinIntro":{"en":"The Latin entries give the verb and its two derived forms. They explain the double life of the family: illustrare clarifies, while illustris merely shines.","cn":"拉丁语条目给出动词及其两个派生形式。它们解释了这一家族的双重面貌：illustrare 负责澄清，illustris 只负责发亮。"},"items":[{"word":"illustration","structure":"illustrare + -atio (process noun)","meaning":"a clarifying picture or example","meaningCN":"起说明作用的图画或例子","example":"The report includes an illustration of the process.","exampleCN":"报告附有该流程的图示。"},{"word":"illustrate","structure":"Latin illustrare, 'to light up'","meaning":"to clarify with examples or pictures","meaningCN":"用例子或图画说明","example":"A single case can illustrate the rule.","exampleCN":"一个案例就能说明这条规则。"},{"word":"illustrative","structure":"illustrate + -ive (adjective suffix)","meaning":"serving as an explanation","meaningCN":"起说明作用的","example":"The numbers are illustrative, not final.","exampleCN":"这些数字仅作说明，并非最终数据。"},{"word":"illustrator","structure":"illustrate + -or (agent noun)","meaning":"a person who draws for publication","meaningCN":"为出版物绘图的人","example":"The book's illustrator also designed the cover.","exampleCN":"这本书的插画家也设计了封面。"},{"word":"illustrious","structure":"Latin illustris + -ous","meaning":"famous and admired","meaningCN":"著名且受人敬仰的","example":"She came from an illustrious family.","exampleCN":"她出身于一个显赫家族。"},{"word":"unillustrated","structure":"un- (negation) + illustrated","meaning":"having no pictures","meaningCN":"没有插图的","example":"The first edition was unillustrated.","exampleCN":"第一版没有插图。"},{"word":"illustratively","structure":"illustrative + -ly (adverb)","meaning":"in a way that explains by example","meaningCN":"以举例说明的方式","example":"The data are presented illustratively.","exampleCN":"这些数据以示例方式呈现。"},{"word":"lustre","structure":"French lustre, from Italian lustro, from lustrare","meaning":"a shine or glory","meaningCN":"光泽；荣光","example":"The old silver still had its lustre.","exampleCN":"旧银器仍带着光泽。"}],"latinEntries":[{"word":"lustrare","structure":"verb, from lustrum (source uncertain)","meaning":"to purify; to illuminate","meaningCN":"净化；照亮"},{"word":"illustrare","structure":"in- (intensive) + lustrare","meaning":"to light up; to make clear","meaningCN":"照亮；使清楚"},{"word":"illustratio","structure":"illustrare + -tio (noun)","meaning":"a making bright or clear","meaningCN":"使明亮或清楚的行为"}]}},{"word":"illustrative","ipa_uk":"/ɪˈlʌstrətɪv/","ipa_us":"/ɪˈlʌstrətɪv/","definition_zh":"说明性的；作为例证的；配有图解的；有代表性的","definition_en":"serving to explain or exemplify something, often by being a typical case","core_image":"一个被举起来的样本：它不是在装饰，而是在替整套规律作证","scene":"The case is illustrative rather than decisive: it shows how the rule works, but does not prove it.","sceneCN":"这里 illustrative 是「作为例证的」（第 2 个义项：以典型个案说明一般规律）；句意：这个案例是示例性的而非决定性的：它显示规则如何运作，却不证明规则。图中可辨识物件：一只被举起的标本瓶、指向它的箭头、旁边未完成的推理链条。","pos":[{"tag":"adj.","zh":"说明性的；示例的；图解的；有代表性的"}],"collocations":[{"phrase":"illustrative example","zh":"说明性例子"},{"phrase":"illustrative of","zh":"足以说明……的"},{"phrase":"purely illustrative","zh":"纯属示例的"},{"phrase":"illustrative material","zh":"说明材料"},{"phrase":"illustrative figures","zh":"示意数据"},{"phrase":"illustrative case","zh":"示例个案"}],"forms":[{"label":"原级","form":"illustrative"},{"label":"比较级","form":"more illustrative"},{"label":"最高级","form":"most illustrative"},{"label":"副词","form":"illustratively"}],"derivatives":[{"word":"illustrate","pos":"v.","zh":"说明；举例；加插图"},{"word":"illustration","pos":"n.","zh":"插图；例证"},{"word":"illustrator","pos":"n.","zh":"插画家"},{"word":"illustratively","pos":"adv.","zh":"以示例方式"}],"senses":[{"no":"01","title":"Serving to explain","titleCN":"起说明作用的","definition":"helping to make a statement or process easier to understand","definitionCN":"有助于使某项陈述或过程更易理解的","example":"He added an illustrative example at the end of the talk.","exampleCN":"他在讲座末尾补了一个说明性例子。","why":"The suffix -ive turns the act of lighting into a quality. Something illustrative does the lighting; it is not the thing lit.","whyCN":"后缀 -ive 把“照亮”的动作变成一种性质。illustrative 的东西负责照亮，而不是被照亮。"},{"no":"02","title":"Standing as a typical case","titleCN":"作为例证代表的","definition":"being a case that represents a wider pattern","definitionCN":"作为一个能代表更广模式的案例","example":"The episode is illustrative of a wider change in the industry.","exampleCN":"这一事件足以说明整个行业更广的变化。","why":"Here the sample is chosen because it is typical. It does not decorate the argument; it stands in for the whole, like a core sample.","whyCN":"这里选这个样本是因为它有代表性。它不装饰论证，而是代替整体，像一根岩芯样本。"},{"no":"03","title":"Containing pictures","titleCN":"配有图解的","definition":"including drawings or diagrams that explain the text","definitionCN":"含有解释文字的图画或图表的","example":"The publisher issued an illustrative guide for beginners.","exampleCN":"出版方为初学者发行了一本配图指南。","why":"The adjective takes the picture sense of the noun and applies it to a whole work: a book can be illustrative in its design, not only in one page.","whyCN":"这个形容词取了名词的“图画”义，并把它用于整部作品：一本书可以在整体设计上就是图示性的，而不只在某一页。"},{"no":"04","title":"Useful in teaching","titleCN":"有教学示范价值的","definition":"clear enough to be used as a teaching demonstration","definitionCN":"清楚到可以用作教学示范的","example":"The experiment is illustrative for first-year students.","exampleCN":"这个实验对一年级学生有示范价值。","why":"Teaching selects cases that carry the whole method on their surface. Illustrative here means 'small enough to hold, complete enough to show the whole'.","whyCN":"教学会挑那些把整套方法摊在表面的案例。这里的 illustrative 意为“小到可以握住，完整到能显示整体”。"},{"no":"05","title":"Merely exemplary, not exhaustive","titleCN":"仅作示例、并非穷尽的","definition":"given as a sample only, with no claim to completeness","definitionCN":"只作为样本给出，并不声称完整","example":"The list is illustrative, not complete.","exampleCN":"这份清单只是示例，并不完整。","why":"This use is a disclaimer. It marks the boundary of the claim: what follows shows the kind, not the full set.","whyCN":"这种用法是一种免责声明。它标记论断的边界：下面给出的是种类，而不是全集。"},{"no":"06","title":"Belonging to the illustrator's style","titleCN":"属于插图风格的","definition":"characteristic of drawing made for books or magazines","definitionCN":"具有为书籍或杂志绘制的图画特征的","example":"Her illustrative work appears in several magazines.","exampleCN":"她的插图作品出现在几家杂志上。","why":"The adjective becomes a style label: work made to accompany text has its own line, colour and composition.","whyCN":"这个形容词变成了风格标签：为陪伴文字而作的画，有自己的线条、色彩与构图。"},{"no":"07","title":"Clarifying by comparison","titleCN":"修辞上用于阐明的","definition":"used of comparisons or images that make an argument vivid","definitionCN":"用于使论证生动的比喻或意象","example":"His illustrative comparisons made the argument easy to follow.","exampleCN":"他那些用于说明的比喻让论证容易跟上。","why":"A comparison is a lamp in the medium of language. The adjective says the comparison exists to clarify, not to ornament.","whyCN":"比喻是语言媒介中的一盏灯。这个形容词说明该比喻的存在是为了澄清，而不是为了装饰。"},{"no":"08","title":"Explanatory in technical reports","titleCN":"技术文件中用于示意的","definition":"in reports, describing figures that show how a system works","definitionCN":"报告中描述展示系统运作方式的图","example":"The illustrative diagrams show the flow of data.","exampleCN":"示意图标示了数据的流动。","why":"Technical writing separates the measured from the shown. Illustrative figures are drawn to explain, so they must not be read as results.","whyCN":"技术写作把“测得的”与“画出的”分开。示意数据是为了解释而绘制，因此不能被当作结果来读。"}],"etymology":{"intro":{"en":"Illustrative is illustrate plus -ive, a suffix that turns an action into a quality. It inherits the Latin verb illustrare, 'to light up', and therefore describes anything that does the lighting rather than the thing lit.","cn":"illustrative 是 illustrate 加 -ive，后者把动作变成性质。它继承了拉丁语动词 illustrare“照亮”，因此描述的是负责照光的东西，而不是被照亮的东西。"},"items":[{"era":"LATIN lustrare (source uncertain)","en":"Lustrare combined purification and brightness. Whether the bright sense came from the lustrum rite or from an older root is uncertain, so the deep origin is labelled as debated.","cn":"lustrare 兼有净化与明亮。明亮义出自 lustrum 仪式还是出自更早词根，来源不确定，故深层来源标注为有争议。"},{"era":"LATIN illustrare","en":"In- strengthened the verb: illustrare meant 'to throw light on, to make clear, to distinguish'. Its participle illustrans described the thing doing the lighting.","cn":"in- 加强了动词：illustrare 意为“把光照上去、使清楚、使显眼”。其分词 illustrans 描述正在照光的事物。"},{"era":"LATIN -ivus","en":"The suffix -ivus built adjectives of tendency, as in activus and effectivus. English -ive inherited that force: a quality that tends to act or to produce an effect.","cn":"后缀 -ivus 构成表示倾向的形容词，如 activus、effectivus。英语 -ive 继承了这股力量：倾向于做出动作或产生效果的性质。"},{"era":"17C. ENGLISH illustrate + -ive","en":"English formed illustrative on the model of French illustratif. Early uses concerned 'serving to elucidate', before the picture sense appeared.","cn":"英语仿法语 illustratif 造出 illustrative。早期用法是“有助于阐明”，之后才出现图画义。"},{"era":"18C.–19C. EDUCATION AND SCIENCE","en":"Scientific plates and teaching manuals made illustrative a standard label for figures and examples that exist to explain, not to measure.","cn":"科学图版与教学手册使 illustrative 成为标准标签，专指标示与例子，其存在是为了解释而非测量。"},{"era":"20C. DISCLAIMER USE","en":"In reports and legal texts, 'illustrative only' became a fixed phrase protecting the writer from the charge of claiming completeness.","cn":"在报告与法律文本中，“仅作示例”成了固定说法，保护作者不被指为声称完整。"}]},"similar":{"note":{"en":"The look-alike group separates the verb, the noun and this adjective, all on the same light-root. The meaning group compares words that explain by showing.","cn":"形近组区分同一“光”词根上的动词、名词与本形容词；词义组比较“靠展示来解释”的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"illustrate","ipa":"/ɪˈlʌstreɪt/","tag":"verb","definition":"to clarify with pictures or examples. The adjective describes what such an act produces.","definitionCN":"用图画或例子澄清。形容词描述这种行为所产生的性质。"},{"word":"illustration","ipa":"/ˌɪləˈstreɪʃn/","tag":"noun","definition":"a picture or an example used to explain. It is the object, while illustrative is the quality.","definitionCN":"用于解释的图画或例子。它是对象，而 illustrative 是性质。"},{"word":"lustrous","ipa":"/ˈlʌstrəs/","tag":"adjective","definition":"shining, glossy. It keeps only the surface brightness of the root and has no explanatory force.","definitionCN":"有光泽的、光亮的。它只保留词根的表面亮度，没有解释功能。"}]},{"heading":"NEAR MEANING","entries":[{"word":"explanatory","ipa":"/ɪˈsplænətəri/","tag":"explaining","definition":"intended to make something understood. It is close to sense 01 but simply means 'explanatory', without the idea of an example.","definitionCN":"意在使人理解的。它接近第 1 义项，但只表示“解释性的”，不含“举例”之意。"},{"word":"representative","ipa":"/ˌreprɪˈzentətɪv/","tag":"standing for others","definition":"typical of a larger group. It stresses sameness of type, while illustrative stresses the power to show how something works.","definitionCN":"能代表更大群体的。它强调类型相同，而 illustrative 强调显示运作方式的能力。"},{"word":"demonstrative","ipa":"/dɪˈmɒnstrətɪv/","tag":"showing","definition":"showing something clearly, or openly expressing feeling. The teaching sense overlaps, but it also names an emotional style.","definitionCN":"清楚展示某物，或公开表达感情。教学义重叠，但它还指一种情感风格。"},{"word":"schematic","ipa":"/skiːˈmætɪk/","tag":"simplified","definition":"shown in simplified form, often as a diagram. It describes the drawing's style, not its purpose.","definitionCN":"以简化形式呈现，常为图解。它描述图稿的风格，而非目的。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks build illustrative from illustrate plus -ive and keep the lamp image: something illustrative is the lamp, not the wall it lights.","cn":"这些记忆钩从 illustrate 加 -ive 搭起 illustrative，并保留“灯”的意象：illustrative 的东西是灯，不是被它照亮的墙。"},"normal":[{"en":"See -ive: the word names a quality. An illustrative case carries the power to light up a rule.","cn":"看见 -ive：这个词命名一种性质。说明性案例带着照亮规则的力量。"},{"en":"Picture a sample bottle lifted above a table: everyone understands the whole category by looking at it.","cn":"想象一只样本瓶被举到桌面上方：所有人一看就懂了整个类别。"},{"en":"A textbook figure is illustrative; a measured data point is evidential. Keep the two apart.","cn":"教科书里的图是示意性的；实测数据点才是证据性的。要把两者分开。"},{"en":"When a list is called illustrative, its author is warning you not to count it.","cn":"当一份清单被称为 illustrative 时，作者是在提醒你别拿它当全集来数。"},{"en":"Remember the family: illustrate acts, illustration objects, illustrative qualifies.","cn":"记住这一家：illustrate 是动作，illustration 是对象，illustrative 是性质。"}],"abstract":[{"en":"Keep one relation: the part chosen so that the whole can be seen through it.","cn":"只记一种关系：选出局部，使整体能透过它被看见。"},{"en":"Treat the word as a claim about purpose, never about proof.","cn":"把这个词当作关于目的的声明，而不是关于证明的声明。"},{"en":"Notice that a good example is a lens, not a wall: it must let the rule through.","cn":"注意好例子是镜片而不是墙：它必须让规则透过来。"}]},"examples":[{"en":"The figures are illustrative and should not be quoted as results.","cn":"这些数字是示意性的，不应被当作结果引用。"},{"en":"His career is illustrative of how the profession changed.","cn":"他的职业生涯说明了这个行业如何变化。"},{"en":"The manual is heavily illustrative, with a diagram on every spread.","cn":"这本手册图很多，每个跨页都有一张图。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“一乐死吹提夫”：一个例子讲得乐、吹得响，就把道理提了起来——正是说明性的。","word":"illustrative"},"root":"拉丁语 illustrare“照亮、使清楚”加形容词后缀 -ivus（英语 -ive）构成；法语 illustratif 提供了构词模型，17 世纪进入英语，义为“有助于阐明的”。","sensesIntro":{"en":"Illustrative never means 'proven'. It means 'this shows you how'. The eight senses divide that showing into an explanatory quality, a representative case, a picture-filled book, a teaching demo, a disclaimer of incompleteness, a drawing style, a clarifying comparison and a technical figure. In every one, the word points at purpose.","cn":"illustrative 从来不是“已证明”的意思，而是“这让你看见怎么运作”。八个义项把这种“展示”分成：解释性质、代表性案例、配图的书、教学示范、不完整的免责、绘图风格、澄清性比喻、技术示意图。每一个义项都指向目的。"},"semanticMap":{"core":{"en":"Having the power to make something visible or understandable.","cn":"具备使某物可见或可理解的力量。"},"chain":["LIGHT","SHOW","TYPICAL","EXPLAIN","SAMPLE","STYLE"],"branches":[{"senses":"S1 · S4","en":"TEACHING: explanation and demonstration that a learner can follow.","cn":"教学：学习者能跟上的解释与示范。"},{"senses":"S2 · S7","en":"ARGUMENT: a case or comparison that carries a rule.","cn":"论证：承载规则的案例或比喻。"},{"senses":"S3 · S6","en":"DESIGN: books and drawings made to accompany text.","cn":"设计：为陪伴文字而作的书与画。"},{"senses":"S5","en":"BOUNDARY: a sample that disclaims completeness.","cn":"边界：声明并不完整的样本。"},{"senses":"S8","en":"TECHNIQUE: figures drawn to show flow, not results.","cn":"技术：为显示流程而非结果绘制的图。"}]},"affixes":{"intro":{"en":"Illustrative is illustrate plus -ive. The items below gather the same light-root family and then show -ive at work in words that name tendencies rather than acts.","cn":"illustrative 是 illustrate 加 -ive。下列条目先汇总同一“光”词根家族，再展示 -ive 在表示倾向而非动作的词中如何工作。"},"latinIntro":{"en":"The Latin entries give the verb and the suffix separately. Together they explain why the adjective describes a tendency to light rather than a completed act.","cn":"拉丁语条目分别给出动词与后缀。两者合起来解释了为什么这个形容词描述照光的倾向，而不是已完成的动作。"},"items":[{"word":"illustrative","structure":"illustrate + -ive (tendency adjective)","meaning":"serving to explain or exemplify","meaningCN":"起解释或例证作用的","example":"The chart is illustrative of the trend.","exampleCN":"这张图说明了该趋势。"},{"word":"illustrate","structure":"Latin illustrare, 'to light up'","meaning":"to make clear by example or picture","meaningCN":"用例子或图画使清楚","example":"The story illustrates the risk clearly.","exampleCN":"这个故事清楚说明了风险。"},{"word":"illustration","structure":"-ation process noun","meaning":"a picture or an example that explains","meaningCN":"起解释作用的图画或例子","example":"The lecture used one illustration after another.","exampleCN":"讲座一个接一个地使用例证。"},{"word":"illustrator","structure":"-or agent noun","meaning":"one who draws for texts","meaningCN":"为文本绘图的人","example":"The illustrator revised the plates twice.","exampleCN":"插画家两次修改了图版。"},{"word":"illustriously","structure":"illustrious + -ly","meaning":"in a celebrated manner","meaningCN":"以显赫的方式","example":"The family served the state illustriously.","exampleCN":"这个家族显赫地报效国家。"},{"word":"illustriousness","structure":"illustrious + -ness","meaning":"the state of being famous","meaningCN":"著名的状态","example":"The prize confirmed his illustriousness.","exampleCN":"该奖项确认了他的显赫。"},{"word":"unillustrative","structure":"un- (negation) + illustrative","meaning":"failing to clarify","meaningCN":"未能起说明作用的","example":"The answer was long but unillustrative.","exampleCN":"这个回答很长，却毫无说明力。"},{"word":"illustrated","structure":"illustrate + -ed (participial adjective)","meaning":"supplied with pictures","meaningCN":"配有图画的","example":"They bought the illustrated edition.","exampleCN":"他们买了插图版。"}],"latinEntries":[{"word":"illustrare","structure":"in- (intensive) + lustrare","meaning":"to light up; to make clear","meaningCN":"照亮；使清楚"},{"word":"illustris","structure":"adjective from the same light-root","meaning":"bright; famous","meaningCN":"明亮的；著名的"},{"word":"-ivus","structure":"adjective-forming suffix","meaning":"tending to, capable of","meaningCN":"倾向于……的；能……的"}]}},{"word":"imbalance","ipa_uk":"/ɪmˈbæləns/","ipa_us":"/ɪmˈbæləns/","definition_zh":"失衡；不平衡；比例失调；失调状态","definition_en":"a state in which parts are not equal, or in which one side has too much weight, power or quantity","core_image":"一架天平一头沉下去，另一头翘起来","scene":"The report warns of a growing imbalance between what the city consumes and what it produces.","sceneCN":"这里 imbalance 是「失衡状态」（第 1 个义项：两端不相等）；句意：报告警告这座城市消费与生产之间失衡正在加剧。图中可辨识物件：倾斜的天平、一端堆高的货物、另一端空着的托盘。","pos":[{"tag":"n.","zh":"失衡；不平衡；失调"}],"collocations":[{"phrase":"trade imbalance","zh":"贸易失衡"},{"phrase":"power imbalance","zh":"权力不平衡"},{"phrase":"gender imbalance","zh":"性别比例失衡"},{"phrase":"chemical imbalance","zh":"化学失衡"},{"phrase":"correct an imbalance","zh":"纠正失衡"},{"phrase":"growing imbalance","zh":"日益加剧的失衡"}],"forms":[{"label":"单数","form":"imbalance"},{"label":"复数","form":"imbalances"},{"label":"形容词","form":"imbalanced"}],"derivatives":[{"word":"balance","pos":"n./v.","zh":"平衡；使平衡"},{"word":"balanced","pos":"adj.","zh":"平衡的；均衡的"},{"word":"imbalanced","pos":"adj.","zh":"失衡的"},{"word":"unbalance","pos":"v.","zh":"使失去平衡"}],"senses":[{"no":"01","title":"Two sides no longer equal","titleCN":"两端不再相等","definition":"a state in which two parts differ in amount, weight or strength","definitionCN":"两部分在数量、重量或强度上不相等状态","example":"There is a clear imbalance between the two budgets.","exampleCN":"两份预算之间有明显失衡。","why":"Balance came from a two-pan scale. The prefix im- denies it, so the word paints the moment one pan sinks.","whyCN":"balance 来自双盘天平。前缀 im- 否定了它，于是这个词画出的是一头沉下去的瞬间。"},{"no":"02","title":"Trade running to one side","titleCN":"贸易与经济失衡","definition":"in economics, a persistent excess of imports over exports or of one region's surplus over another's","definitionCN":"经济学中长期存在的进口大于出口，或一地区盈余高于另一地区","example":"The trade imbalance widened again last quarter.","exampleCN":"上季度贸易失衡再次扩大。","why":"The scale becomes national: goods flow one way and money the other, and the pans never level out.","whyCN":"天平变成了国家尺度：货物流向一边，货币流向另一边，两只托盘始终不能持平。"},{"no":"03","title":"An ecosystem out of tune","titleCN":"生态失衡","definition":"in ecology, a disruption in which populations or resources no longer keep each other in check","definitionCN":"生态学中种群或资源不再相互制约的紊乱","example":"Overfishing caused a lasting imbalance in the reef.","exampleCN":"过度捕捞造成了礁区持久的失衡。","why":"An ecosystem is a set of scales linked together. When one pan drops, the others follow, and the whole arrangement tilts.","whyCN":"生态系统是一组互相连接的天平。一只托盘下沉，其余随之而动，整个装置都倾斜了。"},{"no":"04","title":"Power weighted on one side","titleCN":"权力不平衡","definition":"a situation in which one group holds far more power than another","definitionCN":"一个群体掌握的权力远多于另一群体的局面","example":"The imbalance between employer and worker is structural.","exampleCN":"雇主与工人之间的权力不平衡是结构性的。","why":"The metaphor moves from weight to authority. What tips the scale is no longer goods but the ability to set the terms.","whyCN":"比喻从重量移到权威。压翻天平的不再是货物，而是设定条件的能力。"},{"no":"05","title":"Charge or composition out of balance","titleCN":"化学与电荷失衡","definition":"in chemistry and physics, a condition in which ions, charges or components are not in the required ratio","definitionCN":"化学与物理中离子、电荷或成分未达所需比例的状态","example":"An imbalance of ions changes the reaction rate.","exampleCN":"离子失衡会改变反应速率。","why":"Here the scale is invisible but exact: the two sides must cancel, and the whole system registers every grain that does not.","whyCN":"这里的天平看不见却精确：两侧必须相消，任何一粒没有抵消，整个系统都会记录。"},{"no":"06","title":"A body out of regulation","titleCN":"身体机能失衡","definition":"in medicine, a disturbance in the normal levels of hormones or other substances","definitionCN":"医学中激素或其他物质水平偏离正常导致的紊乱","example":"The illness begins with a hormonal imbalance.","exampleCN":"这种病从激素失衡开始。","why":"The body is described as a set of regulated levels. Illness is the pan that will not come back up.","whyCN":"身体被描述为一组受调节的水平。疾病就是那只再也升不回来的托盘。"},{"no":"07","title":"A mind tipped off centre","titleCN":"心理失衡","definition":"an emotional state in which needs and responses are no longer in proportion","definitionCN":"需求与反应不再成比例的情绪状态","example":"Loss of status can produce a lasting emotional imbalance.","exampleCN":"失去地位可能造成持久的情绪失衡。","why":"The same scale is now internal. Feeling is weighed against circumstance, and the word records the tilt rather than naming a disease.","whyCN":"同一架天平现在移到了内部。感受与环境被放在一起称量，这个词记录的是倾斜，而不是命名某种疾病。"},{"no":"08","title":"Load or proportion wrongly placed","titleCN":"结构中的比例失调","definition":"in engineering, a distribution of weight or material that is not even","definitionCN":"工程中重量或材料分布不均","example":"Engineers found a slight imbalance in the rotor.","exampleCN":"工程师发现转子有轻微失衡。","why":"This is the most literal sense left: a rotating mass whose centre is not where it should be, so every turn shakes.","whyCN":"这是保留得最字面的义项：一个转动体的重心不在应在之处，于是每一转都震动。"}],"etymology":{"intro":{"en":"Imbalance is im- 'not' plus balance, and balance is a pair of pans. Late Latin bilancia meant a two-pan scale, from bilanx, 'having two dishes'. The word therefore begins as an object on a merchant's table and ends as a description of economies, ecosystems and minds.","cn":"imbalance 是 im-“不”加 balance，而 balance 是一对托盘。晚期拉丁语 bilancia 指双盘天平，来自 bilanx“有两个盘子”。所以这个词最初是商人桌上的一件器物，最后成了对经济、生态与心理的描述。"},"items":[{"era":"LATIN lanx (source uncertain)","en":"Lanx meant 'dish, plate, pan of a scale'. Its own origin is uncertain; it may be connected with a root for 'broad dish', but no link is proved.","cn":"lanx 意为“盘、碟、天平托盘”。它自身的来源不确定，可能与表示“宽盘”的词根有关，但未获证实。"},{"era":"LATIN bilanx / bilancia","en":"Bi- 'two' plus lanx 'pan' gave bilanx, 'two-panned'. The Late Latin noun bilancia named the whole instrument and passed into French as balance.","cn":"bi-“二”加 lanx“托盘”构成 bilanx“双盘的”。晚期拉丁名词 bilancia 指整件器具，进入法语作 balance。"},{"era":"13C. FRENCH balance","en":"French balance meant both the scale and the act of weighing. English borrowed it for the instrument, then for equality of weight.","cn":"法语 balance 兼指天平与称量行为。英语借入后先指器具，再指重量相等。"},{"era":"LATIN im- (negation)","en":"The prefix in- assimilates to im- before b, p and m. Here it is privative: it removes the balance rather than repeating it.","cn":"前缀 in- 在 b、p、m 前同化为 im-。这里是剥夺性的：它去掉平衡，而不是重复平衡。"},{"era":"17C. ENGLISH imbalance","en":"Imbalance appears in English in the 17th century, first for physical scales, then for anything measured in two opposing parts.","cn":"imbalance 在 17 世纪进入英语，先指实物天平，后指任何由两个对立部分构成的事物。"},{"era":"20C. ECONOMICS, ECOLOGY AND MEDICINE","en":"Trade imbalance, ecological imbalance and hormonal imbalance each extend the scale into a new domain. The word becomes a general diagnostic for systems that will not level.","cn":"贸易失衡、生态失衡、激素失衡把天平逐一扩展进新领域。这个词成了对“无法持平的系统”的通用诊断。"}]},"similar":{"note":{"en":"The look-alike group separates the base noun, its participle and the negative verb. The meaning group compares words for difference, unevenness and disturbance.","cn":"形近组区分基础名词、其分词与否定动词；词义组比较表示差异、不均与紊乱的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"balance","ipa":"/ˈbæləns/","tag":"noun and verb","definition":"an even distribution, or to make two sides equal. It is the state that imbalance denies.","definitionCN":"均匀分布，或使两侧相等。它是 imbalance 所否认的状态。"},{"word":"imbalanced","ipa":"/ɪmˈbælənst/","tag":"adjective","definition":"showing imbalance; not evenly distributed. It describes a thing, while the noun names the condition.","definitionCN":"显示出失衡的；分布不均的。它描述某物，而名词命名该状态。"},{"word":"unbalance","ipa":"/ʌnˈbæləns/","tag":"verb","definition":"to make something lose its balance. It is an action, not a diagnosis.","definitionCN":"使某物失去平衡。它是动作，而非诊断。"}]},{"heading":"NEAR MEANING","entries":[{"word":"disparity","ipa":"/dɪˈspærəti/","tag":"gap between groups","definition":"a large difference, especially in income or treatment. It stresses the size of the gap; imbalance stresses the failure to level.","definitionCN":"巨大差异，尤指收入或待遇。它强调差距的大小，而 imbalance 强调无法持平。"},{"word":"inequality","ipa":"/ˌiːnɪˈkwɒləti/","tag":"unequal shares","definition":"an unfair difference in status, wealth or opportunity. It adds a judgement of fairness that imbalance need not carry.","definitionCN":"地位、财富或机会上的不公平差异。它加上公平判断，而 imbalance 不必带此判断。"},{"word":"asymmetry","ipa":"/eɪˈsɪmətri/","tag":"lack of mirror form","definition":"a lack of symmetry between two sides. It is structural and neutral, like imbalance in its technical senses.","definitionCN":"两侧缺乏对称。它是结构性、中立的，接近 imbalance 的技术义。"},{"word":"disturbance","ipa":"/dɪˈstɜːbəns/","tag":"disruption","definition":"an interruption of normal working. It fits the medical and ecological senses but suggests an event rather than a standing tilt.","definitionCN":"正常运作被打断。它适合医学与生态义，但暗示某个事件，而非持续倾斜。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks build imbalance from im- 'not' plus a two-pan scale, then let the sinking pan cover trade, ecology, power and the body.","cn":"这些记忆钩从 im-“不”加双盘天平搭起 imbalance，再用沉下去的那只托盘覆盖贸易、生态、权力与身体。"},"normal":[{"en":"See im- + balance: no balance. The word is simply the scale denied.","cn":"看见 im- 加 balance：没有平衡。这个词就是被否定掉的天平。"},{"en":"Picture one pan on the floor and the other in the air: that is every sense at once.","cn":"想象一只托盘落在地上，另一只翘在半空：这同时就是所有义项。"},{"en":"In trade, the sinking pan is the side that keeps buying more than it sells.","cn":"在贸易里，沉下去的那只托盘，是买得多卖得少的那一方。"},{"en":"In an office, the sinking pan is the side that sets the terms.","cn":"在办公室里，沉下去的那只托盘，是能设定条件的那一方。"},{"en":"Remember the word family: balance is the state, imbalance the failure, imbalanced the description.","cn":"记住词族：balance 是状态，imbalance 是失败，imbalanced 是描述。"}],"abstract":[{"en":"Keep one image: a straight beam that has forgotten how to be straight.","cn":"只记一个意象：一根忘了怎么变直的横梁。"},{"en":"Treat the word as a measurement, not an accusation: it tells you which side is heavy.","cn":"把这个词当作测量，而不是指控：它告诉你哪一边重。"},{"en":"Notice that the same tilt can be repaired by removing weight or by adding it to the other side.","cn":"注意同一种倾斜可以靠减重修复，也可以靠给另一边加重修复。"}]},"examples":[{"en":"The trade imbalance between the two countries has narrowed.","cn":"两国之间的贸易失衡有所缩小。"},{"en":"A power imbalance makes genuine consent difficult.","cn":"权力不平衡使真正的同意难以达成。"},{"en":"The test checks for a hormonal imbalance.","cn":"这项检查用来检测激素失衡。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“硬不懒死”：天平硬是不肯懒下来持平，一直斜着——这就是失衡。","word":"imbalance"},"root":"im-（in- 的否定形式，在 b 前同化）加 balance；balance 来自晚期拉丁 bilancia“双盘天平”，源自 bilanx（bi- 二 + lanx 托盘）。lanx 的深层来源不确定，已标注。","sensesIntro":{"en":"Eight senses, one instrument. A beam with two pans appears as a budget, a trade account, a reef, a workplace, a solution of ions, a hormonal system, an emotional life and a spinning rotor. In each case the same thing has happened: the two sides that ought to cancel no longer do, and the whole structure leans.","cn":"八个义项，一件器具。一根带两只托盘的横梁，先后化身为预算、贸易账目、珊瑚礁、工作场所、离子溶液、激素系统、情绪生活与旋转的转子。每种情形里发生的事都一样：本该相消的两侧不再相消，整个结构因此倾斜。"},"semanticMap":{"core":{"en":"A scale that will not come level: one side carries more than the other.","cn":"一架无法持平的天平：一边承载得比另一边多。"},"chain":["SCALE","WEIGHT","DIFFER","TILT","STRAIN","DISORDER"],"branches":[{"senses":"S1 · S8","en":"MECHANICS: unequal amounts and a badly placed load.","cn":"力学：数量不等与载荷位置不当。"},{"senses":"S2","en":"ECONOMY: imports and exports that never level.","cn":"经济：始终无法持平的进出口。"},{"senses":"S3 · S5","en":"NATURE: ecosystems and ions out of their required ratio.","cn":"自然：生态与离子偏离所需比例。"},{"senses":"S4","en":"POWER: one side able to set the terms.","cn":"权力：一方能够设定条件。"},{"senses":"S6 · S7","en":"BODY AND MIND: levels and feelings tipped off centre.","cn":"身心：水平与情绪偏离中心。"}]},"affixes":{"intro":{"en":"Imbalance is a negative prefix plus a borrowed noun. The items below show the scale family, the negation at work, and the adjectives that describe a tipped state.","cn":"imbalance 是一个否定前缀加一个借来的名词。下列条目展示天平词族、否定前缀的作用，以及描述倾斜状态的形容词。"},"latinIntro":{"en":"The Latin entries give the two-pan word and its parts. They explain why balance is not a simple English noun but a machine carried across languages.","cn":"拉丁语条目给出“双盘”这个词及其成分。它们解释了为什么 balance 不是简单的英语名词，而是一台被跨语言搬运的机器。"},"items":[{"word":"imbalance","structure":"im- (negation) + balance","meaning":"a lack of even distribution","meaningCN":"缺乏均匀分布","example":"The survey found an imbalance in staffing.","exampleCN":"调查发现人员配置失衡。"},{"word":"balance","structure":"French balance, from Late Latin bilancia","meaning":"a two-pan scale; equality of weight","meaningCN":"双盘天平；重量相等","example":"She kept her balance on the narrow beam.","exampleCN":"她在窄梁上保持了平衡。"},{"word":"balanced","structure":"balance + -ed (participial adjective)","meaning":"evenly arranged; fair","meaningCN":"安排均匀的；公平的","example":"The article gives a balanced account.","exampleCN":"这篇文章给出了平衡的叙述。"},{"word":"imbalanced","structure":"im- + balanced","meaning":"not evenly arranged","meaningCN":"安排不均的","example":"The diet was badly imbalanced.","exampleCN":"这份饮食严重失衡。"},{"word":"unbalance","structure":"un- (negation) + balance (verb)","meaning":"to throw out of equilibrium","meaningCN":"使失去平衡","example":"One removed weight can unbalance the wheel.","exampleCN":"去掉一个配重就能使车轮失衡。"},{"word":"counterbalance","structure":"counter- (against) + balance","meaning":"a weight or force that offsets another","meaningCN":"抵消另一重量的配重或力量","example":"The second wing acts as a counterbalance.","exampleCN":"第二片机翼起配重作用。"},{"word":"overbalance","structure":"over- (excess) + balance","meaning":"to lose balance by excess, or to outweigh","meaningCN":"因过量而失去平衡，或重于","example":"He overbalanced and fell from the ledge.","exampleCN":"他失去平衡，从台沿跌落。"},{"word":"well-balanced","structure":"well + balanced (compound adjective)","meaning":"properly proportioned","meaningCN":"比例恰当的","example":"A well-balanced portfolio limits risk.","exampleCN":"配置均衡的投资组合能限制风险。"}],"latinEntries":[{"word":"bilanx","structure":"bi- (two) + lanx (pan)","meaning":"having two pans","meaningCN":"有两个托盘的"},{"word":"bilancia","structure":"Late Latin noun from bilanx","meaning":"a two-pan scale","meaningCN":"双盘天平"},{"word":"lanx","structure":"noun, origin uncertain","meaning":"dish; pan of a scale","meaningCN":"盘；天平托盘"}]}},{"word":"implementation","ipa_uk":"/ˌɪmplɪmenˈteɪʃn/","ipa_us":"/ˌɪmplɪmenˈteɪʃn/","definition_zh":"实施；执行；落实；（软件）部署上线；履行","definition_en":"the act or process of putting a plan, policy, system or agreement into actual operation","core_image":"图纸被搬下桌，变成车间里真正转动起来的那条线","scene":"The plan looked simple on paper, but its implementation took two years of retraining.","sceneCN":"这里 implementation 是「计划实施」（第 1 个义项：把方案变成实际运作）；句意：这个计划在纸上看着简单，但实施起来花了两年重新培训。图中可辨识物件：摊开的图纸、卷起的袖口、正在运转的机器、培训名单。","pos":[{"tag":"n.","zh":"实施；执行；落实；履行"}],"collocations":[{"phrase":"policy implementation","zh":"政策执行"},{"phrase":"implementation of a plan","zh":"计划的实施"},{"phrase":"implementation phase","zh":"实施阶段"},{"phrase":"implementation costs","zh":"实施成本"},{"phrase":"full implementation","zh":"全面实施"},{"phrase":"implementation gap","zh":"执行落差"}],"forms":[{"label":"单数","form":"implementation"},{"label":"复数","form":"implementations"},{"label":"动词","form":"implement"}],"derivatives":[{"word":"implement","pos":"v./n.","zh":"实施；执行；工具；器具"},{"word":"implementable","pos":"adj.","zh":"可实施的"},{"word":"implementer","pos":"n.","zh":"实施者"},{"word":"implementing","pos":"adj.","zh":"执行中的"}],"senses":[{"no":"01","title":"Putting a plan into effect","titleCN":"把计划付诸实施","definition":"the process of turning an approved plan into real action","definitionCN":"把已获批准的计划转化为实际行动的过程","example":"Implementation of the new timetable begins in September.","exampleCN":"新时间表的实施从九月开始。","why":"The Latin verb implere means 'to fill up'. A plan is an empty container until implementation fills it with real hours, people and machines.","whyCN":"拉丁动词 implere 意为“填满”。计划在实施之前是个空容器，实施把真实的小时、人和机器填进去。"},{"no":"02","title":"Carrying a policy into practice","titleCN":"政策的执行","definition":"the work of applying a law or official policy in daily administration","definitionCN":"在日常行政中适用法律或官方政策的工作","example":"Local offices are responsible for policy implementation.","exampleCN":"地方办事处负责政策执行。","why":"Here the container is a rule. Implementation is what happens between the text of the rule and the clerk who must apply it.","whyCN":"这里的容器是一条规则。implementation 就是规则文本与必须执行它的办事员之间发生的事。"},{"no":"03","title":"Installing a system in software","titleCN":"软件系统的部署上线","definition":"in computing, the process of making a designed system run in a real environment","definitionCN":"计算机领域把设计好的系统放入真实环境运行的过程","example":"The implementation of the new database took six weeks.","exampleCN":"新数据库的部署用了六周。","why":"Code that only exists in a design document is still empty. Deployment fills the container with running processes and live users.","whyCN":"只存在于设计文档里的代码仍是空的。部署把容器填进正在运行的进程与真实用户。"},{"no":"04","title":"Performing what was agreed","titleCN":"履行约定或协议","definition":"the carrying out of the duties set down in an agreement or contract","definitionCN":"履行协议或合同中规定的义务","example":"The contract's implementation depends on both parties meeting the deadlines.","exampleCN":"合同的履行取决于双方是否按期完成。","why":"A signed agreement is a promise shaped like an empty vessel. Implementation is the behaviour that fills it.","whyCN":"签好的协议是一个空器皿形状的承诺。implementation 就是填满它的行为。"},{"no":"05","title":"Turning a method into classroom practice","titleCN":"教学方法的落地","definition":"in education, the translation of a teaching approach into actual lessons","definitionCN":"教育中把教学理念转化为实际课堂的过程","example":"Teachers need support during the implementation of the new method.","exampleCN":"教师在新方法落地期间需要支持。","why":"A method described in a journal is not yet teaching. The word marks the gap between description and the room full of students.","whyCN":"期刊里描述的方法还不是教学。这个词标记的是描述与那间坐满学生的教室之间的差距。"},{"no":"06","title":"The stage when design becomes operation","titleCN":"项目实施阶段","definition":"in project management, the phase in which the designed solution is built and handed over","definitionCN":"项目管理中构建并交付已设计方案的阶段","example":"The project moves from design to implementation in March.","exampleCN":"项目在三月从设计转入实施。","why":"Here the word names a stage on a timeline. It is the moment when drawings stop and work begins.","whyCN":"这里这个词命名时间轴上的一个阶段。它是图纸停止、工作开始的时刻。"},{"no":"07","title":"The manner in which a measure is applied","titleCN":"执行方式","definition":"the particular way in which a measure is actually carried out","definitionCN":"某项措施实际被执行的具体方式","example":"The policy failed because of poor implementation, not bad design.","exampleCN":"这项政策失败是因为执行不力，而不是设计不好。","why":"The focus shifts from whether to how. Two teams can implement the same rule and produce opposite results.","whyCN":"焦点从“是否”移到“如何”。两个团队可以执行同一条规则，却得到相反结果。"},{"no":"08","title":"The degree to which something is in force","titleCN":"落实程度","definition":"the extent to which a decision has actually been put into effect","definitionCN":"某项决定实际产生效果的程度","example":"Full implementation will take another five years.","exampleCN":"全面落实还需要五年。","why":"Here the word is measurable. A reform can be 30 percent implemented, which treats the plan as a container filled to a certain level.","whyCN":"这里这个词是可测量的。一项改革可以“实施了三成”，这把计划当作一个填到某个高度的容器。"}],"etymology":{"intro":{"en":"Implementation rests on Latin implere, 'to fill up'. The same verb gave English complete, deplete and supply, and its noun implementum first meant 'a filling' before it meant 'a tool'. The modern noun keeps the container image: a plan is filled with action.","cn":"implementation 立足拉丁语 implere“填满”。同一动词给出英语 complete、deplete、supply，其名词 implementum 最早意为“填充”，后指“工具”。现代名词保留容器意象：计划被行动填满。"},"items":[{"era":"PIE *ple- (reconstructed form)","en":"The root behind plere, 'to fill', is reconstructed as *ple-, and is generally believed to underlie Latin plere, Greek pleres and English full.","cn":"plere“填满”背后的词根被重构为 *ple-，一般认为是拉丁语 plere、希腊语 pleres 与英语 full 的共同来源。"},{"era":"LATIN plere / implere","en":"Plere meant 'to fill'. With in- it became implere, 'to fill in, to fill up, to fulfil', used of promises as well as vessels.","cn":"plere 意为“填满”。加 in- 成为 implere“填进去、填满、履行”，既用于容器，也用于承诺。"},{"era":"LATIN implementum (source uncertain)","en":"Implementum meant 'a filling up' and later 'that which fills, equipment'. How the jump from 'filling' to 'tool' happened is not documented with certainty.","cn":"implementum 意为“填充”，后指“填充之物、装备”。从“填充”跳到“工具”的具体过程没有确证，来源不确定。"},{"era":"15C.–17C. ENGLISH implement","en":"English implement first meant 'a means of effecting a purpose', then a physical tool. The verb 'to implement' appeared later, in the 19th century.","cn":"英语 implement 最早意为“达成目的的手段”，后指实物工具。动词“实施”出现更晚，在 19 世纪。"},{"era":"19C. VERB + -ATION","en":"Once implement became a verb, implementation named the process. Early examples come from administration and engineering.","cn":"implement 一旦成为动词，implementation 就命名这一过程。早期用例来自行政与工程领域。"},{"era":"20C. COMPUTING AND MANAGEMENT","en":"Software implementation and project implementation made the word a standard term for the gap between design and operation.","cn":"软件实施与项目实施使这个词成为“设计与运作之间那段差距”的标准术语。"}]},"similar":{"note":{"en":"The look-alike group separates the verb, the tool and the process noun. The meaning group compares words for carrying something out.","cn":"形近组区分动词、工具名词与过程名词；词义组比较“把某事执行下去”的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"implement","ipa":"/ɪmˈplɪment/","tag":"verb","definition":"to put a plan or decision into effect. It is the action that the noun names.","definitionCN":"把计划或决定付诸实施。它是名词所命名的动作。"},{"word":"implement","ipa":"/ˈɪmplɪment/","tag":"noun","definition":"a tool or piece of equipment. The stress moves to the first syllable, and the meaning moves to the object that does the work.","definitionCN":"工具或器具。重音移到第一音节，词义也移到了干活的物件上。"},{"word":"implemental","ipa":"/ˌɪmplɪˈmentl/","tag":"adjective","definition":"serving as a means to an end. It is rare and belongs to philosophy, not administration.","definitionCN":"作为达成目的之手段的。这个词罕用，属哲学用语，不属行政用语。"}]},{"heading":"NEAR MEANING","entries":[{"word":"execution","ipa":"/ˌeksɪˈkjuːʃn/","tag":"carrying out","definition":"the carrying out of a plan, order or legal sentence. It is close to sense 01 but often carries legal or lethal overtones.","definitionCN":"执行计划、命令或法律判决。它接近第 1 义项，但常带法律或处决色彩。"},{"word":"enforcement","ipa":"/ɪnˈfɔːsmənt/","tag":"compelling obedience","definition":"the act of making people obey a law. It is implementation backed by coercion.","definitionCN":"强迫人们遵守法律的行为。它是带强制力的实施。"},{"word":"deployment","ipa":"/dɪˈplɔɪmənt/","tag":"positioning for use","definition":"the placing of resources or software into position for use. It is the technical cousin of sense 03.","definitionCN":"把资源或软件布置到可使用的位置。它是第 3 义项的技术近亲。"},{"word":"realization","ipa":"/ˌriːəlaɪˈzeɪʃn/","tag":"making real","definition":"the act of making something real or achieving it. It stresses achievement, while implementation stresses the work of building.","definitionCN":"使某事成真或实现。它强调达成，而 implementation 强调建设过程。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks build implementation from implere, 'to fill', and let the container image cover plans, policies, software, contracts and classrooms.","cn":"这些记忆钩从 implere“填满”搭起 implementation，再用容器意象覆盖计划、政策、软件、合同与课堂。"},"normal":[{"en":"See in- + plere: to fill in. Implementation is a plan being filled with real action.","cn":"看成 in- 加 plere：填进去。implementation 就是计划被真实行动填满。"},{"en":"Picture a steel ladle pouring concrete into a mould: the drawing only becomes a building when it is filled.","cn":"想象钢斗把混凝土浇进模具：图纸只有被填满才变成建筑。"},{"en":"In software, deployment is the pour: the code finally holds traffic.","cn":"在软件里，部署就是那一浇：代码终于承受真实流量。"},{"en":"In a contract, both signatures are the mould; performance is the concrete.","cn":"在合同里，双方签字是模具；履行才是混凝土。"},{"en":"Remember the family: complete, deplete and supply all come from the same 'fill' verb.","cn":"记住词族：complete、deplete、supply 都出自同一个“填”的动词。"}],"abstract":[{"en":"Keep one image: an empty form waiting for substance, and the risk that it stays empty.","cn":"只记一个意象：一张空表格等待内容，以及它可能一直空着的风险。"},{"en":"Treat the word as the answer to 'who actually does it, with what, starting when?'","cn":"把这个词当作对“谁真正去做、用什么做、从何时开始”的回答。"},{"en":"Notice that failure usually happens here, not in the design room.","cn":"注意失败通常发生在这里，而不是在设计室里。"}]},"examples":[{"en":"The implementation of the peace agreement is behind schedule.","cn":"和平协议的实施落后于计划。"},{"en":"Good policy is useless without competent implementation.","cn":"没有得力的执行，好政策也无用。"},{"en":"The software implementation required a full system migration.","cn":"这次软件实施需要完整的系统迁移。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“硬不累门太深”：再硬的任务也不嫌累，门槛太深也要钻进去把事办成——这就是实施。","word":"implementation"},"root":"拉丁语 implere“填满、履行”（in- 进入 + plere 填满），名词 implementum 原指“填充”，后转指“工具、器具”；implement 作动词后加 -ation 构成 implementation。","sensesIntro":{"en":"Implementation is the moment a document stops being a document. A plan, a policy, a database, a contract, a teaching method, a project phase, a style of carrying out and a percentage completed are all versions of one act: filling an empty form with real work. The eight senses differ in what the container is and how full it has become.","cn":"implementation 是文件不再是文件的那一刻。计划、政策、数据库、合同、教学方法、项目阶段、执行方式、完成百分比，都是同一个动作的版本：用真实工作填满一张空表格。八个义项的差别在于容器是什么、已经填到多满。"},"semanticMap":{"core":{"en":"Filling a designed form with real action until it works.","cn":"用真实行动填满设计好的形式，直到它运转起来。"},"chain":["PLAN","FILL","BUILD","RUN","DELIVER","SUSTAIN"],"branches":[{"senses":"S1 · S6","en":"PROJECT: a plan leaves the drawing board and becomes a phase of work.","cn":"项目：计划离开图板，成为一段施工阶段。"},{"senses":"S2 · S7","en":"ADMINISTRATION: a rule is applied, and the manner of applying decides the result.","cn":"行政：规则被适用，而适用方式决定结果。"},{"senses":"S3","en":"SYSTEMS: designed code is placed in a live environment.","cn":"系统：设计好的代码被放入真实环境。"},{"senses":"S4","en":"OBLIGATION: promised duties are actually performed.","cn":"义务：承诺的义务被真正履行。"},{"senses":"S5 · S8","en":"PRACTICE: a method reaches the classroom, and coverage can be measured.","cn":"实践：方法抵达课堂，覆盖程度可被测量。"}]},"affixes":{"intro":{"en":"Implementation is implement plus -ation. The items below gather the 'fill' family and show how the same Latin verb yields words for completeness, emptiness and supply.","cn":"implementation 是 implement 加 -ation。下列条目汇总“填”的词族，并展示同一拉丁动词如何造出表示完整、空竭与供给的词。"},"latinIntro":{"en":"The Latin entries give the verb, its root and the noun that shifted from 'filling' to 'tool'. That shift explains the double life of English implement.","cn":"拉丁语条目给出动词、其词根，以及从“填充”转向“工具”的名词。这次转变解释了英语 implement 的双重身份。"},"items":[{"word":"implementation","structure":"implement + -ation (process noun)","meaning":"the carrying out of a plan or system","meaningCN":"计划或系统的执行","example":"Implementation begins next month.","exampleCN":"实施下个月开始。"},{"word":"implement","structure":"Late Latin implementum, 'a filling'","meaning":"to carry out; also a tool","meaningCN":"执行；也指工具","example":"The team will implement the changes in stages.","exampleCN":"团队将分阶段实施这些变更。"},{"word":"implementable","structure":"implement + -able","meaning":"able to be carried out","meaningCN":"可实施的","example":"The proposal is technically implementable.","exampleCN":"该提案在技术上可实施。"},{"word":"implementer","structure":"implement + -er (agent)","meaning":"a person or group that carries out a plan","meaningCN":"实施计划的人或团体","example":"The implementers were never consulted.","exampleCN":"实施者从未被征询意见。"},{"word":"complete","structure":"Latin complere (com- + plere)","meaning":"to finish; whole","meaningCN":"完成；完整的","example":"They completed the survey in a week.","exampleCN":"他们一周内完成了调查。"},{"word":"deplete","structure":"Latin deplere (de- + plere, 'unfill')","meaning":"to empty or exhaust","meaningCN":"耗尽；使枯竭","example":"The drought depleted the reservoirs.","exampleCN":"干旱耗尽了水库。"},{"word":"replete","structure":"Latin repletus, from replere","meaning":"full, abundantly supplied","meaningCN":"充满的；充盈的","example":"The archive is replete with letters.","exampleCN":"档案馆里满是信件。"},{"word":"supplement","structure":"Latin supplementum, from supplere","meaning":"something added to fill a gap","meaningCN":"用来填补缺口的补充物","example":"A vitamin supplement filled the gap in her diet.","exampleCN":"一种维生素补充剂填补了她饮食中的缺口。"}],"latinEntries":[{"word":"plere","structure":"2nd conjugation verb","meaning":"to fill","meaningCN":"填满"},{"word":"implere","structure":"in- + plere","meaning":"to fill up; to fulfil","meaningCN":"填满；履行"},{"word":"implementum","structure":"implere + -mentum (instrument noun)","meaning":"a filling; that which fills","meaningCN":"填充；填充之物"}]}},{"word":"implicit","ipa_uk":"/ɪmˈplɪsɪt/","ipa_us":"/ɪmˈplɪsɪt/","definition_zh":"含蓄的；不言明的；内含的；绝对的；隐式的","definition_en":"suggested or contained without being stated directly, or complete and unquestioning","core_image":"话只说了一半，另一半折在信封里，但听的人已经懂了","scene":"The warning was implicit in her tone rather than in anything she said.","sceneCN":"这里 implicit 是「未明说而暗示的」（第 1、2 个义项：意思藏在语气里而非字面）；句意：警告藏在她的语气里，而不是她说的任何话里。图中可辨识物件：半开的信封、露出的信纸一角、听者微微收紧的手。","pos":[{"tag":"adj.","zh":"含蓄的；不言明的；内含的；绝对的"}],"collocations":[{"phrase":"implicit assumption","zh":"隐含的假设"},{"phrase":"implicit meaning","zh":"言外之意"},{"phrase":"implicit trust","zh":"绝对信任"},{"phrase":"implicit in","zh":"内含于……的"},{"phrase":"implicit bias","zh":"内隐偏见"},{"phrase":"implicit function","zh":"隐函数"}],"forms":[{"label":"原级","form":"implicit"},{"label":"比较级","form":"more implicit"},{"label":"最高级","form":"most implicit"},{"label":"副词","form":"implicitly"},{"label":"名词","form":"implicitness"}],"derivatives":[{"word":"imply","pos":"v.","zh":"暗示；意味着"},{"word":"implication","pos":"n.","zh":"含义；牵连"},{"word":"implicitly","pos":"adv.","zh":"含蓄地；绝对地"},{"word":"implicate","pos":"v.","zh":"牵连；暗示"}],"senses":[{"no":"01","title":"Not stated in words","titleCN":"未明说的","definition":"present as meaning without being expressed in words","definitionCN":"作为意义存在，却未用言语表达","example":"There was an implicit threat in the letter.","exampleCN":"这封信里有未明言的威胁。","why":"Implicitus is the past participle of implicare, 'to fold in'. The meaning is folded inside the sentence, present but not laid out.","whyCN":"implicitus 是 implicare“折进去”的过去分词。意思被折进句子内部，在场却没有摊开。"},{"no":"02","title":"Understood from the situation","titleCN":"由情境暗示的","definition":"understood because the context points to it rather than because it is said","definitionCN":"由语境指向而被理解，而非被说出","example":"Silence gave implicit permission.","exampleCN":"沉默等于默许。","why":"The missing sentence is supplied by the listener. The word marks meaning that the situation, not the speaker, has folded in.","whyCN":"缺的那句话由听者补上。这个词标记的是情境而非说话者折进去的意义。"},{"no":"03","title":"Contained within something","titleCN":"内含于某物的","definition":"existing as a necessary part of something larger","definitionCN":"作为更大事物必要部分而存在","example":"A cost is implicit in every design choice.","exampleCN":"每个设计选择都内含成本。","why":"Here the fold is structural: the part was always inside the whole, whether anyone noticed.","whyCN":"这里的折叠是结构性的：那部分一直在整体内部，无论有没有人注意。"},{"no":"04","title":"Complete and unquestioning","titleCN":"毫无保留的","definition":"absolute and undoubting, as in trust or obedience","definitionCN":"绝对且不存疑虑的，如信任或服从","example":"She had implicit faith in his judgement.","exampleCN":"她对他的判断有绝对的信任。","why":"A different branch of the same Latin fold: to be folded into someone's will is to hold nothing back.","whyCN":"同一拉丁“折叠”的另一条分支：被折进某人的意志里，就是毫无保留。"},{"no":"05","title":"Defined through an equation, not solved out","titleCN":"数学中的隐式","definition":"in mathematics, describing a relation given by an equation that is not solved for one variable","definitionCN":"数学中由未解出某一变量的方程所给出的关系","example":"The curve is given by an implicit function of two variables.","exampleCN":"这条曲线由二元隐函数给出。","why":"The variable is folded into the equation rather than standing alone on one side. That is why mathematicians call it implicit.","whyCN":"变量被折进方程里，而不是单独站在等号一边。数学家因此称它为隐式。"},{"no":"06","title":"Operating outside awareness","titleCN":"心理上的内隐","definition":"in psychology, describing mental processes that run automatically and below conscious notice","definitionCN":"心理学中自动运行、不被意识注意的心理过程","example":"Implicit memory lets you ride a bicycle without thinking.","exampleCN":"内隐记忆让你不必思考就能骑车。","why":"The knowledge is folded into the body and not available for report. This is the modern scientific version of 'not stated'.","whyCN":"知识被折进身体里，无法用言语报告。这是“未明说”的现代科学版本。"},{"no":"07","title":"Taken for granted as a premise","titleCN":"被默认为前提的","definition":"assumed in the background of an argument without being defended","definitionCN":"在论证背景中被假定、未经辩护","example":"The argument rests on an implicit premise about human nature.","exampleCN":"该论证依赖一个关于人性的隐含前提。","why":"Logic calls a premise implicit when it never appears on the list but is needed for the conclusion to stand.","whyCN":"逻辑学把从未列在清单上、却是结论成立所必需的前提称为隐含前提。"},{"no":"08","title":"Conveyed indirectly in style","titleCN":"含蓄表达的风格","definition":"in art or writing, meaning carried by suggestion rather than statement","definitionCN":"艺术或写作中由暗示而非陈述承载的意义","example":"The novel's ending is implicit rather than explicit.","exampleCN":"这部小说的结局是含蓄的，而非明说的。","why":"The word becomes a style judgement: what is left folded is valued more than what is spread open.","whyCN":"这个词成了风格判断：留着折叠的部分，比摊开的部分更受重视。"}],"etymology":{"intro":{"en":"Implicit is the past participle of Latin implicare, 'to fold in, to entangle'. Its opposite is explicit, the past participle of explicare, 'to unfold'. The whole family is about folding and unfolding meaning, and that image explains every sense.","cn":"implicit 是拉丁语 implicare“折进去、缠绕”的过去分词。它的反义词 explicit 是 explicare“展开”的过去分词。整个词族都在讲“折”与“展”，这个意象解释了所有义项。"},"items":[{"era":"PIE *plek- (reconstructed form)","en":"The root behind plicare, 'to fold', is reconstructed as *plek-, 'to plait, to fold'. It is generally connected with Latin plectere and English plait.","cn":"plicare“折叠”背后的词根被重构为 *plek-“编、折”，一般与拉丁语 plectere 和英语 plait 联系起来。"},{"era":"LATIN plicare / implicare","en":"Plicare meant 'to fold'. In- plus plicare gave implicare, 'to fold in, to involve, to entangle', used of cloth and of people caught in a case.","cn":"plicare 意为“折叠”。in- 加 plicare 构成 implicare“折入、牵涉、缠绕”，既用于布料，也用于被案情卷入的人。"},{"era":"LATIN implicitus","en":"The past participle implicitus meant 'folded in, entangled'. English took it as a learned adjective in the 16th century, meaning 'contained though not expressed'.","cn":"过去分词 implicitus 意为“被折入的、被缠绕的”。英语在 16 世纪把它当作学术形容词借入，意为“内含而未表达”。"},{"era":"LATIN explicitus / explicit","en":"The opposite participle explicitus, from explicare 'to unfold', gave English explicit. The pair has been used together ever since as a fold and its opening.","cn":"反义的过去分词 explicitus 出自 explicare“展开”，给出英语 explicit。这对词此后一直一起使用，一个折叠，一个摊开。"},{"era":"17C.–18C. RELIGION AND LOGIC","en":"Implicit faith meant trusting a doctrine without fully understanding it. Logic then used implicit for premises that are needed but not written down.","cn":"implicit faith 指未完全理解就信赖某教义。逻辑学随后用 implicit 指必需却未写下的前提。"},{"era":"20C. MATHEMATICS AND PSYCHOLOGY","en":"Implicit functions and implicit memory extend the fold image to equations and to the mind. Both describe something present but not laid out for inspection.","cn":"隐函数与内隐记忆把折叠意象扩展到方程与心智。两者都描述在场却未摊开可供检查之物。"}]},"similar":{"note":{"en":"The look-alike group separates the verb, the noun and the direct opposite, all built on the same fold-root. The meaning group compares words for what is present but unsaid.","cn":"形近组区分同一“折叠”词根上的动词、名词与直接反义词；词义组比较表示“在场却未说出”的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"implicate","ipa":"/ɪmˈplɪkeɪt/","tag":"verb","definition":"to show that someone is involved in a crime or problem. It is the active verb, and it drags a person into the fold.","definitionCN":"表明某人卷入犯罪或问题。它是个主动动词，把人拖进折叠之中。"},{"word":"implication","ipa":"/ˌɪmplɪˈkeɪʃn/","tag":"noun","definition":"something suggested though not stated, or the state of being involved. It names what is folded in, while implicit is the adjective.","definitionCN":"未明说而暗示的内容，或卷入的状态。它命名被折入之物，而 implicit 是形容词。"},{"word":"explicit","ipa":"/ɪkˈsplɪsɪt/","tag":"opposite adjective","definition":"stated fully and clearly. It is the exact opposite: what implicit folds in, explicit unfolds.","definitionCN":"完整清楚地说出。它是精确的反义词：implicit 折进去的，explicit 展开。"}]},{"heading":"NEAR MEANING","entries":[{"word":"implied","ipa":"/ɪmˈplaɪd/","tag":"suggested","definition":"meant but not said. It is close to sense 01 but is the everyday participle rather than the learned adjective.","definitionCN":"有意却未说出。它接近第 1 义项，但属日常分词而非学术形容词。"},{"word":"inherent","ipa":"/ɪnˈherənt/","tag":"built in","definition":"existing as a permanent part of something. It matches sense 03 and stresses that the part cannot be removed.","definitionCN":"作为某物永久部分存在。它对应第 3 义项，强调该部分无法移除。"},{"word":"tacit","ipa":"/ˈtæsɪt/","tag":"silently understood","definition":"understood or agreed without being spoken. It fits senses 01 and 07 but comes from tacere, 'to be silent', not from folding.","definitionCN":"未经言说就被理解或同意。它适合第 1、7 义项，但词源是 tacere“沉默”，而非“折叠”。"},{"word":"latent","ipa":"/ˈleɪtnt/","tag":"not yet active","definition":"present but not yet visible or active. It stresses waiting to appear, while implicit stresses never having been said.","definitionCN":"存在但尚未显现或活动。它强调等待出现，而 implicit 强调从未被说出。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks build implicit from implicare, 'to fold in', and keep the contrast with explicit, 'unfolded', in view.","cn":"这些记忆钩从 implicare“折进去”搭起 implicit，并始终把与 explicit“展开”的对照放在眼前。"},"normal":[{"en":"See im- + plicare: folded in. The meaning is inside the sentence, not printed on it.","cn":"看成 im- 加 plicare：折进去。意思在句子里，而不是印在句子表面。"},{"en":"Picture a letter folded twice: the message exists, but you must unfold it to read it.","cn":"想象一封折了两折的信：讯息存在，但你得展开才能读。"},{"en":"Keep the pair: implicit folds in, explicit unfolds.","cn":"记住这一对：implicit 折进去，explicit 展开。"},{"en":"An implicit premise is the page of the argument nobody printed.","cn":"隐含前提是论证中没人印出来的那一页。"},{"en":"In psychology, the knowledge is folded into your hands, not into your words.","cn":"在心理学里，知识被折进你的手里，而不是你的话里。"}],"abstract":[{"en":"Keep one gesture: closing a hand around something so that others see the gesture but not the object.","cn":"只记一个动作：把手合起来握住某物，别人看见手势，却看不见东西。"},{"en":"Treat the word as a claim about where meaning is stored, not about how much meaning there is.","cn":"把这个词当作关于意义存放位置的说明，而不是关于意义多少的说明。"},{"en":"Notice that implicit trust and implicit meaning share only the image of no distance left.","cn":"注意绝对信任与含蓄含义只共享一个意象：不再留有距离。"}]},"examples":[{"en":"The contract carries an implicit promise of confidentiality.","cn":"这份合同内含保密的承诺。"},{"en":"His silence was an implicit admission of guilt.","cn":"他的沉默等于默认有罪。"},{"en":"The psychologist studies implicit attitudes that people cannot report.","cn":"这位心理学家研究人们无法报告的内隐态度。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“阴里塞的”：话不明说，悄悄塞进语气里——这就是含蓄的、隐含的。","word":"implicit"},"root":"拉丁语 implicare“折入、缠绕”（in- 进入 + plicare 折叠）的过去分词 implicitus；与 explicare“展开”的 explicit 构成一对反义。","sensesIntro":{"en":"Everything in this word is a fold. A meaning is folded into a sentence (S1), into a situation (S2), into a structure (S3), into a will (S4), into an equation (S5), into the body (S6), into the background of an argument (S7) and into a style (S8). The opposite word, explicit, is the same cloth spread flat.","cn":"这个词里的一切都是一次折叠。意义被折进句子（第 1）、折进情境（第 2）、折进结构（第 3）、折进意志（第 4）、折进方程（第 5）、折进身体（第 6）、折进论证背景（第 7）、折进风格（第 8）。反义词 explicit 就是同一块布被摊平。"},"semanticMap":{"core":{"en":"Meaning folded inside something, present but not laid open.","cn":"意义被折在某物内部，在场却未摊开。"},"chain":["FOLD","INSIDE","UNSAID","ASSUME","AUTOMATIC","ENTRUST"],"branches":[{"senses":"S1 · S2","en":"LANGUAGE: what the words do not say but the listener hears.","cn":"语言：字面没说、听者却听见的内容。"},{"senses":"S3 · S7","en":"STRUCTURE: costs inside a design, premises behind a proof.","cn":"结构：设计中的成本，证明背后的前提。"},{"senses":"S4","en":"TRUST: nothing held back, folded entirely into another's will.","cn":"信任：毫无保留，整个人折进他人的意志。"},{"senses":"S5 · S6","en":"SCIENCE: variables inside equations, knowledge inside the body.","cn":"科学：方程中的变量，身体中的知识。"},{"senses":"S8","en":"STYLE: meaning carried by suggestion rather than statement.","cn":"风格：由暗示而非陈述承载的意义。"}]},"affixes":{"intro":{"en":"Implicit is im- plus the participle of plicare. The items below show the fold family and its opposite, and show how far the root reaches into ordinary words like complex and multiply.","cn":"implicit 是 im- 加 plicare 的分词。下列条目展示“折叠”词族及其反义，并展示该词根延伸到 complex、multiply 等日常词的范围。"},"latinIntro":{"en":"The Latin entries give the verb, its participle and the bare root. They explain why the same fold produces words about involvement, complexity and multiplication.","cn":"拉丁语条目给出动词、其分词与裸词根。它们解释了同一次折叠为何造出关于牵连、复杂与倍增的词。"},"items":[{"word":"implicit","structure":"Latin implicitus, participle of implicare","meaning":"folded in; unstated but understood","meaningCN":"折入的；未明说但被理解的","example":"The rule is implicit in the wording.","exampleCN":"这条规则隐含在措辞之中。"},{"word":"implicitly","structure":"implicit + -ly","meaning":"in an unstated or absolute way","meaningCN":"以未明说或绝对的方式","example":"She trusted him implicitly.","exampleCN":"她绝对信任他。"},{"word":"implicate","structure":"Latin implicare + -ate","meaning":"to involve, especially in wrongdoing","meaningCN":"使卷入，尤指卷入过错","example":"The emails implicated two officials.","exampleCN":"这些邮件牵连了两名官员。"},{"word":"implication","structure":"implicare + -ation","meaning":"a suggested meaning; a consequence","meaningCN":"暗示的含义；后果","example":"The implication was that funding would stop.","exampleCN":"言下之意是资金会停止。"},{"word":"explicit","structure":"Latin explicitus, participle of explicare","meaning":"fully and clearly stated","meaningCN":"完整清楚地说出的","example":"The instructions are explicit.","exampleCN":"说明写得很明确。"},{"word":"complicate","structure":"Latin complicare (com- + plicare)","meaning":"to fold together; to make difficult","meaningCN":"折叠在一起；使复杂","example":"New rules complicated the process.","exampleCN":"新规则使流程复杂化。"},{"word":"complex","structure":"Latin complexus, participle of complecti","meaning":"made of many folded parts","meaningCN":"由许多折叠部分构成的","example":"The brain is a complex organ.","exampleCN":"大脑是一个复杂的器官。"},{"word":"multiply","structure":"Latin multiplicare, from multiplex","meaning":"to increase in number","meaningCN":"数量增加；相乘","example":"Cells multiply rapidly.","exampleCN":"细胞迅速增殖。"}],"latinEntries":[{"word":"plicare","structure":"1st conjugation verb","meaning":"to fold, to bend","meaningCN":"折叠；弯曲"},{"word":"implicare","structure":"in- + plicare","meaning":"to fold in; to entangle","meaningCN":"折入；缠绕；牵连"},{"word":"implicitus","structure":"past participle of implicare","meaning":"folded in; involved","meaningCN":"被折入的；被卷入的"}]}},{"word":"implicitly","ipa_uk":"/ɪmˈplɪsɪtli/","ipa_us":"/ɪmˈplɪsɪtli/","definition_zh":"含蓄地；不言明地；内隐地；绝对地；默认地","definition_en":"in a way that is suggested rather than stated, or in a complete and unquestioning way","core_image":"不把话说出口，只把话折好递过去","scene":"By signing the form she implicitly accepted the conditions printed on the back.","sceneCN":"这里 implicitly 是「以默认方式」（第 1、5 个义项：未明说即成立）；句意：签下表格，她就默认接受了背面印着的条件。图中可辨识物件：签字的笔、翻到背面的表格、压在纸上的手指。","pos":[{"tag":"adv.","zh":"含蓄地；不言明地；绝对地；默认地"}],"collocations":[{"phrase":"implicitly accept","zh":"默认接受"},{"phrase":"implicitly assume","zh":"隐含假定"},{"phrase":"implicitly trust","zh":"绝对信任"},{"phrase":"implicitly criticize","zh":"含蓄地批评"},{"phrase":"implicitly agree","zh":"默许"},{"phrase":"implicitly understood","zh":"不言而喻地理解"}],"forms":[{"label":"原级","form":"implicitly"},{"label":"对应形容词","form":"implicit"},{"label":"名词","form":"implicitness"}],"derivatives":[{"word":"implicit","pos":"adj.","zh":"含蓄的；内含的"},{"word":"imply","pos":"v.","zh":"暗示；意味着"},{"word":"implication","pos":"n.","zh":"含义；牵连"},{"word":"implicitness","pos":"n.","zh":"含蓄性"}],"senses":[{"no":"01","title":"Without putting it into words","titleCN":"未把话说出口地","definition":"in a manner that conveys meaning without stating it","definitionCN":"以传达意义却不明说的方式","example":"She implicitly blamed the manager for the delay.","exampleCN":"她含蓄地把延误归咎于经理。","why":"The adverb modifies the verb, so it tells us how an act was done: the blame was delivered folded, not spoken.","whyCN":"这个副词修饰动词，说明动作是“怎样”做的：责备被折起来递出，而没有说出口。"},{"no":"02","title":"By suggestion rather than statement","titleCN":"靠暗示而非陈述地","definition":"through hints and context rather than explicit words","definitionCN":"通过暗示与语境而非明确言语","example":"The ending implicitly tells us that he never returned.","exampleCN":"结局暗示他再也没有回来。","why":"Here the adverb describes how a text works, not how a person acts. Meaning arrives by implication.","whyCN":"这里副词描述的是文本如何运作，而不是人如何行动。意义是靠暗示到达的。"},{"no":"03","title":"Completely, holding nothing back","titleCN":"毫无保留地","definition":"with absolute and undoubting confidence","definitionCN":"带着绝对且不存疑虑的信任","example":"He trusted her implicitly.","exampleCN":"他绝对信任她。","why":"This is the 'folded into another's will' branch: the adverb says no reservation was kept outside the trust.","whyCN":"这是“折进他人意志”的分支：副词说明信任之外没有留下任何保留。"},{"no":"04","title":"Without conscious notice","titleCN":"不被意识到地","definition":"in a way that operates automatically, below awareness","definitionCN":"以自动、低于意识的方式运作","example":"We implicitly learn the rules of our first language.","exampleCN":"我们在无意识中习得母语的规则。","why":"The learning is folded into habit, so the adverb marks an act that leaves no memory of learning it.","whyCN":"学习被折进习惯，因此这个副词标记的是一个没有留下“学习”记忆的动作。"},{"no":"05","title":"As an unstated premise","titleCN":"作为默认前提地","definition":"in logic, in a way that is assumed rather than argued","definitionCN":"逻辑中作为被假定而非被论证的前提","example":"The model implicitly assumes stable prices.","exampleCN":"该模型默认假定价格稳定。","why":"The assumption never appears as a line in the proof; the adverb says it was folded into the background.","whyCN":"该假设从未作为一行出现在证明里；副词说明它被折进了背景。"},{"no":"06","title":"Indirectly, in manner or style","titleCN":"以间接方式","definition":"in an indirect manner of expression or behaviour","definitionCN":"以间接的表达或行为方式","example":"He implicitly criticized the plan by praising its opposite.","exampleCN":"他通过称赞相反做法而含蓄地批评了该计划。","why":"The adverb names the route, not the content: the criticism travels around the statement instead of through it.","whyCN":"副词命名的是路径而不是内容：批评绕过陈述，而不是穿过陈述。"},{"no":"07","title":"With unquestioning obedience","titleCN":"不加质疑地","definition":"with obedience or belief that asks for no justification","definitionCN":"带着不求理由的服从或相信","example":"The staff followed the order implicitly.","exampleCN":"员工不加质疑地服从了命令。","why":"Obedience is complete when nothing is held outside the fold. The adverb marks the absence of a reserve.","whyCN":"服从之所以彻底，是因为没有东西留在折叠之外。副词标记的正是那份保留的缺席。"},{"no":"08","title":"As part of what is meant","titleCN":"作为含义一部分地","definition":"as something contained in the meaning of a word or act even if not spelled out","definitionCN":"作为词或行为的含义所包含、却未被写明的内容","example":"The promise implicitly includes a duty to warn.","exampleCN":"这项承诺隐含了告知的义务。","why":"Here the adverb points at the contents of a concept. What is included was always inside, awaiting articulation.","whyCN":"这里副词指向概念的内容。被包含的东西一直在内部，只等着被表述出来。"}],"etymology":{"intro":{"en":"Implicitly is implicit plus -ly. The adjective comes from Latin implicitus, 'folded in', the participle of implicare. The adverb therefore describes actions and statements whose meaning or commitment is folded inside them.","cn":"implicitly 是 implicit 加 -ly。形容词来自拉丁语 implicitus“折入的”，即 implicare 的分词。因此这个副词描述的是意义或承诺被折在里面的动作与陈述。"},"items":[{"era":"PIE *plek- (reconstructed form)","en":"The root *plek-, 'to fold or plait', is reconstructed and generally accepted behind Latin plicare and plectere.","cn":"词根 *plek-“折叠、编织”是重构形式，一般被接受为拉丁语 plicare 与 plectere 的来源。"},{"era":"LATIN implicare","en":"In- plus plicare gave implicare, 'to fold in, to involve'. The participle implicitus described something already folded, not something being folded.","cn":"in- 加 plicare 构成 implicare“折入、牵连”。分词 implicitus 描述已经折好的东西，而不是正在折的动作。"},{"era":"16C. ENGLISH implicit","en":"English borrowed implicit as a learned adjective meaning 'contained though not expressed'. The adverb followed once the adjective was established.","cn":"英语借入 implicit 作学术形容词，意为“内含而未表达”。形容词站稳之后，副词随之出现。"},{"era":"ENGLISH -ly","en":"The suffix -ly turns adjectives into manner adverbs. It comes from Old English -lice, and in this word it asks 'in what manner was it folded?'","cn":"后缀 -ly 把形容词变成方式副词，源自古英语 -lice。在这个词里，它问的是“是以何种方式折叠的？”。"},{"era":"18C.–19C. USAGE SPLIT","en":"The 'unstated meaning' use and the 'absolute trust' use both appear in the 18th and 19th centuries, sometimes in the same sentence.","cn":"“未明说的意义”与“绝对信任”两种用法都出现在 18、19 世纪，有时同处一句。"},{"era":"20C. SCIENCE AND LAW","en":"Psychology and law gave the adverb technical work: implicitly learned rules, implicitly accepted terms. Both rely on the same image of an unprinted clause.","cn":"心理学与法律赋予这个副词技术任务：内隐习得的规则、默认接受的条款。两者都依赖同一个“未印出的条款”意象。"}]},"similar":{"note":{"en":"The look-alike group separates the adjective, the verb and the noun. The meaning group compares adverbs of indirect or silent communication.","cn":"形近组区分形容词、动词与名词；词义组比较表示间接或沉默传达的副词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"implicit","ipa":"/ɪmˈplɪsɪt/","tag":"adjective","definition":"folded in, not stated. The adverb says that an action is carried out in that folded way.","definitionCN":"折入的、未明说的。副词说明某动作以这种折叠方式完成。"},{"word":"implicate","ipa":"/ɪmˈplɪkeɪt/","tag":"verb","definition":"to involve someone in wrongdoing. It is active and judicial, not adverbial.","definitionCN":"使某人卷入过错。它是主动的、司法性的，不是副词用法。"},{"word":"implication","ipa":"/ˌɪmplɪˈkeɪʃn/","tag":"noun","definition":"a suggested meaning or a consequence. It is the thing an implicit act leaves behind.","definitionCN":"暗示的含义或后果。它是隐含行为留下的东西。"}]},{"heading":"NEAR MEANING","entries":[{"word":"tacitly","ipa":"/ˈtæsɪtli/","tag":"silently","definition":"by agreement or understanding without words. It is very close to sense 01 but comes from 'silent', not from 'folded'.","definitionCN":"不发一言地同意或理解。它很接近第 1 义项，但词源是“沉默”，而非“折叠”。"},{"word":"indirectly","ipa":"/ˌɪndəˈrektli/","tag":"by a roundabout route","definition":"in a way that does not go straight to the point. It matches sense 06 and stresses route rather than silence.","definitionCN":"不走直线地。它对应第 6 义项，强调路径而非沉默。"},{"word":"absolutely","ipa":"/əˈsɒluːtli/","tag":"completely","definition":"totally, without limit. It matches senses 03 and 07 but lacks the image of trust folded into another.","definitionCN":"完全地、无限制地。它对应第 3、7 义项，但缺少“信任折进他人”的意象。"},{"word":"automatically","ipa":"/ɔːˈtɒmætɪkli/","tag":"by itself","definition":"without conscious control. It matches sense 04 and stresses mechanism, not concealment.","definitionCN":"不受意识控制地。它对应第 4 义项，强调机制而非隐藏。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks build implicitly from implicit plus -ly and keep the image of an act done with the meaning folded inside.","cn":"这些记忆钩从 implicit 加 -ly 搭起 implicitly，并保留“动作完成时意义折在里面”的意象。"},"normal":[{"en":"See implicit + -ly: in a folded manner. Ask 'how?' and the answer is 'without saying it'.","cn":"看成 implicit 加 -ly：以折叠的方式。问“怎么做的？”，答案就是“没说出口”。"},{"en":"Picture a signed form: the signature says nothing, yet it accepts every clause on the back.","cn":"想象一份签好的表格：签名一言不发，却接受了背面的每一条款。"},{"en":"When someone replies 'if you like', they are implicitly refusing.","cn":"当有人回答“随你吧”，他们其实在含蓄地拒绝。"},{"en":"Trusting implicitly means keeping nothing back outside the trust.","cn":"绝对信任意味着在信任之外不留任何东西。"},{"en":"Learning implicitly means the rule entered your hands without a lesson.","cn":"内隐学习意味着规则没上课就进了你的手。"}],"abstract":[{"en":"Keep one image: a hand passing a closed note across a table.","cn":"只记一个意象：一只手把折好的纸条推过桌面。"},{"en":"Treat the adverb as answering 'how', never 'what'; the content stays folded.","cn":"把这个副词当作回答“如何”，而不是“什么”；内容始终折着。"},{"en":"Notice that silence can carry both criticism and consent, and only context unfolds it.","cn":"注意沉默既能携带批评也能携带同意，只有语境能把它展开。"}]},"examples":[{"en":"The report implicitly criticizes the previous administration.","cn":"这份报告含蓄地批评了前任政府。"},{"en":"She trusted his judgement implicitly.","cn":"她绝对信任他的判断。"},{"en":"Children learn grammar implicitly long before they study it.","cn":"儿童在系统学习语法之前，早已内隐地习得语法。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“阴里塞得利”：把话藏在阴处塞进去，还办得利落——这就是含蓄地、默认地。","word":"implicitly"},"root":"拉丁语 implicitus（implicare“折入”的过去分词，in- + plicare 折叠）加英语副词后缀 -ly；与 explicit“展开的”相对。","sensesIntro":{"en":"Implicitly always answers the question 'how'. It says that a blame, a promise, a trust, a learning, an assumption, a criticism, an obedience or an inclusion was carried out with the meaning folded in. The eight senses differ in which act is being performed and whether the fold hides a message or hides a reservation.","cn":"implicitly 始终回答“如何”这个问题。它说责备、承诺、信任、学习、假定、批评、服从或包含，都是以“意义折在里面”的方式完成的。八个义项的差别在于执行的是什么动作，以及这次折叠是藏起了一则讯息，还是藏起了一份保留。"},"semanticMap":{"core":{"en":"Acting or meaning in a folded way, with the content left inside.","cn":"以折叠的方式行动或表意，内容留在里面。"},"chain":["FOLD","UNSAID","SUGGEST","ASSUME","TRUST","AUTOMATIC"],"branches":[{"senses":"S1 · S2 · S6","en":"COMMUNICATION: blame, hints and criticism delivered by implication.","cn":"沟通：以暗示递出的责备、提示与批评。"},{"senses":"S3 · S7","en":"COMMITMENT: trust and obedience with nothing held back.","cn":"承诺：毫无保留的信任与服从。"},{"senses":"S4","en":"MIND: rules absorbed below awareness.","cn":"心智：在意识之下吸收的规则。"},{"senses":"S5","en":"REASONING: premises assumed but never listed.","cn":"推理：被假定却从未列出的前提。"},{"senses":"S8","en":"MEANING: duties contained inside a promise.","cn":"意义：包含在承诺内部的义务。"}]},"affixes":{"intro":{"en":"Implicitly is the adjective plus -ly. The items below show the fold family across parts of speech, and show that the adverb is simply the manner form of the adjective.","cn":"implicitly 是形容词加 -ly。下列条目展示“折叠”词族跨词类的分布，并说明副词只是形容词的方式形式。"},"latinIntro":{"en":"The Latin entries repeat the small family behind the adverb: a verb, its participle and the bare root.","cn":"拉丁语条目重复了副词背后的小家族：一个动词、它的分词与裸词根。"},"items":[{"word":"implicitly","structure":"implicit + -ly (manner adverb)","meaning":"in a folded, unstated way","meaningCN":"以折叠、未明说的方式","example":"He implicitly acknowledged the error.","exampleCN":"他含蓄地承认了错误。"},{"word":"implicit","structure":"Latin implicitus + -it","meaning":"unstated but understood","meaningCN":"未明说但被理解","example":"The condition was implicit in the offer.","exampleCN":"条件隐含在报价中。"},{"word":"implication","structure":"implicare + -ation","meaning":"what is suggested; a consequence","meaningCN":"暗示的内容；后果","example":"The implication frightened the investors.","exampleCN":"言下之意吓到了投资者。"},{"word":"implicate","structure":"implicare + -ate","meaning":"to involve in a fault","meaningCN":"使卷入过错","example":"The testimony implicated three others.","exampleCN":"证词牵连了另外三人。"},{"word":"implicitness","structure":"implicit + -ness","meaning":"the quality of being unstated","meaningCN":"未明说的性质","example":"The implicitness of the rule caused confusion.","exampleCN":"规则的不言明造成了混乱。"},{"word":"explicitly","structure":"explicit + -ly (opposite adverb)","meaning":"in a fully stated way","meaningCN":"以完整明说的方式","example":"The contract states the deadline explicitly.","exampleCN":"合同明确写明了截止日期。"},{"word":"implied","structure":"imply + -ed","meaning":"suggested without being said","meaningCN":"未说出而被暗示的","example":"The implied threat was clear to everyone.","exampleCN":"那隐含的威胁人人都看得出。"},{"word":"imply","structure":"Old French emplier, from Latin implicare","meaning":"to suggest indirectly","meaningCN":"间接暗示","example":"Are you implying that I lied?","exampleCN":"你是在暗示我撒谎吗？"}],"latinEntries":[{"word":"plicare","structure":"1st conjugation verb","meaning":"to fold","meaningCN":"折叠"},{"word":"implicare","structure":"in- + plicare","meaning":"to fold in; to involve","meaningCN":"折入；牵连"},{"word":"implicitus","structure":"past participle","meaning":"folded in","meaningCN":"被折入的"}]}},{"word":"importance","ipa_uk":"/ɪmˈpɔːtns/","ipa_us":"/ɪmˈpɔːrtns/","definition_zh":"重要性；重要地位；重要意义；显著性","definition_en":"the quality of being important, or the high value and influence that something carries","core_image":"一件东西被抬到桌子中央，所有眼睛都跟着它走","scene":"The report stresses the importance of diagnosing the disease early.","sceneCN":"这里 importance 是「重要性」（第 1 个义项：某事具有重大意义）；句意：报告强调早期诊断这种疾病的重要性。图中可辨识物件：被放到桌面中央的报告、围过来的几双手、指向第一页的笔。","pos":[{"tag":"n.","zh":"重要性；重要地位；重要意义"}],"collocations":[{"phrase":"of great importance","zh":"极为重要的"},{"phrase":"attach importance to","zh":"重视"},{"phrase":"the importance of","zh":"……的重要性"},{"phrase":"grow in importance","zh":"重要性上升"},{"phrase":"relative importance","zh":"相对重要性"},{"phrase":"a matter of importance","zh":"重要事项"}],"forms":[{"label":"单数","form":"importance"},{"label":"复数（多种重要性）","form":"importances"},{"label":"形容词","form":"important"}],"derivatives":[{"word":"important","pos":"adj.","zh":"重要的"},{"word":"import","pos":"v./n.","zh":"进口；输入；含义"},{"word":"importation","pos":"n.","zh":"进口；输入"},{"word":"unimportant","pos":"adj.","zh":"不重要的"}],"senses":[{"no":"01","title":"The quality of mattering","titleCN":"重要性本身","definition":"the quality of having great value, effect or significance","definitionCN":"具有重大价值、影响或意义的性质","example":"Few people doubt the importance of clean water.","exampleCN":"很少有人怀疑清洁水源的重要性。","why":"Importare meant 'to bring in'. Something important 'carries weight' into a situation, and the noun names that carried weight.","whyCN":"importare 意为“搬进来”。重要的东西把分量搬进某个局面，这个名词命名的就是那份被搬进来的分量。"},{"no":"02","title":"High standing in a group","titleCN":"重要地位","definition":"the state of having high status or influence among people","definitionCN":"在人群中拥有高地位或影响力的状态","example":"She rose to importance in the ministry.","exampleCN":"她在部里升至显要地位。","why":"Here the weight is social. The word measures not the deed but the position of the person who performs it.","whyCN":"这里的分量是社会性的。这个词衡量的不是行为，而是行为者所处的位置。"},{"no":"03","title":"A matter of real consequence","titleCN":"事关重大的事项","definition":"an issue whose outcome will seriously affect people or events","definitionCN":"结果会严重影响人或事件的问题","example":"The timing of the vote is a matter of great importance.","exampleCN":"投票的时机是极为重要的事项。","why":"Importance is attached to an issue when ignoring it would change the future. The word marks the consequence, not the size.","whyCN":"当忽视某个问题会改变未来时，重要性就被附着在它身上。这个词标记的是后果，而不是体量。"},{"no":"04","title":"Relative weight in a calculation","titleCN":"统计与决策中的权重","definition":"in statistics and decision-making, the relative weight assigned to a factor","definitionCN":"统计与决策中赋予某因素的相对权重","example":"The index gives greater importance to housing costs.","exampleCN":"该指数给住房成本更高的权重。","why":"This is the most literal quantitative use: importance becomes a number placed on one pan of a weighted average.","whyCN":"这是最字面的定量用法：重要性变成一个数字，被放到加权平均的某一只托盘上。"},{"no":"05","title":"Decisiveness for an outcome","titleCN":"对结果的关键性","definition":"the degree to which something determines how a situation ends","definitionCN":"某事物决定局面如何收尾的程度","example":"The importance of that final step is easy to miss.","exampleCN":"最后那一步的关键性很容易被忽略。","why":"The word shifts from value to causality. A step matters because the whole result depends on it.","whyCN":"这个词从价值转向因果。某一步重要，是因为整个结果都取决于它。"},{"no":"06","title":"Urgency that demands attention","titleCN":"紧迫性","definition":"the quality of requiring immediate attention because delay would be harmful","definitionCN":"因延误会有害而需要立即关注的性质","example":"They discussed the importance of acting before winter.","exampleCN":"他们讨论了在冬季前行动的重要性。","why":"Time gives weight. Something urgent is important because the window in which it can be done is closing.","whyCN":"时间赋予了分量。紧急之事之所以重要，是因为能够做它的窗口正在关闭。"},{"no":"07","title":"The value people place on something","titleCN":"所赋予的价值","definition":"the value or priority that people consciously attach to something","definitionCN":"人们有意识地赋予某物的价值或优先地位","example":"The school attaches great importance to music.","exampleCN":"这所学校非常重视音乐。","why":"Here importance is not a property but an act of valuing. The noun names what a group has decided to lift up.","whyCN":"这里的重要性不是属性，而是评价行为。名词命名的是一个群体决定抬高的东西。"},{"no":"08","title":"Considerable influence","titleCN":"相当大的影响力","definition":"the capacity to affect decisions or events on a large scale","definitionCN":"在大范围影响决策或事件的能力","example":"The region's importance in world trade has grown.","exampleCN":"该地区在世界贸易中的影响力上升了。","why":"The word moves from merit to power. What is important can move other things, and the noun measures that reach.","whyCN":"这个词从价值移到权力。重要的东西能推动其他事物，名词衡量的就是这种影响范围。"}],"etymology":{"intro":{"en":"Importance comes from Latin importare, 'to bring in, to carry in', and it keeps a mercantile image: something is carried into a situation and its weight changes the balance. The sense 'of consequence' developed in English and French in the 16th century.","cn":"importance 来自拉丁语 importare“搬进来、带入”，保留了商业意象：某物被搬进一个局面，它的重量改变了天平。‘有分量、有后果’的义项在 16 世纪于英语与法语中发展出来。"},"items":[{"era":"PIE *per- (reconstructed form)","en":"The root behind portare, 'to carry', is generally reconstructed as *per-, 'to lead, to pass through'. It also underlies English ferry and ford.","cn":"portare“搬运”背后的词根一般被重构为 *per-“引导、穿过”，它也是英语 ferry 与 ford 的来源。"},{"era":"LATIN portare / importare","en":"Portare meant 'to carry'. Importare added in- 'into' and meant 'to bring in', especially goods and, later, meaning.","cn":"portare 意为“搬运”。importare 加 in-“进入”，意为“搬进来”，尤指货物，后来也指意义。"},{"era":"LATIN importans (source uncertain)","en":"Medieval Latin used importans for 'of consequence'. The exact route from 'bringing in' to 'carrying weight in an argument' is a plausible but undocumented semantic shift, so it is labelled as uncertain.","cn":"中古拉丁语用 importans 表示“有后果的”。从“搬进来”到“在论证中有分量”的具体路径说得通，却缺乏文献确证，故标注来源不确定。"},{"era":"16C. FRENCH importance","en":"French importance named consequence and standing. English adopted the noun in the same century, first for personal rank, then for the weight of any matter.","cn":"法语 importance 指后果与地位。英语在同一世纪借入该名词，先指个人等级，后指任何事情的分量。"},{"era":"17C.–18C. MORAL AND RELIGIOUS USE","en":"Sermons and moral essays made 'a matter of importance' a fixed phrase, often meaning the eternal rather than the trivial.","cn":"布道文与道德随笔使“重要事项”成为固定说法，常指永恒之事而非琐事。"},{"era":"20C. STATISTICS AND MANAGEMENT","en":"Relative importance and importance weighting turned the word into a measurable quantity in surveys and decision models.","cn":"相对重要性与重要性加权把这个词变成调查与决策模型中的可测量数值。"}]},"similar":{"note":{"en":"The look-alike group separates the adjective, the verb and the unrelated noun that looks similar. The meaning group compares words for value, weight and consequence.","cn":"形近组区分形容词、动词与那个形似却无关的名词；词义组比较表示价值、分量与后果的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"important","ipa":"/ɪmˈpɔːtnt/","tag":"adjective","definition":"having great value or effect. It is the adjective form of this noun.","definitionCN":"具有重大价值或影响的。它是本名词的形容词形式。"},{"word":"import","ipa":"/ɪmˈpɔːt/","tag":"verb and noun","definition":"to bring goods in from abroad, or the goods themselves. It shares the root but kept the trade sense.","definitionCN":"从国外输入货物，或指所输入的货物。它同词根，但保留了贸易义。"},{"word":"importune","ipa":"/ˌɪmpɔːˈtjuːn/","tag":"verb","definition":"to ask persistently and annoyingly. It looks similar but comes from a different use of the same prefix, meaning 'not suitable'.","definitionCN":"烦人地反复请求。它形似，却出自同一前缀的另一用法，意为“不适宜”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"significance","ipa":"/ˈsɪɡnɪfɪkəns/","tag":"meaning and weight","definition":"the meaning or importance of something. It stresses what something signifies, while importance stresses the weight it carries.","definitionCN":"某物的意义或重要性。它强调所指，而 importance 强调所承载的分量。"},{"word":"weight","ipa":"/weɪt/","tag":"heaviness","definition":"the heaviness of an object, or the influence of an argument. It is the physical image behind the abstract noun.","definitionCN":"物体的重，或论证的影响力。它是抽象名词背后的物理意象。"},{"word":"consequence","ipa":"/ˈkɒnsɪkwəns/","tag":"result and rank","definition":"a result, or social standing. It matches senses 03 and 08 but always points to what follows.","definitionCN":"结果，或社会地位。它对应第 3、8 义项，但始终指向随后发生的事。"},{"word":"prominence","ipa":"/ˈprɒmɪnəns/","tag":"standing out","definition":"the state of being noticed or distinguished. It is close to sense 02 but stresses visibility rather than weight.","definitionCN":"被注意或出众的状态。它接近第 2 义项，但强调可见度而非分量。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks build importance from importare, 'to carry in', and let the image of a heavy object placed on the table cover status, urgency and statistical weight.","cn":"这些记忆钩从 importare“搬进来”搭起 importance，再用“重物被放上桌面”的意象覆盖地位、紧迫与统计权重。"},"normal":[{"en":"See import + -ance: what is carried in has weight. Importance is the weight it adds to the room.","cn":"看成 import 加 -ance：被搬进来的东西带有重量。importance 就是它给房间加上的分量。"},{"en":"Picture a document laid in the centre of the table: everyone's eyes move to it.","cn":"想象一份文件被放到桌子正中央：所有人的眼睛都移向它。"},{"en":"When a school 'attaches importance' to music, it physically lifts music onto the centre of the table.","cn":"当学校“重视”音乐时，它是把音乐搬到了桌子的中央。"},{"en":"In a weighted average, importance becomes a number on one pan.","cn":"在加权平均里，importance 变成某只托盘上的一个数字。"},{"en":"Remember the contrast: famous is seen by many, important moves many.","cn":"记住对比：famous 是被很多人看见，important 是能推动很多人。"}],"abstract":[{"en":"Keep one image: weight carried into a situation, changing which way it tips.","cn":"只记一个意象：被搬进局面的重量，改变了它往哪边倾。"},{"en":"Treat the word as a relation, not a property: nothing is important alone, only relative to an outcome.","cn":"把这个词当作关系而非属性：没有东西单独重要，只有相对于某个结果才重要。"},{"en":"Notice that the word can be measured, conferred or merely felt; each sense picks one of these.","cn":"注意这个词可以被测量、被赋予或只是被感觉，每个义项各取其一。"}]},"examples":[{"en":"The importance of sleep for memory is now well documented.","cn":"睡眠对记忆的重要性如今已有充分记录。"},{"en":"She attached little importance to public opinion.","cn":"她不太重视舆论。"},{"en":"The relative importance of the two factors is still debated.","cn":"这两个因素的相对重要性仍有争议。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“硬包腾斯”：硬把一包东西扛进屋，腾出位置给它——因为重要。","word":"importance"},"root":"拉丁语 importare“搬进来、带入”（in- 进入 + portare 搬运），中古拉丁 importans“有后果的”，经法语 importance 进入英语；核心是“搬进来的分量”。","sensesIntro":{"en":"Importance is weight carried into a situation. The eight senses place that weight in different spots: in the value of a thing, the standing of a person, the consequence of an issue, the coefficient in a calculation, the dependence of an outcome, the closing of a time window, the deliberate valuing by a group, and the power to move events. Nothing is important by itself; it is always important for something.","cn":"importance 是被搬进某个局面的分量。八个义项把这份分量放在不同位置：事物的价值、人的地位、问题的后果、计算中的系数、结果对某一步的依赖、时间窗口的关闭、群体的刻意重视，以及推动事件的力量。没有东西单独重要，它总是“对某事物”重要。"},"semanticMap":{"core":{"en":"Weight carried into a situation, changing the balance of what happens.","cn":"被搬进局面的分量，改变了事情的分量对比。"},"chain":["CARRY","WEIGHT","VALUE","STANDING","CONSEQUENCE","INFLUENCE"],"branches":[{"senses":"S1 · S7","en":"VALUE: the worth of a thing and the value people choose to give it.","cn":"价值：事物本身的价值，以及人们选择赋予的价值。"},{"senses":"S2 · S8","en":"STANDING: a person's rank and a region's power.","cn":"地位：个人的等级与地区的影响力。"},{"senses":"S3 · S5","en":"CONSEQUENCE: an issue that changes the future, a step the result depends on.","cn":"后果：改变未来的问题，结果所依赖的一步。"},{"senses":"S4","en":"MEASUREMENT: a relative weight in an index or model.","cn":"测量：指数或模型中的相对权重。"},{"senses":"S6","en":"TIME: weight created by a closing window.","cn":"时间：由关闭中的窗口所产生的分量。"}]},"affixes":{"intro":{"en":"Importance is important plus -ance, and important is the participle of importare. The items below show the 'carry' family and the trade sense that never quite left.","cn":"importance 是 important 加 -ance，而 important 是 importare 的分词。下列条目展示“搬运”词族，以及始终没有完全离开的贸易义。"},"latinIntro":{"en":"The Latin entries give the verb, the carrying root and the participle that shifted from 'bringing in' to 'mattering'.","cn":"拉丁语条目给出动词、搬运词根，以及从“搬进来”转向“有分量”的分词。"},"items":[{"word":"importance","structure":"important + -ance (abstract noun)","meaning":"the quality of mattering","meaningCN":"具有分量的性质","example":"The importance of the find was not recognized at once.","exampleCN":"这一发现的重要性没有立刻被认识到。"},{"word":"important","structure":"Latin importans, participle of importare","meaning":"carrying weight; of consequence","meaningCN":"有分量的；有后果的","example":"This is an important distinction.","exampleCN":"这是一个重要区别。"},{"word":"import","structure":"Latin importare (in- + portare)","meaning":"to bring in goods; meaning","meaningCN":"输入货物；含义","example":"The country imports most of its fuel.","exampleCN":"该国大部分燃料靠进口。"},{"word":"importation","structure":"import + -ation","meaning":"the act of bringing goods in","meaningCN":"输入货物的行为","example":"Importation of the grain resumed in spring.","exampleCN":"谷物进口在春季恢复。"},{"word":"importer","structure":"import + -er (agent)","meaning":"a person or firm that brings goods in","meaningCN":"进口商","example":"The importer pays the tariff.","exampleCN":"进口商支付关税。"},{"word":"imported","structure":"import + -ed (participial adjective)","meaning":"brought in from elsewhere","meaningCN":"从外地输入的","example":"Imported coal filled the gap.","exampleCN":"进口煤填补了缺口。"},{"word":"unimportant","structure":"un- (negation) + important","meaning":"of no consequence","meaningCN":"无关紧要的","example":"The difference is unimportant for our purpose.","exampleCN":"这一差别对我们的目的无关紧要。"},{"word":"self-importance","structure":"self + importance (compound)","meaning":"an exaggerated sense of one's own worth","meaningCN":"对自身价值的夸大感","example":"His self-importance irritated the team.","exampleCN":"他的自负让团队恼火。"}],"latinEntries":[{"word":"portare","structure":"1st conjugation verb","meaning":"to carry","meaningCN":"搬运；携带"},{"word":"importare","structure":"in- + portare","meaning":"to bring in","meaningCN":"搬进来；输入"},{"word":"importans","structure":"present participle of importare","meaning":"bringing in; of consequence","meaningCN":"带入的；有后果的"}]}},{"word":"increasingly","ipa_uk":"/ɪnˈkriːsɪŋli/","ipa_us":"/ɪnˈkriːsɪŋli/","definition_zh":"日益；越来越；不断增加地；愈发","definition_en":"more and more, or to a degree that keeps growing over time","core_image":"温度计里的水银柱一格格往上爬，停不下来","scene":"City rents have become increasingly difficult for young families to afford.","sceneCN":"这里 increasingly 是「越来越」（第 2 个义项：程度持续加深）；句意：对年轻家庭来说，城市房租变得越来越难负担。图中可辨识物件：向上爬的水银柱、几张租金单、一对年轻夫妇的肩膀。","pos":[{"tag":"adv.","zh":"日益；越来越；不断增加地"}],"collocations":[{"phrase":"increasingly difficult","zh":"越来越困难"},{"phrase":"increasingly common","zh":"日益普遍"},{"phrase":"increasingly important","zh":"越来越重要"},{"phrase":"increasingly reliant on","zh":"越来越依赖"},{"phrase":"increasingly aware","zh":"日益意识到"},{"phrase":"increasingly rare","zh":"越来越罕见"}],"forms":[{"label":"原级","form":"increasingly"},{"label":"对应形容词","form":"increasing"},{"label":"动词","form":"increase"},{"label":"名词","form":"increase"}],"derivatives":[{"word":"increase","pos":"v./n.","zh":"增加；增长"},{"word":"increasing","pos":"adj.","zh":"不断增加的"},{"word":"increment","pos":"n.","zh":"增量；加薪"},{"word":"crescent","pos":"adj./n.","zh":"新月形的；新月"}],"senses":[{"no":"01","title":"In growing quantity","titleCN":"在数量上不断增加地","definition":"in a quantity that rises steadily over time","definitionCN":"以随时间稳定上升的数量","example":"The centre receives increasingly large data sets.","exampleCN":"该中心收到越来越大的数据集。","why":"Increase comes from in- plus crescere, 'to grow'. The adverb marks growth that has not stopped, so the quantity is always one step beyond the last measurement.","whyCN":"increase 来自 in- 加 crescere“生长”。这个副词标记尚未停止的增长，因此数量总比上一次测量多一步。"},{"no":"02","title":"To a deepening degree","titleCN":"程度上不断加深地","definition":"to a degree that becomes stronger as time passes","definitionCN":"强度随时间推移而增强的程度","example":"The work became increasingly demanding.","exampleCN":"这项工作变得要求越来越高。","why":"Here the growth is in intensity, not count. A quality keeps rising, and the adverb says the rise is still in progress.","whyCN":"这里增长的是强度而非数量。一种性质持续上升，副词说明上升仍在进行。"},{"no":"03","title":"With rising frequency","titleCN":"频率越来越高","definition":"more often as time goes on","definitionCN":"随时间推移发生得更频繁","example":"Storms occur increasingly often along the coast.","exampleCN":"沿海的风暴发生得越来越频繁。","why":"The same growth is now counted in events per year. Each interval holds more occurrences than the one before.","whyCN":"同一种增长现在按每年事件数来计。每个时间段里的发生次数都多于前一个。"},{"no":"04","title":"Becoming the normal state","titleCN":"逐渐成为常态地","definition":"in a way that is becoming standard rather than exceptional","definitionCN":"以逐渐成为常规而非例外的方式","example":"Remote work is increasingly the default.","exampleCN":"远程工作正日益成为默认选项。","why":"Growth applies to prevalence. What was an exception keeps adding members until it is the ordinary case.","whyCN":"增长作用于普及度。原本是例外的事物不断增添成员，直到成为普通情形。"},{"no":"05","title":"Before a comparative, intensifying it","titleCN":"修饰比较级、加强程度","definition":"used before a comparative adjective to say that the comparison itself keeps growing","definitionCN":"置于比较级形容词前，表示比较本身持续加大","example":"The exam is becoming increasingly harder to pass.","exampleCN":"这场考试正变得越来越难通过。","why":"The adverb doubles the comparison: not merely harder, but harder by a growing margin.","whyCN":"这个副词把比较加倍：不只是更难，而是以越来越大的幅度变难。"},{"no":"06","title":"As a trend across a population","titleCN":"作为群体趋势地","definition":"describing a pattern that spreads through a group rather than a single case","definitionCN":"描述在群体中扩散而非单一案例的模式","example":"Voters are increasingly sceptical of the promise.","exampleCN":"选民对这个承诺越来越怀疑。","why":"The growth is now statistical. The adverb says the proportion, not the individual, is moving.","whyCN":"这里的增长是统计性的。副词说明移动的是比例，而不是个人。"},{"no":"07","title":"At a rising rate","titleCN":"以不断加快的速度","definition":"at a pace that itself accelerates","definitionCN":"以本身正在加快的速度","example":"The glacier is retreating increasingly fast.","exampleCN":"这座冰川正以越来越快的速度退缩。","why":"Here growth applies to the rate of growth. The adverb can describe acceleration, not just motion.","whyCN":"这里增长作用于增长速率本身。这个副词可以描述加速，而不仅是移动。"},{"no":"08","title":"In a way that keeps accumulating","titleCN":"持续累积地","definition":"so that effects pile up rather than level off","definitionCN":"使效果不断叠加而非趋于平稳","example":"The evidence is increasingly pointing to one conclusion.","exampleCN":"证据越来越指向同一个结论。","why":"The word implies no plateau. Each new item adds to a pile that has no visible top.","whyCN":"这个词暗示没有平台期。每一份新证据都加到一个看不见顶的堆上。"}],"etymology":{"intro":{"en":"Increasingly is the adverb of increasing, which is the participle of increase. Increase goes back to Latin increscere, 'to grow in or upon'. The word is therefore a participle carrying a Latin verb of growth, and its eight senses are eight kinds of growth.","cn":"increasingly 是 increasing 的副词，而 increasing 是 increase 的分词。increase 可追溯到拉丁语 increscere“生长、增长”。所以这个词是一个承载拉丁“生长”动词的分词，八个义项就是八种生长。"},"items":[{"era":"PIE *ker- (reconstructed form)","en":"The root behind crescere, 'to grow', is reconstructed as *ker-, 'to grow'. The link is generally accepted but remains a reconstruction, not a recorded form.","cn":"crescere“生长”背后的词根被重构为 *ker-“生长”。这一联系一般被接受，但仍是重构形式，而非有记录的形式。"},{"era":"LATIN crescere / increscere","en":"Crescere meant 'to grow, to arise'. In- added direction, giving increscere, 'to grow upon, to increase'. The verb described plants, numbers and reputations alike.","cn":"crescere 意为“生长、出现”。in- 添加方向，构成 increscere“长上去、增加”。这个动词既用于植物，也用于数字与名声。"},{"era":"14C. FRENCH encreistre","en":"Old French encreistre carried the verb into Middle English as increase. The noun and verb were borrowed together, a rare double arrival.","cn":"古法语 encreistre 把动词带入中古英语作 increase。名词与动词一同借入，这是少见的成对到达。"},{"era":"ENGLISH -ing / -ingly","en":"The present participle increasing plus -ly produced increasingly in the 17th century. The suffix -ly marks manner or degree, not time.","cn":"现在分词 increasing 加 -ly 在 17 世纪产生 increasingly。后缀 -ly 标记方式或程度，而非时间。"},{"era":"18C.–19C. POLITICAL AND ECONOMIC WRITING","en":"The adverb spread in writing about population, prices and industry, where trends were first plotted as lines on a page.","cn":"这个副词在关于人口、物价与工业的写作中扩散，当时趋势第一次被画成纸上的线。"},{"era":"20C. GENERAL INTENSIFIER","en":"Modern English uses it before almost any adjective: increasingly rare, increasingly automated, increasingly online. The growth image becomes a general intensifier.","cn":"现代英语把它用在几乎任何形容词前：越来越罕见、越来越自动化、越来越线上化。生长意象成了通用强调手段。"}]},"similar":{"note":{"en":"The look-alike group separates the verb, the participle and the adverb. The meaning group compares words for growth and repetition.","cn":"形近组区分动词、分词与副词；词义组比较表示增长与重复的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"increase","ipa":"/ɪnˈkriːs/","tag":"verb and noun","definition":"to become larger in number or amount. It is the process that the adverb modifies.","definitionCN":"数量或数额变大。它是副词所修饰的过程。"},{"word":"increasing","ipa":"/ɪnˈkriːsɪŋ/","tag":"participle and adjective","definition":"growing; rising. It describes the trend itself, without saying that a comparison is being made.","definitionCN":"增长中的；上升的。它描述趋势本身，并不表示正在作比较。"},{"word":"increment","ipa":"/ˈɪŋkrəmənt/","tag":"noun","definition":"a small increase or an added amount. It is the step, not the trend.","definitionCN":"小幅增加或增加量。它是台阶，不是趋势。"}]},{"heading":"NEAR MEANING","entries":[{"word":"progressively","ipa":"/prəˈɡresɪvli/","tag":"step by step","definition":"gradually, in stages. It stresses the sequence of steps rather than the rising amount.","definitionCN":"逐步地、分阶段地。它强调步骤的顺序，而非上升的量。"},{"word":"gradually","ipa":"/ˈɡrædʒuəli/","tag":"slowly","definition":"slowly and by small degrees. It says the change is slow, while increasingly says the change is upward.","definitionCN":"缓慢而小幅度地。它说变化慢，而 increasingly 说变化在上升。"},{"word":"ever more","ipa":"/ˌevə ˈmɔː/","tag":"fixed phrase","definition":"an emphatic way of saying increasingly, common in formal writing. It makes the same comparison with more force.","definitionCN":"increasingly 的强调说法，常见于正式写作。它用更强的力度作同样的比较。"},{"word":"more and more","ipa":"/ˌmɔːr ən ˈmɔː/","tag":"everyday phrase","definition":"the spoken equivalent, used before adjectives and nouns. It carries the same upward image without the Latin root.","definitionCN":"口语对应说法，用于形容词与名词前。它带同样的上升意象，却没有拉丁词根。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks build increasingly from in- plus crescere, 'to grow', and keep the rising column of mercury in view.","cn":"这些记忆钩从 in- 加 crescere“生长”搭起 increasingly，并让上升的水银柱始终在眼前。"},"normal":[{"en":"See crescere: to grow. Increasingly means the growth is still going on as we speak.","cn":"看见 crescere：生长。increasingly 意味着我们说话时增长还在继续。"},{"en":"Picture a thermometer climbing one mark at a time and never settling.","cn":"想象温度计一格格往上爬，始终不停。"},{"en":"Pair it with a comparative: increasingly rare means rare, and rarer each year.","cn":"把它和比较级搭在一起：increasingly rare 意为罕见，而且一年比一年更罕见。"},{"en":"In a survey, the adverb moves the percentage, not the person.","cn":"在调查里，这个副词推动的是百分比，而不是个人。"},{"en":"Remember the family: crescent, increment and crescendo all carry the same 'grow' idea.","cn":"记住词族：crescent、increment、crescendo 都带着同一个“生长”观念。"}],"abstract":[{"en":"Keep one image: a line that climbs without ever drawing a flat top.","cn":"只记一个意象：一条一直上升、从未画出平顶的线。"},{"en":"Treat the word as a comment on direction, not on speed; acceleration is only its sense 07.","cn":"把这个词当作对方向的评述，而不是对速度的评述；加速只是第 7 义项。"},{"en":"Notice that the same adverb can make a warning or a compliment: rising cost, rising skill.","cn":"注意同一个副词既能发出警告，也能表达赞美：成本上升，技能上升。"}]},"examples":[{"en":"Consumers are increasingly careful about what they buy online.","cn":"消费者在网上购物时越来越谨慎。"},{"en":"The technology has become increasingly affordable.","cn":"这项技术已变得越来越可负担。"},{"en":"Researchers are increasingly turning to machine learning.","cn":"研究人员越来越多地转向机器学习。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“因亏利息里”：因为亏了利息，日子越来越紧——越来越、日益。","word":"increasingly"},"root":"increase 来自拉丁语 increscere“生长、增加”（in- 向上 + crescere 生长），加 -ing 与副词后缀 -ly 构成 increasingly，17 世纪起用于表示趋势持续上升。","sensesIntro":{"en":"Increasingly is one adverb doing one job: marking a rise that is still rising. The rise can be counted (S1), felt as intensity (S2), counted as frequency (S3), measured as prevalence (S4), doubled onto a comparative (S5), read as a population trend (S6), applied to a rate (S7) or left to accumulate (S8). In every case the line has no flat top yet.","cn":"increasingly 是一个副词做一件事：标记仍在上升的上升。这种上升可以被计数（第 1）、被感受为强度（第 2）、按频率计数（第 3）、按普及度衡量（第 4）、叠加到比较级上（第 5）、读作群体趋势（第 6）、作用于速率（第 7），或任其累积（第 8）。每一种情形里，那条线都还没有画出平顶。"},"semanticMap":{"core":{"en":"A rise that continues, so that each moment exceeds the one before.","cn":"持续进行的上升，使每一刻都超过前一刻。"},"chain":["GROW","RISE","REPEAT","EXTEND","ACCUMULATE","NORMALIZE"],"branches":[{"senses":"S1 · S3","en":"COUNT: larger amounts and more frequent events.","cn":"计数：更大的数量与更频繁的事件。"},{"senses":"S2 · S7","en":"DEGREE AND SPEED: stronger qualities, accelerating rates.","cn":"程度与速度：更强的性质、不断加快的速率。"},{"senses":"S5","en":"COMPARISON: the adverb doubles a comparative, so the gap itself widens.","cn":"比较：副词把比较级加倍，使差距本身不断扩大。"},{"senses":"S4 · S6","en":"POPULATION: what was exceptional becomes the ordinary pattern.","cn":"群体：原本例外之事成为普通模式。"},{"senses":"S8","en":"ACCUMULATION: evidence or effects piling up.","cn":"累积：证据或效果不断堆高。"}]},"affixes":{"intro":{"en":"Increasingly is increase plus two endings. The items below show the growth family and the two directions Latin gives it: up and down.","cn":"increasingly 是 increase 加两个词尾。下列条目展示“生长”词族，以及拉丁语给它的两个方向：向上与向下。"},"latinIntro":{"en":"The Latin entries give the verb and its root. They explain why a word about rising numbers is also the source of words about moonlight and music.","cn":"拉丁语条目给出动词及其词根。它们解释了为什么一个关于数字上升的词，也是关于月光与音乐的词的来源。"},"items":[{"word":"increasingly","structure":"increasing + -ly (adverb of degree)","meaning":"more and more","meaningCN":"越来越；日益","example":"The task is increasingly complex.","exampleCN":"这项任务越来越复杂。"},{"word":"increase","structure":"Latin increscere","meaning":"to grow larger","meaningCN":"变大；增长","example":"Sales increased by a fifth.","exampleCN":"销售额增长了五分之一。"},{"word":"increasing","structure":"increase + -ing (participle)","meaning":"rising, growing","meaningCN":"上升的；增长的","example":"There is increasing pressure on the system.","exampleCN":"系统承受的压力在增大。"},{"word":"increment","structure":"Latin incrementum, from increscere","meaning":"an added amount","meaningCN":"增加量","example":"The salary rises in annual increments.","exampleCN":"工资按年度增量上调。"},{"word":"incremental","structure":"increment + -al","meaning":"step-by-step, in small additions","meaningCN":"逐步的、小幅累加的","example":"Progress was incremental, not sudden.","exampleCN":"进展是逐步的，不是突然的。"},{"word":"decrease","structure":"Latin decrescere (de- + crescere)","meaning":"to grow smaller","meaningCN":"减少；变小","example":"Demand decreased after the tax.","exampleCN":"加税后需求下降。"},{"word":"crescent","structure":"Latin crescens, participle of crescere","meaning":"a growing moon","meaningCN":"正在生长的月亮","example":"A crescent moon hung over the valley.","exampleCN":"一弯新月挂在山谷上方。"},{"word":"crescendo","structure":"Italian, from Latin crescendo","meaning":"a gradual increase in volume","meaningCN":"音量逐渐增强","example":"The music reached a crescendo.","exampleCN":"音乐达到高潮。"}],"latinEntries":[{"word":"crescere","structure":"3rd conjugation verb","meaning":"to grow, to arise","meaningCN":"生长；出现"},{"word":"increscere","structure":"in- + crescere","meaning":"to grow upon; to increase","meaningCN":"长上去；增加"},{"word":"incrementum","structure":"increscere + -mentum","meaning":"growth; an addition","meaningCN":"生长；增加物"}]}},{"word":"independent","ipa_uk":"/ˌɪndɪˈpendənt/","ipa_us":"/ˌɪndɪˈpendənt/","definition_zh":"独立的；自主的；不相关的；无党派的；（统计学）独立的","definition_en":"not controlled by or relying on another person, group or state, or not connected with something else","core_image":"一根柱子自己站稳，没有靠墙","scene":"The two studies were designed by independent teams that never compared notes.","sceneCN":"这里 independent 是「互不隶属、各自独立的」（第 5 个义项：互不相关）；句意：这两项研究由互不通气的独立团队设计。图中可辨识物件：两间分开的实验室、各自的白板、中间没有相连的走廊。","pos":[{"tag":"adj.","zh":"独立的；自主的；不相关的；无党派的"},{"tag":"n.","zh":"无党派人士；独立候选人"}],"collocations":[{"phrase":"independent of","zh":"不依赖……的；不受……影响的"},{"phrase":"financially independent","zh":"经济独立的"},{"phrase":"independent state","zh":"独立国家"},{"phrase":"independent study","zh":"独立研究"},{"phrase":"independent candidate","zh":"独立候选人"},{"phrase":"independent variable","zh":"自变量"}],"forms":[{"label":"原级","form":"independent"},{"label":"比较级","form":"more independent"},{"label":"最高级","form":"most independent"},{"label":"名词","form":"independence"},{"label":"副词","form":"independently"}],"derivatives":[{"word":"independence","pos":"n.","zh":"独立；自主"},{"word":"independently","pos":"adv.","zh":"独立地；各自地"},{"word":"dependent","pos":"adj.","zh":"依赖的；受扶养的"},{"word":"interdependent","pos":"adj.","zh":"相互依存的"}],"senses":[{"no":"01","title":"Not relying on others","titleCN":"不依赖他人的","definition":"able to act or live without help from another person","definitionCN":"能够在没有他人帮助的情况下行动或生活的","example":"She became independent at eighteen.","exampleCN":"她十八岁就独立了。","why":"Dependere means 'to hang from'. Independent is in- 'not' plus that verb: nothing is hanging from anyone else.","whyCN":"dependere 意为“悬挂于”。independent 就是 in-“不”加这个动词：没有东西挂在别人身上。"},{"no":"02","title":"Self-governing as a state","titleCN":"国家自主的","definition":"governing itself and not subject to another state","definitionCN":"自行治理、不受他国支配的","example":"The country became independent in 1960.","exampleCN":"该国于 1960 年独立。","why":"The hanging image scales up: a nation that hangs from an empire is dependent, and cutting that line makes it independent.","whyCN":"悬挂意象放大：挂在帝国链条上的国家是依附的，剪断这条线便成为独立。"},{"no":"03","title":"A body free of outside control","titleCN":"机构独立自主的","definition":"describing an institution that is not controlled by government or another owner","definitionCN":"描述不受政府或另一所有者控制的机构","example":"An independent auditor reviewed the accounts.","exampleCN":"一位独立审计师审查了账目。","why":"Independence here is a firewall: the body must not hang from the organization it is judging.","whyCN":"这里的独立是一道防火墙：机构不得挂在它所评判的组织身上。"},{"no":"04","title":"Judging for oneself","titleCN":"判断自主的","definition":"forming conclusions from one's own reasoning rather than accepting others'","definitionCN":"依据自己的推理得出结论，而非接受他人结论","example":"She is an independent thinker, not a follower.","exampleCN":"她是个独立思考者，而不是跟随者。","why":"This is the inward sense: the mind has no line tethering it to a voice outside.","whyCN":"这是向内的义项：心智没有一条线把它系在外面的声音上。"},{"no":"05","title":"Not connected with something else","titleCN":"与……无关的","definition":"separate in origin or operation, with no causal connection","definitionCN":"在来源或运作上分开、没有因果联系的","example":"The two results came from independent experiments.","exampleCN":"这两个结果来自各自独立的实验。","why":"Here 'not hanging from' means 'not hanging from the same hook'. Two experiments share no support.","whyCN":"这里的“不悬挂”意为“不挂在同一只钩子上”。两个实验不共享支撑。"},{"no":"06","title":"Statistically unrelated","titleCN":"统计学上独立的","definition":"in statistics, describing variables whose values do not affect one another's probabilities","definitionCN":"统计学中描述取值不影响彼此概率的变量","example":"In this model the two variables are independent.","exampleCN":"在这个模型中两个变量相互独立。","why":"Probabilities behave as if each variable hangs from its own hook: knowing one tells you nothing about the other.","whyCN":"概率表现得就像每个变量各自挂在自己的钩子上：知道其中一个，对另一个毫无提示。"},{"no":"07","title":"Not belonging to a party","titleCN":"无党派的","definition":"not aligned with an established political party","definitionCN":"不与既有政党和结盟的","example":"An independent candidate won the seat.","exampleCN":"一位独立候选人赢得了席位。","why":"The noun use grew from this sense: a person who will not hang from a party machine.","whyCN":"名词用法由此义长出：一个不肯挂在党派机器上的人。"},{"no":"08","title":"Financially self-supporting","titleCN":"经济自立的","definition":"earning enough to support oneself without subsidy","definitionCN":"收入足以自给、不需补贴的","example":"The journal is financially independent.","exampleCN":"这份期刊在经济上独立。","why":"Money is the most concrete tether. The word says the rope to a funder has been cut.","whyCN":"金钱是最具体的绳索。这个词说通向出资者的绳子已被割断。"}],"etymology":{"intro":{"en":"Independent is a negative prefix laid on a Latin verb of hanging. Dependere, 'to hang down from', gave dependent, and in- 'not' reversed it. The word first appeared in English in the 17th century in grammar and philosophy before it moved to people and states.","cn":"independent 是一个否定前缀加在拉丁“悬挂”动词上。dependere“挂下来”给出 dependent，in-“不”把它反转。这个词 17 世纪先出现在英语的语法与哲学中，之后才转向人与国家。"},"items":[{"era":"PIE *(s)pen- (reconstructed form)","en":"The root behind pendere, 'to hang', is reconstructed as *(s)pen-, 'to draw, to stretch'. The link is generally accepted but remains a reconstruction.","cn":"pendere“悬挂”背后的词根被重构为 *(s)pen-“拉、伸”。这一联系一般被接受，但仍是重构形式。"},{"era":"LATIN pendere / dependere","en":"Pendere meant 'to hang'. De- 'down' plus pendere gave dependere, 'to hang down from, to be attached to, to rely on'.","cn":"pendere 意为“悬挂”。de-“向下”加 pendere 构成 dependere“挂在……下面、附着于、依赖”。"},{"era":"LATIN in- (negation)","en":"The prefix in- becomes im- before b, p and m, but before d it stays in-. Here it negates the hanging relation rather than intensifying it.","cn":"前缀 in- 在 b、p、m 前变为 im-，在 d 前保持 in-。这里是它否定悬挂关系，而不是加强。"},{"era":"1610s. ENGLISH, GRAMMAR AND PHILOSOPHY","en":"Independent first described a clause or proposition that stands on its own. The political sense followed in the 17th century during debates about church and state authority.","cn":"independent 最早描述能自行站立的从句或命题。政治义在 17 世纪关于教会与国家权威的争论中随之出现。"},{"era":"18C.–19C. POLITICS AND EDUCATION","en":"Independent states, independent newspapers and independent study all generalize the same image of a line cut.","cn":"独立国家、独立报纸、独立研究都把同一个“剪断绳索”的意象普遍化。"},{"era":"20C. STATISTICS","en":"Statistical independence gave the adjective a precise mathematical meaning: two variables whose joint probability equals the product of their separate probabilities.","cn":"统计独立性赋予这个形容词精确的数学含义：两个变量的联合概率等于各自概率的乘积。"}]},"similar":{"note":{"en":"The look-alike group separates the two adjectives and the noun of state. The meaning group compares words for freedom, separation and self-sufficiency.","cn":"形近组区分两个形容词与状态名词；词义组比较表示自由、分离与自足的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"dependent","ipa":"/dɪˈpendənt/","tag":"adjective","definition":"relying on another for support. It is the exact opposite and comes from the same hanging verb.","definitionCN":"依靠他人支持的。它是精确的反义词，出自同一个“悬挂”动词。"},{"word":"dependence","ipa":"/dɪˈpendəns/","tag":"noun","definition":"the state of relying on something, or addiction. It is the noun of the opposite adjective.","definitionCN":"依赖某物的状态，或指成瘾。它是反义形容词的名词。"},{"word":"independence","ipa":"/ˌɪndɪˈpendəns/","tag":"noun","definition":"the state of being independent. It is the noun form of this word.","definitionCN":"独立的状态。它是本词的名词形式。"}]},{"heading":"NEAR MEANING","entries":[{"word":"autonomous","ipa":"/ɔːˈtɒnəməs/","tag":"self-ruling","definition":"governing itself, especially a region or institution. It stresses self-rule rather than freedom from reliance.","definitionCN":"自行治理，尤指地区或机构。它强调自治，而非免于依赖。"},{"word":"self-sufficient","ipa":"/ˌself səˈfɪʃnt/","tag":"needing nothing","definition":"able to supply all one's own needs. It is more concrete than independent and usually refers to food, money or energy.","definitionCN":"能自给所有需要。它比 independent 更具体，通常指食物、金钱或能源。"},{"word":"separate","ipa":"/ˈseprət/","tag":"apart","definition":"not joined or connected. It matches sense 05 but says nothing about control or support.","definitionCN":"不相连的。它对应第 5 义项，但不涉及控制或支撑。"},{"word":"neutral","ipa":"/ˈnjuːtrəl/","tag":"not taking sides","definition":"not supporting any party in a dispute. It is close to sense 07 but concerns allegiance, not structure.","definitionCN":"在争端中不支持任何一方。它接近第 7 义项，但涉及效忠，而非结构。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks build independent from in- 'not' plus dependere, 'to hang from', and keep the image of a pillar standing without a wall.","cn":"这些记忆钩从 in-“不”加 dependere“悬挂于”搭起 independent，并保留“柱子不靠墙也站住”的意象。"},"normal":[{"en":"See in- + depend: not hanging from anyone. That is the whole word.","cn":"看成 in- 加 depend：不挂在任何人身上。整个词就是这个意思。"},{"en":"Picture a pillar that carries its own roof while the wall beside it is removed.","cn":"想象一根柱子自己撑住屋顶，旁边的墙已被拆掉。"},{"en":"A country that cuts the line to an empire becomes independent.","cn":"把通向帝国的线剪断的国家就成为独立国家。"},{"en":"An independent thinker has no rope tied to someone else's opinion.","cn":"独立思考者没有绳子系在别人的观点上。"},{"en":"Remember the pair: dependent hangs, independent does not.","cn":"记住这一对：dependent 挂着，independent 不挂。"}],"abstract":[{"en":"Keep one image: a support removed, and the thing still standing.","cn":"只记一个意象：支撑被撤走，而东西仍然立着。"},{"en":"Treat the word as a statement about lines, not about loneliness.","cn":"把这个词当作关于“连线”的陈述，而不是关于孤独的陈述。"},{"en":"Notice that independence can be structural, statistical or financial; only context tells you which line was cut.","cn":"注意独立可以是结构性的、统计性的或财政性的；只有语境告诉你剪断的是哪根线。"}]},"examples":[{"en":"The commission must remain independent of the government.","cn":"该委员会必须保持独立于政府之外。"},{"en":"The two variables are statistically independent.","cn":"这两个变量在统计上相互独立。"},{"en":"She registered as an independent before the election.","cn":"选举前她登记为无党派候选人。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“因敌喷弹”：敌人喷来弹雨也不靠别人挡，自己站稳——独立的。","word":"independent"},"root":"in-“不”加拉丁语 dependere“悬挂于、依赖”（de- 向下 + pendere 悬挂）；17 世纪先用于语法与哲学，后扩展到政治、机构与统计。","sensesIntro":{"en":"Independent is one negation applied to one verb of hanging. Whatever hangs from another is dependent; cut the line and the thing is independent. The eight senses cut different lines: the line to parents, to an empire, to a government, to others' opinions, to the same experiment, to another variable's probability, to a party, and to a funder.","cn":"independent 是一个否定加在一个“悬挂”动词上。挂在别处的东西是依附的；剪断那条线，它就独立了。八个义项剪断的是不同的线：通向父母的线、通向帝国的线、通向政府的线、通向他人观点的线、通向同一实验的线、通向另一个变量概率的线、通向政党的线、通向出资者的线。"},"semanticMap":{"core":{"en":"Standing without a support line: nothing hangs from another.","cn":"没有支撑线地立着：没有任何东西挂在别处。"},"chain":["HANG","ATTACH","SUPPORT","SEPARATE","GOVERN","STAND"],"branches":[{"senses":"S1 · S8","en":"PERSON: living and paying one's own way.","cn":"个人：自己生活、自己付账。"},{"senses":"S2 · S3 · S7","en":"INSTITUTIONS: a state, an auditor, a candidate outside party control.","cn":"机构：国家、审计者、政党控制之外的候选人。"},{"senses":"S4","en":"MIND: conclusions formed without borrowed authority.","cn":"心智：不借权威而得出的结论。"},{"senses":"S5","en":"SEPARATION: no shared origin or operation.","cn":"分离：没有共同来源或运作。"},{"senses":"S6","en":"MATHEMATICS: probabilities that ignore each other.","cn":"数学：彼此不相影响的概率。"}]},"affixes":{"intro":{"en":"Independent is in- plus the participle of dependere. The items below show the hanging family in both directions, and show what the prefix does to it.","cn":"independent 是 in- 加 dependere 的分词。下列条目展示“悬挂”词族的正反两面，以及前缀对它的作用。"},"latinIntro":{"en":"The Latin entries give the hanging verb and its prefix-modified form. They explain why dependence and independence are two readings of the same rope.","cn":"拉丁语条目给出悬挂动词及其加前缀形式。它们解释了为什么依赖与独立是同一根绳子的两种读法。"},"items":[{"word":"independent","structure":"in- (negation) + dependent","meaning":"not relying on another","meaningCN":"不依赖他人的","example":"The laboratory is independent of the university.","exampleCN":"这个实验室独立于大学之外。"},{"word":"independence","structure":"independent + -ence (state noun)","meaning":"the state of not being controlled","meaningCN":"不受控制的状态","example":"Independence came after a long struggle.","exampleCN":"独立在长期斗争之后到来。"},{"word":"independently","structure":"independent + -ly","meaning":"without reliance on another","meaningCN":"不依赖他人地","example":"The two groups worked independently.","exampleCN":"两个小组各自独立工作。"},{"word":"dependent","structure":"Latin dependens, participle of dependere","meaning":"hanging from; relying on","meaningCN":"悬挂于；依赖的","example":"The child is still dependent on her parents.","exampleCN":"这个孩子仍依赖父母。"},{"word":"depend","structure":"Latin dependere, shortened","meaning":"to rely on; to be decided by","meaningCN":"依赖；取决于","example":"The result depends on the weather.","exampleCN":"结果取决于天气。"},{"word":"dependence","structure":"depend + -ence","meaning":"the state of relying on something","meaningCN":"依赖某物的状态","example":"Dependence on imported oil is risky.","exampleCN":"依赖进口石油有风险。"},{"word":"interdependent","structure":"inter- (between) + dependent","meaning":"relying on each other","meaningCN":"相互依赖的","example":"The two economies are interdependent.","exampleCN":"这两个经济体相互依存。"},{"word":"pendant","structure":"Old French pendant, from pendere","meaning":"something that hangs","meaningCN":"垂挂之物；吊坠","example":"A silver pendant hung from the chain.","exampleCN":"一枚银吊坠挂在链子上。"}],"latinEntries":[{"word":"pendere","structure":"3rd conjugation verb","meaning":"to hang, to weigh","meaningCN":"悬挂；称重"},{"word":"dependere","structure":"de- + pendere","meaning":"to hang down from; to rely on","meaningCN":"悬挂于；依赖"},{"word":"dependens","structure":"present participle","meaning":"hanging from; dependent","meaningCN":"悬挂于的；依赖的"}]}},{"word":"independently","ipa_uk":"/ˌɪndɪˈpendəntli/","ipa_us":"/ˌɪndɪˈpendəntli/","definition_zh":"独立地；自主地；各自分别地；不受影响地","definition_en":"in a way that does not rely on or is not controlled by another person or thing","core_image":"两个人各自关上门，在各自的纸上写下答案，互不看对方","scene":"Two laboratories independently reached the same conclusion within a month of each other.","sceneCN":"这里 independently 是「各自分别地」（第 4 个义项：不同团队互不知情地做同一件事）；句意：两个实验室在一个月内各自得出同一结论。图中可辨识物件：两扇关着的门、两份分开的记录、同一个结论的两行字。","pos":[{"tag":"adv.","zh":"独立地；自主地；各自地；不受影响地"}],"collocations":[{"phrase":"work independently","zh":"独立工作"},{"phrase":"independently of","zh":"独立于……；不受……影响"},{"phrase":"arrive independently at","zh":"各自独立得出"},{"phrase":"independently owned","zh":"独立所有的"},{"phrase":"independently verified","zh":"经独立核实的"},{"phrase":"act independently","zh":"自主行动"}],"forms":[{"label":"原级","form":"independently"},{"label":"对应形容词","form":"independent"},{"label":"名词","form":"independence"}],"derivatives":[{"word":"independent","pos":"adj.","zh":"独立的"},{"word":"independence","pos":"n.","zh":"独立；自主"},{"word":"dependent","pos":"adj.","zh":"依赖的"},{"word":"interdependently","pos":"adv.","zh":"相互依存地"}],"senses":[{"no":"01","title":"Without relying on anyone","titleCN":"不依赖他人地","definition":"in a way that requires no help or support from another","definitionCN":"以不需要他人帮助或支持的方式","example":"She completed the survey independently.","exampleCN":"她独立完成了这项调查。","why":"The adverb modifies the verb and removes the support line: the action was done with no rope attached to anyone else.","whyCN":"这个副词修饰动词并撤掉支撑线：动作完成时，没有绳子系在别人身上。"},{"no":"02","title":"Under one's own authority","titleCN":"自主地","definition":"by one's own decision rather than by instruction from above","definitionCN":"由自己决定而非按上级指示","example":"The agency acted independently of the ministry.","exampleCN":"该机构自主于部之外行事。","why":"Here the broken line is a chain of command. The act was authorized from inside, not outside.","whyCN":"这里被剪断的是指挥链。行动的授权来自内部，而非外部。"},{"no":"03","title":"Separately, each on its own","titleCN":"各自分别地","definition":"in separate cases or units rather than together","definitionCN":"以分开的个案或单位而非一起的方式","example":"Each plant was tested independently.","exampleCN":"每株植物都单独测试。","why":"The adverb counts units. Nothing hangs from the same hook, so results cannot leak from one case to the next.","whyCN":"副词按单位计数。没有东西挂在同一只钩子上，结果便不会从一例漏到另一例。"},{"no":"04","title":"By separate researchers, without contact","titleCN":"由不同研究者独立地","definition":"describing parallel work done without communication between the parties","definitionCN":"描述各方之间没有沟通的平行工作","example":"Two teams independently arrived at the same formula.","exampleCN":"两个团队各自独立得出了同一公式。","why":"This is the strongest scientific use: the agreement counts as evidence only because neither team could see the other's work.","whyCN":"这是最强的科学用法：一致之所以能算证据，正因为两个团队都看不到对方的工作。"},{"no":"05","title":"Unaffected by another factor","titleCN":"不受另一因素影响地","definition":"in a way that is not caused or changed by a stated influence","definitionCN":"以不被所述因素引起或改变的方式","example":"Prices moved independently of demand.","exampleCN":"价格变动不受需求影响。","why":"The phrase 'independently of' marks a variable that ignores the other variable. Statistically, its values do not consult it.","whyCN":"短语 independently of 标记一个不理睬另一变量的变量。统计上，它的取值不向对方咨询。"},{"no":"06","title":"Without external control","titleCN":"不受外部控制地","definition":"in a manner free of direction by an owner or authority","definitionCN":"以不受所有者或权威指挥的方式","example":"The newspaper is independently owned.","exampleCN":"这家报纸归独立所有者所有。","why":"The adverb can modify an adjective of ownership. It says the funding line runs to no patron.","whyCN":"这个副词可以修饰表所属关系的形容词。它说明资金线不通向任何赞助人。"},{"no":"07","title":"Without party allegiance","titleCN":"无党派地","definition":"in politics, without belonging to an established party","definitionCN":"政治上不隶属于既有政党","example":"He ran independently in the local election.","exampleCN":"他在地方选举中以独立身份参选。","why":"The hanging image becomes electoral: no party machine holds the candidate up.","whyCN":"悬挂意象变成选举意象：没有党派机器托着这位候选人。"},{"no":"08","title":"With one's own income","titleCN":"经济上自立地","definition":"in a way that is paid for by oneself rather than by a subsidy","definitionCN":"以由自己支付而非依靠补贴的方式","example":"The study was independently funded.","exampleCN":"这项研究由独立资金资助。","why":"Money is the last tether. Independently funded means no sponsor could pull the line.","whyCN":"金钱是最后一根绳索。independently funded 意为没有赞助人能拉动这根线。"}],"etymology":{"intro":{"en":"Independently is independent plus -ly. The adjective negates Latin dependere, 'to hang from', so the adverb says that an action is performed with no support line attached.","cn":"independently 是 independent 加 -ly。形容词否定了拉丁语 dependere“悬挂于”，因此副词说明一个动作完成时没有系上支撑线。"},"items":[{"era":"PIE *(s)pen- (reconstructed form)","en":"The root behind pendere, 'to hang', is reconstructed and generally accepted as *(s)pen-, 'to draw or stretch'.","cn":"pendere“悬挂”背后的词根是重构形式，一般认为作 *(s)pen-“拉、伸”。"},{"era":"LATIN dependere","en":"De- 'down' plus pendere 'hang' gave dependere, 'to hang down from'. The verb described both a physical attachment and a legal dependence.","cn":"de-“向下”加 pendere“悬挂”构成 dependere“挂下来”。这个动词既描述实物附着，也描述法律上的依附。"},{"era":"17C. ENGLISH independent / independently","en":"The adjective appeared first; the adverb followed to describe action rather than state. Early examples concern religion and politics.","cn":"形容词先出现，副词随后用来描述动作而非状态。早期用例涉及宗教与政治。"},{"era":"ENGLISH -ly","en":"-Ly from Old English -lice turns an adjective into a manner adverb. In this word it answers 'with what support?'","cn":"-ly 源自古英语 -lice，把形容词变成方式副词。在这个词里，它回答“靠什么支撑？”。"},{"era":"18C.–19C. SCIENCE","en":"Independent verification and independent observation became ideals of the scientific method: a result must be repeatable without the original author's help.","cn":"独立核实与独立观察成为科学方法的理想：结果必须能在没有原作者帮助的情况下被重复。"},{"era":"20C. STATISTICS AND GOVERNANCE","en":"Independently distributed variables and independently regulated bodies carried the adverb into technical and administrative English.","cn":"独立分布的变量与独立监管的机构把这个副词带入技术与行政英语。"}]},"similar":{"note":{"en":"The look-alike group separates the adjective, the noun and the adverb. The meaning group compares adverbs of separation and self-direction.","cn":"形近组区分形容词、名词与副词；词义组比较表示分离与自主的副词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"independent","ipa":"/ˌɪndɪˈpendənt/","tag":"adjective","definition":"not relying on another. The adverb says an action is done in that condition.","definitionCN":"不依赖他人的。副词说明动作在这种状态下完成。"},{"word":"independence","ipa":"/ˌɪndɪˈpendəns/","tag":"noun","definition":"the state of being independent. It names the condition, not the manner.","definitionCN":"独立的状态。它命名条件，而非方式。"},{"word":"dependently","ipa":"/dɪˈpendəntli/","tag":"rare adverb","definition":"in a relying manner. It is the opposite adverb and is rare outside technical writing.","definitionCN":"以依赖的方式。它是反义副词，在技术写作之外罕用。"}]},{"heading":"NEAR MEANING","entries":[{"word":"separately","ipa":"/ˈseprətli/","tag":"one by one","definition":"as different units, not together. It matches sense 03 and says nothing about control.","definitionCN":"作为不同单位、不在一起。它对应第 3 义项，不涉及控制。"},{"word":"autonomously","ipa":"/ɔːˈtɒnəməsli/","tag":"self-governed","definition":"by self-rule. It is close to sense 02 and is used of regions, machines and institutions.","definitionCN":"以自治方式。它接近第 2 义项，用于地区、机器与机构。"},{"word":"alone","ipa":"/əˈləʊn/","tag":"without others","definition":"without other people present. It describes company, while independently describes reliance.","definitionCN":"没有他人在场。它描述陪伴，而 independently 描述依赖。"},{"word":"freely","ipa":"/ˈfriːli/","tag":"without restriction","definition":"without being controlled or limited. It stresses permission, not the absence of support.","definitionCN":"不受控制或限制。它强调许可，而非缺少支撑。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks build independently from in- 'not' plus dependere 'hang' plus -ly, and keep the image of two closed doors.","cn":"这些记忆钩从 in-“不”加 dependere“悬挂”再加 -ly 搭起 independently，并保留“两扇关着的门”的意象。"},"normal":[{"en":"See in- + depend + -ly: done without hanging from anyone.","cn":"看成 in- 加 depend 加 -ly：完成时不挂在任何人身上。"},{"en":"Picture two laboratories with their doors shut, each writing the same number on a board.","cn":"想象两个实验室门都关着，各自在黑板上写下同一个数字。"},{"en":"When prices move independently of demand, the two lines simply never consult each other.","cn":"当价格独立于需求变动时，两条线根本不向对方咨询。"},{"en":"A newspaper that is independently owned has no patron holding its rope.","cn":"归独立所有者所有的报纸，没有赞助人牵着它的绳子。"},{"en":"Remember the pair: independently answers 'how did it stand?'","cn":"记住这一对：independently 回答“它是怎么站住的？”"}],"abstract":[{"en":"Keep one image: two ropes that were never tied together.","cn":"只记一个意象：两根从未系在一起的绳子。"},{"en":"Treat the adverb as a statement about support, never about solitude.","cn":"把这个副词当作关于支撑的陈述，而不是关于孤独的陈述。"},{"en":"Notice that independence in research is valuable only because agreement is then not copied.","cn":"注意研究中的独立之所以有价值，正因为得出的共识不是抄来的。"}]},"examples":[{"en":"The two witnesses described the car independently.","cn":"两名目击者各自独立地描述了那辆车。"},{"en":"The findings were independently verified by a second team.","cn":"这些发现由第二个团队独立核实。"},{"en":"Interest rates moved independently of the exchange rate.","cn":"利率的变动不受汇率影响。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“阴地喷灯特立”：在阴暗处打着喷灯也特立独行，不靠别人——独立地。","word":"independently"},"root":"independent（in-“不” + 拉丁语 dependere“悬挂于、依赖”）加副词后缀 -ly；核心是“动作完成时不挂在任何支撑上”。","sensesIntro":{"en":"Independently is the manner form of a cut rope. It says an action was performed with no support from a person (S1), an authority (S2), a shared unit (S3), another research group (S4), another factor (S5), an owner (S6), a party (S7) or a funder (S8). The adverb never describes the state; it describes how the deed was done.","cn":"independently 是“剪断绳子”的方式形式。它说某个动作完成时，没有来自他人的支撑（第 1）、没有来自权威的支撑（第 2）、没有共享单位（第 3）、没有另一研究组（第 4）、没有另一因素（第 5）、没有所有者（第 6）、没有政党（第 7）、没有出资者（第 8）。这个副词从不描述状态，只描述事情是怎么办成的。"},"semanticMap":{"core":{"en":"Acting with no support line attached to another.","cn":"行动时没有支撑线系在别处。"},"chain":["HANG","SUPPORT","SEPARATE","SELF-RULE","PARALLEL","UNLINKED"],"branches":[{"senses":"S1","en":"SELF-SUFFICIENCY: no help from any person.","cn":"自立：不借助任何人的帮助。"},{"senses":"S2 · S7","en":"AUTHORITY: no ministry and no party machine above the actor.","cn":"权威：行动者之上没有部、没有党派机器。"},{"senses":"S3 · S4","en":"UNITS: cases tested one by one, teams working blind to each other.","cn":"单位：逐个测试的案例，互相看不见的团队。"},{"senses":"S5","en":"CAUSATION: one factor moving without consulting another.","cn":"因果：一个因素变动而不咨询另一因素。"},{"senses":"S6 · S8","en":"MONEY: no owner and no sponsor holding the line.","cn":"金钱：没有所有者，也没有赞助人牵线。"}]},"affixes":{"intro":{"en":"Independently is the adverb of the hanging family. The items below show the same root with negation, with state suffixes and with a rare positive adverb.","cn":"independently 是“悬挂”词族的副词。下列条目展示同一词根配否定、配状态后缀，以及那个罕用的肯定副词。"},"latinIntro":{"en":"The Latin entries repeat the small set behind the adverb: a bare verb, a prefixed verb and its participle.","cn":"拉丁语条目重复了副词背后的小集合：裸动词、加前缀动词及其分词。"},"items":[{"word":"independently","structure":"independent + -ly (manner adverb)","meaning":"without reliance or control","meaningCN":"不依赖、不受控制地","example":"The panels reviewed the case independently.","exampleCN":"各小组独立审查了此案。"},{"word":"independent","structure":"in- (negation) + dependent","meaning":"not relying on another","meaningCN":"不依赖他人的","example":"An independent review was ordered.","exampleCN":"已下令进行独立审查。"},{"word":"independence","structure":"independent + -ence","meaning":"freedom from control","meaningCN":"不受控制的状态","example":"The court guards its independence.","exampleCN":"法院守护自身的独立性。"},{"word":"dependent","structure":"Latin dependens","meaning":"relying on another","meaningCN":"依赖他人的","example":"The program is dependent on donations.","exampleCN":"该项目依赖捐款。"},{"word":"depend","structure":"Latin dependere","meaning":"to rely on; to be determined by","meaningCN":"依赖；由……决定","example":"Much depends on the next vote.","exampleCN":"许多事取决于下一次投票。"},{"word":"dependence","structure":"depend + -ence","meaning":"reliance","meaningCN":"依赖","example":"Dependence on one supplier is dangerous.","exampleCN":"依赖单一供应商很危险。"},{"word":"interdependently","structure":"interdependent + -ly","meaning":"in a mutually reliant way","meaningCN":"以相互依赖的方式","example":"The systems operate interdependently.","exampleCN":"这些系统相互依存地运作。"},{"word":"pendulous","structure":"Latin pendulus + -ous","meaning":"hanging, swinging","meaningCN":"下垂的；摆动的","example":"The pendulous branches touched the water.","exampleCN":"下垂的枝条触到了水面。"}],"latinEntries":[{"word":"pendere","structure":"3rd conjugation verb","meaning":"to hang","meaningCN":"悬挂"},{"word":"dependere","structure":"de- + pendere","meaning":"to hang down from","meaningCN":"悬挂于"},{"word":"dependens","structure":"present participle","meaning":"hanging from; dependent","meaningCN":"悬挂于的；依赖的"}]}},{"word":"indication","ipa_uk":"/ˌɪndɪˈkeɪʃn/","ipa_us":"/ˌɪndɪˈkeɪʃn/","definition_zh":"迹象；表明；指示；（医学）体征、适应证；读数","definition_en":"a sign that shows something is true or likely, or the act of pointing something out","core_image":"一根手指指向远处，所有人顺着它看过去","scene":"There was no indication that the storm would turn inland until the barometer fell.","sceneCN":"这里 indication 是「迹象」（第 1 个义项：显示某事可能属实的信号）；句意：在气压计下降之前，没有任何迹象表明风暴会转向内陆。图中可辨识物件：气压计指针、窗外压低的云层、指向地图的手指。","pos":[{"tag":"n.","zh":"迹象；表明；指示；体征；适应证"}],"collocations":[{"phrase":"an indication of","zh":"……的迹象"},{"phrase":"there is every indication that","zh":"种种迹象表明"},{"phrase":"clinical indication","zh":"临床指征"},{"phrase":"clear indication","zh":"明确的迹象"},{"phrase":"indication for treatment","zh":"治疗适应证"},{"phrase":"without any indication","zh":"毫无迹象地"}],"forms":[{"label":"单数","form":"indication"},{"label":"复数","form":"indications"},{"label":"动词","form":"indicate"}],"derivatives":[{"word":"indicate","pos":"v.","zh":"表明；指示；暗示"},{"word":"indicator","pos":"n.","zh":"指标；指示器"},{"word":"indicative","pos":"adj.","zh":"表明的；指示性的"},{"word":"index","pos":"n.","zh":"索引；指数"}],"senses":[{"no":"01","title":"A sign that something is so","titleCN":"表明某事的迹象","definition":"a piece of evidence that suggests a fact or a likely development","definitionCN":"暗示某事实或可能发展的证据","example":"There is no indication that the trend will reverse.","exampleCN":"没有迹象表明这一趋势会逆转。","why":"Indicare means 'to point out'. An indication is a finger pointed at a fact, and the viewer must still read what it points to.","whyCN":"indicare 意为“指出”。indication 就是指向事实的一根手指，而观看者仍须读懂它指向什么。"},{"no":"02","title":"The act of pointing something out","titleCN":"指出、表明的行为","definition":"the act of stating or showing that something is the case","definitionCN":"陈述或显示某事如此的行为","example":"His indication of the exit saved us time.","exampleCN":"他指出出口，替我们省了时间。","why":"The suffix -ation makes this the act itself, not the sign. Someone performs the pointing.","whyCN":"后缀 -ation 使这个词指行为本身，而非标志。是某人在做指向动作。"},{"no":"03","title":"A medical sign","titleCN":"医学上的体征","definition":"in medicine, an observable sign that points to a condition","definitionCN":"医学中指向某种病情的可观察体征","example":"Fever is one indication of infection.","exampleCN":"发热是感染的一种体征。","why":"A clinical sign is a finger aimed at a hidden cause. The cause remains invisible; only the pointing is visible.","whyCN":"临床体征是一根指向隐藏病因的手指。病因仍然不可见，可见的只有这次指向。"},{"no":"04","title":"A reading on an instrument","titleCN":"仪表上的读数","definition":"a value shown by a gauge or meter","definitionCN":"计量仪表显示的数值","example":"The dial gave no indication of pressure.","exampleCN":"表盘没有显示压力读数。","why":"The needle is a literal finger on a scale. The instrument indicates, and the reading is the indication.","whyCN":"指针就是落在刻度上的一根真实手指。仪表在指示，读数就是这次指示。"},{"no":"05","title":"A signal or gesture","titleCN":"示意信号或手势","definition":"a gesture or signal intended to convey a message","definitionCN":"意在传达讯息的手势或信号","example":"A nod was his indication that we should begin.","exampleCN":"一个点头就是他示意我们开始的信号。","why":"Here the pointing is bodily and immediate. Nothing is written; the message is delivered by a movement.","whyCN":"这里的指向是身体性的、即时的。没有文字，讯息由一个动作递出。"},{"no":"06","title":"A hint in speech or manner","titleCN":"言谈中的暗示","definition":"a subtle hint given in conversation rather than a direct statement","definitionCN":"交谈中给出的细微暗示，而非直接陈述","example":"He gave a slight indication that he was unhappy.","exampleCN":"他给了个细微暗示，表示自己不高兴。","why":"The finger is only half raised. The word marks a signal deliberately kept below the level of a statement.","whyCN":"手指只抬起一半。这个词标记的是一个被刻意压在陈述线以下的信号。"},{"no":"07","title":"Evidence pointing to a conclusion","titleCN":"指向结论的证据","definition":"in the phrase 'there is every indication', evidence strong enough to support an expectation","definitionCN":"在“种种迹象表明”这一说法中，强到足以支持某种预期的证据","example":"There is every indication that the talks will succeed.","exampleCN":"种种迹象表明会谈将会成功。","why":"The phrase weighs a set of fingers all pointing the same way. Indication becomes the collective direction of evidence.","whyCN":"这个说法称量一组都指向同一方向的手指。indication 成了证据的集体方向。"},{"no":"08","title":"A reason to use a treatment","titleCN":"治疗的适应证","definition":"in medicine, a condition that makes a particular treatment appropriate","definitionCN":"医学中使某种治疗变得合适的病情","example":"The scan gave a clear indication for surgery.","exampleCN":"扫描结果给出了明确的手术适应证。","why":"Here the pointing goes the other way: the condition points at the treatment, licensing the doctor to act.","whyCN":"这里的指向反了过来：病情指向治疗，从而授权医生行动。"}],"etymology":{"intro":{"en":"Indication comes from Latin indicare, 'to point out'. It is built from in- plus dicare, 'to proclaim', and is related to index, the pointing finger. Every sense keeps that gesture: something is aimed at, and the viewer must read the aim.","cn":"indication 来自拉丁语 indicare“指出”。它由 in- 加 dicare“宣告”构成，与 index（食指、索引）同族。每个义项都保留那个手势：某物被指向，而观看者必须读懂指向。"},"items":[{"era":"LATIN dicare (source uncertain)","en":"Dicare meant 'to proclaim, to dedicate'. Its relation to dicere 'to say' is generally accepted, but the exact prehistoric division between the two verbs is uncertain.","cn":"dicare 意为“宣告、奉献”。它与 dicere“说”的关系一般被接受，但两个动词在史前期的具体分化来源不确定。"},{"era":"LATIN index / indicis","en":"Index meant 'a pointer, a sign, the forefinger'. The plural indices kept the same stem that produced indicate. This is why an index and an indication both point.","cn":"index 意为“指示者、标志、食指”。复数 indices 保留的词干正产生了 indicate。索引与迹象都指方向，原因就在这里。"},{"era":"LATIN indicare","en":"In- plus dicare gave indicare, 'to point out, to show, to give a sign'. The verb was used of fingers, of evidence and of prices.","cn":"in- 加 dicare 构成 indicare“指出、显示、给出信号”。这个动词既用于手指，也用于证据与价格。"},{"era":"LATIN indicatio","en":"The noun indicatio named the act of pointing out. Latin medical writers already used it for symptoms that point to a disease.","cn":"名词 indicatio 指指出某物的行为。拉丁医学作者已用它指指向疾病的症状。"},{"era":"16C. FRENCH / ENGLISH","en":"English borrowed indication through French. Early uses concerned both 'a hint' and 'a symptom', and the medical sense has never left.","cn":"英语经法语借入 indication。早期用法兼指“暗示”与“症状”，医学义从未离开这个单词。"},{"era":"19C.–20C. MEDICINE AND INSTRUMENTS","en":"Clinical indication, indication for surgery and instrument indications fixed the word in medicine and engineering, where a sign licenses an action.","cn":"临床指征、手术适应证与仪表读数使这个词固定于医学与工程，在这些领域里，一个信号就是行动的依据。"}]},"similar":{"note":{"en":"The look-alike group separates the verb, this noun and the instrument noun. The meaning group compares words for signs and evidence.","cn":"形近组区分动词、本名词与仪器名词；词义组比较表示迹象与证据的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"indicate","ipa":"/ˈɪndɪkeɪt/","tag":"verb","definition":"to point out or show. It is the action behind the noun.","definitionCN":"指出或显示。它是名词背后的动作。"},{"word":"indicator","ipa":"/ˈɪndɪkeɪtə/","tag":"noun of instrument","definition":"a gauge or a measurable sign. It is the thing that points, while indication is the pointing or the pointed-at fact.","definitionCN":"仪表或可测量的标志。它是做指向的东西，而 indication 是指向动作或被指的事实。"},{"word":"index","ipa":"/ˈɪndeks/","tag":"noun","definition":"an alphabetical list, a number expressing change, or the forefinger. It shares the pointing stem.","definitionCN":"按字母排列的清单、表示变化的数字，或食指。它共享“指向”的词干。"}]},{"heading":"NEAR MEANING","entries":[{"word":"sign","ipa":"/saɪn/","tag":"general marker","definition":"anything that suggests the presence of something. It is the broad everyday word; indication is more formal.","definitionCN":"暗示某物存在的任何东西。它是宽泛的日常词，indication 更正式。"},{"word":"symptom","ipa":"/ˈsɪmptəm/","tag":"medical sign","definition":"a change in the body that points to a disease. It matches sense 03 specifically.","definitionCN":"身体上指向疾病的变化。它专门对应第 3 义项。"},{"word":"evidence","ipa":"/ˈevɪdəns/","tag":"proof material","definition":"facts offered to support a claim. It is stronger than indication and carries the weight of proof.","definitionCN":"为支持某主张而提供的事实。它比 indication 更强，带有证明的分量。"},{"word":"hint","ipa":"/hɪnt/","tag":"slight signal","definition":"an indirect suggestion. It is close to sense 06 and is always deliberately understated.","definitionCN":"间接的提示。它接近第 6 义项，且总是刻意压低力度。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks build indication from in- plus dicare, 'to proclaim', and keep the pointing finger and the index card in view.","cn":"这些记忆钩从 in- 加 dicare“宣告”搭起 indication，并让指向的手指与索引卡始终在眼前。"},"normal":[{"en":"See in- + dicare: to proclaim towards something. An indication is a proclamation aimed at a fact.","cn":"看成 in- 加 dicare：朝某物宣告。indication 就是指向某个事实的宣告。"},{"en":"Picture a finger pointing at a distant hill: the hill is the fact, the finger is the indication.","cn":"想象一根手指指向远处的山：山是事实，手指是迹象。"},{"en":"An index is a book's pointing finger; an indication is evidence's pointing finger.","cn":"索引是书的指向手指；迹象是证据的指向手指。"},{"en":"In medicine, a symptom points at a cause the doctor cannot yet see.","cn":"在医学里，症状指向医生尚看不见的病因。"},{"en":"When there is every indication, many fingers point the same way.","cn":"当“种种迹象表明”时，是许多手指都指向同一方向。"}],"abstract":[{"en":"Keep one gesture: aim, and let another read the aim.","cn":"只记一个手势：指过去，让别人读懂所指。"},{"en":"Treat the word as weaker than proof and stronger than a guess.","cn":"把这个词当作比证据弱、比猜测强的东西。"},{"en":"Notice that the same word covers a raised finger and a falling barometer: both are pointers.","cn":"注意同一个词既覆盖抬起的手指，也覆盖下降的气压计：两者都是指向器。"}]},"examples":[{"en":"The survey gives a useful indication of public mood.","cn":"这项调查为了解公众情绪提供了有用的迹象。"},{"en":"There is every indication that the policy is working.","cn":"种种迹象表明这项政策正在奏效。"},{"en":"The doctor found no indication for further surgery.","cn":"医生认为没有进一步手术的适应证。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“印地开神”：印度街头的开示神像用手一指，众人顺着看过去——这就是指示、迹象。","word":"indication"},"root":"拉丁语 indicare“指出、显示”（in- 朝向 + dicare 宣告），名词 indicatio；与 index“食指、索引”同出“指向”词干。","sensesIntro":{"en":"Every sense of indication is a pointing. Sometimes the finger is a symptom, sometimes a needle, sometimes a nod, sometimes a half-raised hint, sometimes a whole body of evidence, and sometimes a condition that points at a treatment. The word never contains the conclusion; it contains the direction in which to look.","cn":"indication 的每个义项都是一次指向。有时手指是症状，有时是仪表指针，有时是一个点头，有时是抬到一半的暗示，有时是整组证据，有时是病情指向某种治疗。这个词从不包含结论，它包含的是该往哪里看。"},"semanticMap":{"core":{"en":"A pointing that tells another where to look.","cn":"一次指向，告诉别人该往哪里看。"},"chain":["POINT","SIGN","SHOW","SUGGEST","EVIDENCE","LICENSE"],"branches":[{"senses":"S1 · S7","en":"EVIDENCE: signs and the collective weight of signs.","cn":"证据：迹象与迹象的集体分量。"},{"senses":"S2 · S5","en":"GESTURE: the act of pointing and a signal given by hand.","cn":"手势：指向动作与用手给出的信号。"},{"senses":"S6","en":"HINT: a sign deliberately kept below the level of a statement.","cn":"暗示：被刻意压在陈述线以下的信号。"},{"senses":"S3 · S8","en":"MEDICINE: a symptom pointing to a cause, a condition licensing treatment.","cn":"医学：指向病因的症状，以及授权治疗的病情。"},{"senses":"S4","en":"INSTRUMENT: a needle's reading.","cn":"仪表：指针的读数。"}]},"affixes":{"intro":{"en":"Indication is indicare plus -atio. The items below gather the pointing family, including index, which looks different but shares the same stem.","cn":"indication 是 indicare 加 -atio。下列条目汇总“指向”词族，包括形似不同却共享同一词干的 index。"},"latinIntro":{"en":"The Latin entries give the pointing verb and the pointer noun. They explain why an index and an indication belong to one family.","cn":"拉丁语条目给出指向动词与指示者名词。它们解释了为什么索引与迹象属于同一家族。"},"items":[{"word":"indication","structure":"indicare + -atio (process noun)","meaning":"a sign; the act of pointing out","meaningCN":"迹象；指出的行为","example":"The indication was easy to miss.","exampleCN":"这个迹象很容易被忽略。"},{"word":"indicate","structure":"Latin indicare, 'to point out'","meaning":"to show or suggest","meaningCN":"表明或暗示","example":"The figures indicate a slow recovery.","exampleCN":"这些数字表明复苏缓慢。"},{"word":"indicator","structure":"indicate + -or (instrument noun)","meaning":"a gauge or measurable sign","meaningCN":"仪表或可测量的标志","example":"The indicator moved into the red zone.","exampleCN":"指示器进入了红色区域。"},{"word":"indicative","structure":"indicare + -ive (adjective)","meaning":"serving as a sign of","meaningCN":"表明……的","example":"The tone is indicative of trouble.","exampleCN":"这种语气表明有麻烦。"},{"word":"index","structure":"Latin index, 'pointer, forefinger'","meaning":"a list or a number that points to change","meaningCN":"指向变化的清单或数字","example":"The price index rose sharply.","exampleCN":"价格指数大幅上升。"},{"word":"indices","structure":"plural of index, from Latin indices","meaning":"more than one index","meaningCN":"多个索引或指数","example":"Both indices point to slower growth.","exampleCN":"两个指数都指向增长放缓。"},{"word":"indexical","structure":"index + -ical","meaning":"pointing to context, as a word like 'here'","meaningCN":"指向语境的，如“这里”这类词","example":"Pronouns are indexical expressions.","exampleCN":"代词是指示性表达。"},{"word":"indicatively","structure":"indicative + -ly","meaning":"in a way that serves as a sign","meaningCN":"以起标志作用的方式","example":"The sample was indicatively small.","exampleCN":"这个样本小得只能算个示意。"}],"latinEntries":[{"word":"index","structure":"noun, indic- stem","meaning":"pointer; forefinger; sign","meaningCN":"指示者；食指；标志"},{"word":"indicare","structure":"in- + dicare","meaning":"to point out; to show","meaningCN":"指出；显示"},{"word":"dicare","structure":"1st conjugation verb","meaning":"to proclaim; to dedicate","meaningCN":"宣告；奉献"}]}},{"word":"indicator","ipa_uk":"/ˈɪndɪkeɪtə/","ipa_us":"/ˈɪndɪkeɪtər/","definition_zh":"指标；指示器；指示剂；指示物；转向灯","definition_en":"something that shows a condition or points to a result, such as a gauge, a statistical measure or a warning light","core_image":"仪表盘上一根指针，把看不见的状态翻成看得见的刻度","scene":"The unemployment rate is the most closely watched indicator of the economy's health.","sceneCN":"这里 indicator 是「经济指标」（第 1、5 个义项：用来显示整体状况的可测量量）；句意：失业率是衡量经济健康最受关注的指标。图中可辨识物件：仪表盘、上升与下降的两条曲线、报摊上的报纸标题。","pos":[{"tag":"n.","zh":"指标；指示器；指示剂；指示物；转向灯"}],"collocations":[{"phrase":"economic indicator","zh":"经济指标"},{"phrase":"key indicator","zh":"关键指标"},{"phrase":"pH indicator","zh":"酸碱指示剂"},{"phrase":"indicator species","zh":"指示物种"},{"phrase":"turn indicator","zh":"转向灯"},{"phrase":"health indicator","zh":"健康指标"}],"forms":[{"label":"单数","form":"indicator"},{"label":"复数","form":"indicators"},{"label":"动词","form":"indicate"}],"derivatives":[{"word":"indicate","pos":"v.","zh":"表明；指示"},{"word":"indication","pos":"n.","zh":"迹象；表明"},{"word":"indicative","pos":"adj.","zh":"表明的"},{"word":"index","pos":"n.","zh":"索引；指数"}],"senses":[{"no":"01","title":"A measurable sign of a condition","titleCN":"衡量状况的指标","definition":"a statistic used to show the state or direction of a system","definitionCN":"用来显示某系统状态或走向的统计量","example":"Inflation is a key indicator of economic stress.","exampleCN":"通货膨胀是经济压力的关键指标。","why":"The suffix -or names the thing that does the pointing. An indicator is the finger itself, not the fact it aims at.","whyCN":"后缀 -or 命名做指向动作的事物。indicator 是手指本身，而不是它所指向的事实。"},{"no":"02","title":"A gauge or dial","titleCN":"仪表盘上的指示器","definition":"a device that shows a reading such as pressure, speed or temperature","definitionCN":"显示压力、速度或温度等读数的装置","example":"The temperature indicator warned of overheating.","exampleCN":"温度指示器发出了过热警告。","why":"Here the pointing is mechanical. The needle converts an invisible quantity into a visible position on a scale.","whyCN":"这里的指向是机械的。指针把不可见的量换算成刻度上的可见位置。"},{"no":"03","title":"A chemical that changes colour","titleCN":"化学指示剂","definition":"in chemistry, a substance that changes colour to show a property such as acidity","definitionCN":"化学中通过变色显示酸碱性等性质的物质","example":"Litmus is a classic pH indicator.","exampleCN":"石蕊是一种经典的酸碱指示剂。","why":"The colour change is the pointing. The molecule raises a finger the moment a threshold is crossed.","whyCN":"颜色变化就是那次指向。阈值一旦被越过，分子立刻举起一根手指。"},{"no":"04","title":"A species that reveals ecosystem health","titleCN":"生态指示物种","definition":"in ecology, an organism whose condition reveals the health of its habitat","definitionCN":"生态学中其状况能揭示栖息地健康的生物","example":"Lichens are useful indicators of air quality.","exampleCN":"地衣是空气质量的实用指示物。","why":"A sensitive organism cannot help pointing. If it thrives, the habitat is well; if it dies, something is wrong.","whyCN":"敏感的生物不由自主地指向。它繁盛，说明栖息地良好；它死亡，说明出了问题。"},{"no":"05","title":"An economic figure to watch","titleCN":"经济指标","definition":"in economics, a published figure used to judge the direction of the economy","definitionCN":"经济学中用来判断经济走向的公布数字","example":"Housing starts are a leading indicator of recovery.","exampleCN":"新屋开工是复苏的先行指标。","why":"The metaphor becomes statistical: one number is chosen to stand for millions of unseen decisions.","whyCN":"比喻变成统计性的：一个数字被选中，代表数百万个看不见的决策。"},{"no":"06","title":"A person who points something out","titleCN":"指出某事的人","definition":"a person who indicates or draws attention to something","definitionCN":"指出某事或引起注意的人","example":"He was the first indicator of the flaw in the plan.","exampleCN":"他是最先指出计划缺陷的人。","why":"The rare human sense restores the literal finger: the indicator is a person doing the pointing.","whyCN":"罕用的人称义恢复了字面手指：指示者就是一个在做指向动作的人。"},{"no":"07","title":"A car's flashing light","titleCN":"汽车转向灯","definition":"in British usage, the flashing light on a vehicle that shows the direction of a turn","definitionCN":"英式用法中指车辆上显示转向方向的闪灯","example":"He forgot to use the indicator before turning.","exampleCN":"他转弯前忘了打转向灯。","why":"The lamp points for the driver, announcing an intention before the vehicle moves. It is pointing made public.","whyCN":"灯替驾驶员指出方向，在车辆移动之前宣布意图。这是公开化的指向。"},{"no":"08","title":"A warning sign of risk","titleCN":"风险的警示信号","definition":"an early sign that something may go wrong","definitionCN":"某事可能出问题的早期信号","example":"A rise in complaints is an indicator of deeper trouble.","exampleCN":"投诉上升是更深层问题的警示信号。","why":"The finger now points at the future. The sign is valuable because it appears before the damage.","whyCN":"手指现在指向未来。信号之所以有价值，是因为它在损害出现之前就到了。"}],"etymology":{"intro":{"en":"Indicator is indicare plus -or, the suffix for the doer. It descends from Latin index, the pointer or forefinger, so the word is literally 'the one that points'. English first used it for people, then for gauges and figures.","cn":"indicator 是 indicare 加 -or，后者是表示施动者的后缀。它源自拉丁语 index“指示者、食指”，因此字面上就是“做指向的东西”。英语先把它用于人，后用于仪表与数字。"},"items":[{"era":"LATIN dicare (source uncertain)","en":"Dicare, 'to proclaim', shares a stem with dicere, 'to say'. The split between the two verbs is generally accepted but its exact prehistory is uncertain.","cn":"dicare“宣告”与 dicere“说”共享词干。两个动词的分化一般被接受，但确切史前过程不确定。"},{"era":"LATIN index","en":"Index meant 'one who points out, a sign, the forefinger'. It also named the list in a book, because a list points to pages.","cn":"index 意为“指出者、标志、食指”。它也指书中的目录，因为目录指向页码。"},{"era":"LATIN indicare","en":"Indicare meant 'to point out, to show'. Its agent noun indicator would have meant 'one who points out'; English built the noun fresh on the Latin stem.","cn":"indicare 意为“指出、显示”。其施动名词 indicator 本应意为“指出者”；英语是在拉丁词干上重新造出这个名词。"},{"era":"LATIN -or","en":"The suffix -or forms agent nouns such as doctor and rector. Attached to indicare it gives 'the pointer', the thing or person that does the pointing.","cn":"后缀 -or 构成 doctor、rector 等施动名词。加在 indicare 上就得到“指向者”，即做指向的事物或人。"},{"era":"17C.–18C. ENGLISH","en":"Early English indicators were people, especially informers or signallers. The instrument sense arrived with the growth of scientific instruments.","cn":"早期英语中的 indicator 指人，尤指告发者或信号员。仪器义随着科学仪器的增长而来。"},{"era":"19C.–20C. SCIENCE, INDUSTRY AND ECONOMICS","en":"Chemical indicators, engine gauges, ecological indicator species and economic leading indicators each put a different object in the pointing role.","cn":"化学指示剂、发动机仪表、生态指示物种与经济先行指标，各自把不同物件放在“指向者”的位置上。"}]},"similar":{"note":{"en":"The look-alike group separates the verb, the process noun and this agent noun. The meaning group compares words for measures and signals.","cn":"形近组区分动词、过程名词与这个施动名词；词义组比较表示测量与信号的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"indicate","ipa":"/ˈɪndɪkeɪt/","tag":"verb","definition":"to point out or show. The indicator is the thing that performs this act.","definitionCN":"指出或显示。indicator 是执行这一动作的事物。"},{"word":"indication","ipa":"/ˌɪndɪˈkeɪʃn/","tag":"noun","definition":"a sign or the act of showing. It is the pointing, while indicator is the pointer.","definitionCN":"迹象或显示的行为。它是指向，而 indicator 是指向者。"},{"word":"index","ipa":"/ˈɪndeks/","tag":"noun","definition":"a list, a comparative number or the forefinger. It is the older Latin name for the same pointer.","definitionCN":"清单、比较数字或食指。它是同一指向者的更早拉丁名称。"}]},{"heading":"NEAR MEANING","entries":[{"word":"measure","ipa":"/ˈmeʒə/","tag":"quantity used to judge","definition":"a quantity used to judge or compare. It is close to sense 01 but names the size, not the pointing function.","definitionCN":"用于判断或比较的数量。它接近第 1 义项，但命名的是大小，而非指向功能。"},{"word":"gauge","ipa":"/ɡeɪdʒ/","tag":"instrument","definition":"a device for measuring. It is the physical object behind sense 02.","definitionCN":"测量用的装置。它是第 2 义项背后的实物。"},{"word":"sign","ipa":"/saɪn/","tag":"general marker","definition":"anything that suggests something else. It is broader than indicator and does not imply a designed measuring role.","definitionCN":"暗示另一事物的任何东西。它比 indicator 更宽，不含被设计来测量的角色。"},{"word":"signal","ipa":"/ˈsɪɡnəl/","tag":"transmitted message","definition":"a gesture, sound or light that carries information. It matches sense 07 and stresses communication rather than measurement.","definitionCN":"承载信息的手势、声音或光。它对应第 7 义项，强调传达而非测量。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks build indicator from indicare plus -or and keep the image of a needle that turns an unseen quantity into a visible mark.","cn":"这些记忆钩从 indicare 加 -or 搭起 indicator，并保留“指针把看不见的量变成看得见的刻度”的意象。"},"normal":[{"en":"See -or: the one that points. An indicator does the pointing; an indication is what is pointed at.","cn":"看见 -or：做指向的那一个。indicator 负责指，indication 是被指出的东西。"},{"en":"Picture a dashboard needle: the engine's health becomes a position on a dial.","cn":"想象仪表盘指针：发动机的健康变成一个表盘位置。"},{"en":"In chemistry, the colour change is the needle.","cn":"在化学里，颜色变化就是那根指针。"},{"en":"A lichen is a living gauge for the air around it.","cn":"地衣就是它周围空气的活仪表。"},{"en":"Remember the chain: indicator points, indication appears, indicate is the act.","cn":"记住这条链：indicator 指，indication 显现，indicate 是动作。"}],"abstract":[{"en":"Keep one image: a small visible thing standing in for a large invisible one.","cn":"只记一个意象：一个小的可见之物，代表一个大的不可见之物。"},{"en":"Treat the word as a promise that the reading is connected to the reality it stands for.","cn":"把这个词当作一个承诺：读数与它所代表的事实是相连的。"},{"en":"Notice that an indicator can be wrong; that is why economists argue about which one to trust.","cn":"注意指标可能出错；正因如此，经济学家才争论该信哪一个。"}]},"examples":[{"en":"The report uses three indicators to rank the schools.","cn":"这份报告用三项指标给学校排名。"},{"en":"The indicator on the dashboard began to flash.","cn":"仪表盘上的指示器开始闪动。"},{"en":"Moss is a reliable indicator of damp conditions.","cn":"苔藓是潮湿环境的可靠指示物。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“印地开特”：在印度地图上开一个特别记号，一指就明白——指标、指示器。","word":"indicator"},"root":"拉丁语 indicare“指出”（in- 朝向 + dicare 宣告）加施动后缀 -or；与 index“食指、索引”同源，字面义为“做指向的东西”。","sensesIntro":{"en":"An indicator is the pointer, not the truth. It can be a statistic, a needle, a dye, a lichen, a leading economic figure, a person, a car lamp or an early warning. The eight senses differ in material and in what is being pointed at, but each one converts something hard to see into something that can be read.","cn":"indicator 是指向者，而不是真相。它可以是统计数字、指针、染料、地衣、经济先行数据、一个人、一盏车灯或一次预警。八个义项的差别在材质与所指对象，但每一个都把难以看见的东西变成可读的东西。"},"semanticMap":{"core":{"en":"A pointer that makes an unseen condition readable.","cn":"使看不见的状况变得可读的指向者。"},"chain":["POINT","READ","MEASURE","WARN","REPRESENT","TRACK"],"branches":[{"senses":"S1 · S5","en":"NUMBERS: statistics that stand for a whole system.","cn":"数字：代表整个系统的统计量。"},{"senses":"S2 · S7","en":"DEVICES: needles and lamps that show a state or an intention.","cn":"装置：显示状态或意图的指针与灯。"},{"senses":"S3 · S4","en":"NATURE: dyes and organisms that react before we can measure.","cn":"自然：在我们能测量之前就反应的染料与生物。"},{"senses":"S6","en":"PERSON: someone who points a problem out.","cn":"人：指出问题的人。"},{"senses":"S8","en":"WARNING: a sign that arrives before the damage.","cn":"警示：在损害之前到达的信号。"}]},"affixes":{"intro":{"en":"Indicator is indicare plus -or. The items below show the agent suffix at work and the pointing family around it.","cn":"indicator 是 indicare 加 -or。下列条目展示施动后缀的作用，以及它周围的“指向”词族。"},"latinIntro":{"en":"The Latin entries give the pointing noun, the verb and the verb's root. They explain why a forefinger, an index and an indicator are one family.","cn":"拉丁语条目给出指向名词、动词及其词根。它们解释了为什么食指、索引与指标是一个家族。"},"items":[{"word":"indicator","structure":"indicate + -or (agent noun)","meaning":"a thing or person that points out","meaningCN":"指出某物的东西或人","example":"The indicator fell below zero.","exampleCN":"该指标跌到零以下。"},{"word":"indicate","structure":"Latin indicare","meaning":"to show or suggest","meaningCN":"表明或暗示","example":"The map indicates where the river once ran.","exampleCN":"地图标示出这条河曾经的走向。"},{"word":"indication","structure":"indicate + -ation","meaning":"a sign; a showing","meaningCN":"迹象；显示","example":"There is little indication of change.","exampleCN":"几乎没有变化的迹象。"},{"word":"indicative","structure":"indicate + -ive","meaning":"serving as a sign","meaningCN":"起标志作用的","example":"The vote is indicative of public anger.","exampleCN":"这次投票显示了公众的愤怒。"},{"word":"index","structure":"Latin index, 'pointer'","meaning":"a list or a comparative number","meaningCN":"清单或比较数字","example":"The index tracks housing costs.","exampleCN":"该指数追踪住房成本。"},{"word":"indices","structure":"Latin plural of index","meaning":"several indexes","meaningCN":"多个索引或指数","example":"Two indices showed the same trend.","exampleCN":"两个指数显示出同一趋势。"},{"word":"indicator-plant","structure":"indicator + plant (compound)","meaning":"a plant that reveals soil conditions","meaningCN":"揭示土壤条件的植物","example":"The indicator-plant thrived on copper-rich soil.","exampleCN":"这种指示植物在富铜土壤上长得很好。"},{"word":"indicatively","structure":"indicative + -ly","meaning":"as a sign rather than as proof","meaningCN":"作为标志而非证明地","example":"The figures are indicatively useful.","exampleCN":"这些数字具有提示性的用处。"}],"latinEntries":[{"word":"index","structure":"noun, indic- stem","meaning":"pointer; forefinger","meaningCN":"指示者；食指"},{"word":"indicare","structure":"in- + dicare","meaning":"to point out","meaningCN":"指出"},{"word":"-or","structure":"agent-noun suffix","meaning":"one who does","meaningCN":"做某事者"}]}},{"word":"indigenous","ipa_uk":"/ɪnˈdɪdʒənəs/","ipa_us":"/ɪnˈdɪdʒənəs/","definition_zh":"土生土长的；原住民的；本地原产的；当地固有的","definition_en":"originating naturally in a particular place, or belonging to the original people of a region","core_image":"一棵树从本地的土里长出来，根就在这里，不在别处","scene":"The reserve protects plants indigenous to the valley, several of which grow nowhere else.","sceneCN":"这里 indigenous 是「本地原产的」（第 2 个义项：某物种自然生长于某地）；句意：保护区保护本山谷原产的植物，其中几种在其他地方完全不生长。图中可辨识物件：山谷轮廓、贴地生长的灌木、标出边界的围栏。","pos":[{"tag":"adj.","zh":"土生土长的；原住民的；本地原产的"}],"collocations":[{"phrase":"indigenous peoples","zh":"原住民族"},{"phrase":"indigenous species","zh":"本地原生种"},{"phrase":"indigenous to","zh":"原产于……的"},{"phrase":"indigenous culture","zh":"本土文化"},{"phrase":"indigenous language","zh":"本地语言"},{"phrase":"indigenous knowledge","zh":"本土知识"}],"forms":[{"label":"原级","form":"indigenous"},{"label":"比较级（罕用）","form":"more indigenous"},{"label":"名词","form":"indigene"},{"label":"名词（抽象）","form":"indigeneity"}],"derivatives":[{"word":"indigene","pos":"n.","zh":"本地人；原住民"},{"word":"indigeneity","pos":"n.","zh":"原住性；本土性"},{"word":"indigenize","pos":"v.","zh":"使本土化"},{"word":"indigenization","pos":"n.","zh":"本土化"}],"senses":[{"no":"01","title":"Belonging to the original people","titleCN":"原住民的","definition":"relating to the people who first lived in a region","definitionCN":"与最早居住于某地区的人群相关的","example":"The law recognizes indigenous land rights.","exampleCN":"这项法律承认原住民的土地权利。","why":"Indigena meant 'born in the place'. The adjective marks people whose origin is in the ground under them, not across a sea.","whyCN":"indigena 意为“生在此地”。这个形容词标记的是根在脚下土地而非海外的人。"},{"no":"02","title":"Native to a region's wildlife","titleCN":"本地原产的（动植物）","definition":"in biology, describing a species that evolved naturally in a given area","definitionCN":"生物学中描述在某地区自然演化的物种","example":"The garden grows only indigenous shrubs.","exampleCN":"这座花园只种本地原生灌木。","why":"A species is indigenous when its line began here. The word is about origin, not about being common.","whyCN":"一个物种若其谱系始于此地，就是本地原产的。这个词讲的是来源，而不是常见与否。"},{"no":"03","title":"Rooted in local culture","titleCN":"本地固有的文化","definition":"describing customs or institutions that developed locally rather than being imported","definitionCN":"描述在当地发展而非输入的风俗或制度","example":"The festival is indigenous to the island.","exampleCN":"这个节庆是该岛固有的。","why":"Culture is treated like a plant: it grew in this soil, and its roots show it.","whyCN":"文化被当作植物看待：它在这片土壤里长成，根就证明了这一点。"},{"no":"04","title":"Growing from within, not imposed","titleCN":"内生的（发展）","definition":"in development studies, arising from local resources and initiative","definitionCN":"发展研究中由本地资源与主动性产生的","example":"They argued for indigenous development rather than imported models.","exampleCN":"他们主张内生发展，而不是照搬外来模式。","why":"Here the metaphor is political: what is indigenous grew up here and does not need a scaffold brought from abroad.","whyCN":"这里的比喻是政治性的：内生的东西在这里长成，不需要从国外运来脚手架。"},{"no":"05","title":"A language of the place","titleCN":"本地语言的","definition":"describing a language spoken by a region's original inhabitants","definitionCN":"描述由某地区原初居民使用的语言","example":"The school teaches two indigenous languages.","exampleCN":"这所学校教授两种本地语言。","why":"A language is the deepest root a community has. The word says its grammar was formed here.","whyCN":"语言是一个共同体最深的根。这个词说它的语法是在此地形成的。"},{"no":"06","title":"Naturally present in the ground","titleCN":"天然存在于本地的","definition":"describing minerals or materials found naturally in a place rather than brought in","definitionCN":"描述在当地天然存在而非输入的材料或矿物","example":"The pigment is made from indigenous clay.","exampleCN":"这种颜料由本地黏土制成。","why":"The oldest sense is geological: the material was formed under this ground and has never travelled.","whyCN":"最古老的义项是地质性的：材料在这片土地下形成，从未旅行过。"},{"no":"07","title":"Born and raised in the place","titleCN":"土生土长的（人）","definition":"describing a person born and raised in a particular region","definitionCN":"描述在某地区出生并长大的人","example":"He is indigenous to the highlands.","exampleCN":"他是高地土生土长的人。","why":"This is the literal core: a person born in the place. It is neutral about politics and simply states origin.","whyCN":"这是字面核心：生在此地的人。它对政治中立，只陈述来源。"},{"no":"08","title":"Local as opposed to imported","titleCN":"与外来相对的本地的","definition":"describing what belongs to a place as distinct from what was introduced","definitionCN":"描述属于本地、区别于外来引入的事物","example":"Local farmers prefer indigenous breeds.","exampleCN":"当地农民偏爱本地品种。","why":"The word always draws a border. On one side are things grown here; on the other, things carried in.","whyCN":"这个词始终画一条边界。一边是在此地长成的东西，另一边是被搬进来的东西。"}],"etymology":{"intro":{"en":"Indigenous comes from Latin indigena, 'a native, one born in the country'. It is built from an old form of in- plus gignere, 'to beget, to give birth'. The word therefore means 'born here', and every sense tests where a thing's origin lies.","cn":"indigenous 来自拉丁语 indigena“本地人、本地出生者”。它由 in- 的古体加 gignere“生育、产生”构成。因此这个词意为“在此出生”，每个义项都在检验某物的来源在何处。"},"items":[{"era":"PIE *gen- (reconstructed form)","en":"The root behind gignere, 'to beget', is reconstructed as *gen-, 'to give birth, to produce'. It is generally accepted and also underlies genus, generate and kin.","cn":"gignere“生育”背后的词根被重构为 *gen-“生育、产生”，一般被接受，也是 genus、generate 与 kin 的来源。"},{"era":"LATIN gignere / genus","en":"Gignere meant 'to beget, to cause to be'. Its related noun genus named a birth-line or kind. The two words gave English a whole family of origin words.","cn":"gignere 意为“生育、使存在”。其相关名词 genus 指血统或种类。两个词为英语提供了一整族关于来源的词。"},{"era":"LATIN indu- (generally considered to be)","en":"Indu- is an archaic form of in-, preserved in indigena. The identification of indu- with in- is generally accepted but rests on comparison rather than direct record.","cn":"indu- 是 in- 的古体，保存在 indigena 中。把 indu- 认定为 in- 一般被接受，但依据是比较而非直接记录。"},{"era":"LATIN indigena","en":"Indigena meant 'native, born in the place'. It was used of people, animals and plants alike, which is why the English word covers all three.","cn":"indigena 意为“本地的、在此出生的”，既用于人，也用于动物与植物，这就是英语这个词同时覆盖三类对象的原因。"},{"era":"16C.–17C. ENGLISH","en":"English borrowed indigenous in the 17th century as a learned word for 'native'. Early writers applied it to plants before peoples.","cn":"英语在 17 世纪借入 indigenous 作学术词，意为“本地的”。早期作者先把它用于植物，后用于人群。"},{"era":"20C. POLITICS AND LAW","en":"Indigenous peoples became the standard international term for the original inhabitants of a region, carrying legal claims about land and self-government.","cn":"indigenous peoples 成为国际上指某地区原初居民的标准说法，承载关于土地与自治的法律主张。"}]},"similar":{"note":{"en":"The look-alike group separates the noun for a person, the abstract noun and the verb of making local. The meaning group compares words for belonging to a place.","cn":"形近组区分指人的名词、抽象名词与“使本土化”的动词；词义组比较表示“属于某地”的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"indigene","ipa":"/ˈɪndɪdʒiːn/","tag":"person noun","definition":"a person or organism native to a region. It is the countable noun behind the adjective.","definitionCN":"某地区原生的个人或生物。它是形容词背后的可数名词。"},{"word":"indigeneity","ipa":"/ˌɪndɪˈdʒeniəti/","tag":"abstract noun","definition":"the quality of being indigenous. It is used in academic and political writing.","definitionCN":"土生土长的性质。它用于学术与政治写作。"},{"word":"indigenize","ipa":"/ɪnˈdɪdʒənaɪz/","tag":"verb","definition":"to make something local in character. It is the active form of the adjective's idea.","definitionCN":"使某物具有本地特征。它是形容词观念的活动形式。"}]},{"heading":"NEAR MEANING","entries":[{"word":"native","ipa":"/ˈneɪtɪv/","tag":"born here","definition":"belonging to a place by birth. It is the everyday near-synonym and can also mean 'innate'.","definitionCN":"因出生而属于某地。它是日常近义词，也可指“天生的”。"},{"word":"aboriginal","ipa":"/ˌæbəˈrɪdʒənl/","tag":"from the beginning","definition":"relating to the earliest known inhabitants. It is close to sense 01 but is used especially of Australia and Canada.","definitionCN":"与已知最早居民有关的。它接近第 1 义项，尤用于澳大利亚与加拿大。"},{"word":"endemic","ipa":"/enˈdemɪk/","tag":"restricted to a place","definition":"found only in one region, often of a species or disease. It stresses restriction, while indigenous stresses origin.","definitionCN":"仅见于某一地区，常用于物种或疾病。它强调限定，而 indigenous 强调来源。"},{"word":"local","ipa":"/ˈləʊkl/","tag":"of the area","definition":"belonging to a particular neighbourhood or district. It is broader and carries no claim about origins.","definitionCN":"属于某一街区或地区的。它更宽，不含关于起源的主张。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks build indigenous from indu- plus gignere, 'to be born', and keep the image of a tree whose roots never left this soil.","cn":"这些记忆钩从 indu- 加 gignere“生育”搭起 indigenous，并保留“树根从未离开这片土”的意象。"},"normal":[{"en":"See gignere: born. Indigenous means born in this place, not brought here.","cn":"看见 gignere：出生。indigenous 意为在此地出生，而非被搬来。"},{"en":"Picture a tree whose roots are visible in the local soil and go nowhere else.","cn":"想象一棵树，根就露在本地土壤里，哪里也不去。"},{"en":"Compare with exotic: indigenous grew here, exotic was carried in.","cn":"与 exotic 对照：indigenous 是在此长成，exotic 是被搬进来。"},{"en":"An indigenous language keeps its grammar in the ground of the community.","cn":"本地语言把语法留在共同体脚下的土里。"},{"en":"Remember the family: genus, generate and native all come from the same 'birth' root.","cn":"记住词族：genus、generate、native 都出自同一个“出生”词根。"}],"abstract":[{"en":"Keep one image: a border drawn around a place, and everything inside it that grew there.","cn":"只记一个意象：围绕某地画一条边界，边界内一切在此长成的东西。"},{"en":"Treat the word as a question about origin, not about quality.","cn":"把这个词当作关于来源的问题，而不是关于品质的问题。"},{"en":"Notice that the same adjective defends a plant, a language and a legal right.","cn":"注意同一个形容词可以为一株植物、一种语言和一项法定权利辩护。"}]},"examples":[{"en":"The museum works closely with indigenous communities.","cn":"这家博物馆与原住民社区密切合作。"},{"en":"Several indigenous species are now threatened by the dam.","cn":"几种本地原生种如今受到大坝威胁。"},{"en":"The programme supports indigenous knowledge in medicine.","cn":"该项目支持医学领域的本土知识。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“印地真牛死”：印度本地土生土长的牛真厉害——土生土长的、原产的。","word":"indigenous"},"root":"拉丁语 indigena“本地出生者”，由 indu-（in- 的古体，“在内”）加 gignere“生育”构成；核心义为“在此地出生、根在此地”。","sensesIntro":{"en":"Indigenous always asks one question: where did this begin? A people, a shrub, a festival, a development strategy, a language, a clay deposit, a person and a breed are all tested against the same border. Whatever grew inside the border is indigenous; whatever was carried across it is not.","cn":"indigenous 始终在问一个问题：这东西起源于哪里？一个民族、一株灌木、一个节庆、一种发展战略、一门语言、一处黏土矿、一个人、一个品种，都用同一条边界来检验。在边界内长成的是 indigenous；被搬过边界进来的不是。"},"semanticMap":{"core":{"en":"Born and grown inside a place, with roots that never crossed the border.","cn":"在某地出生、长成，根从未越过边界。"},"chain":["BIRTH","ORIGIN","ROOT","PLACE","NATIVE","LOCAL"],"branches":[{"senses":"S1 · S7","en":"PEOPLE: the original inhabitants and a person born in the region.","cn":"人：原初居民与在此地出生的人。"},{"senses":"S2 · S6","en":"NATURE: species and materials formed in this ground.","cn":"自然：在这片土地上演化或形成的物种与材料。"},{"senses":"S3 · S5","en":"CULTURE: customs and languages shaped locally.","cn":"文化：在当地成形的风俗与语言。"},{"senses":"S4","en":"DEVELOPMENT: growth from local resources and initiative.","cn":"发展：由本地资源与主动性产生的成长。"},{"senses":"S8","en":"CONTRAST: what belongs here against what was imported.","cn":"对照：属于此地之物与输入之物。"}]},"affixes":{"intro":{"en":"Indigenous is indu- plus gignere plus -ous. The items below show the birth family and the forms built directly on this adjective.","cn":"indigenous 是 indu- 加 gignere 再加 -ous。下列条目展示“出生”词族，以及直接建立在这个形容词上的形式。"},"latinIntro":{"en":"The Latin entries give the native noun, the begetting verb and the archaic prefix. Together they spell out 'born inside'.","cn":"拉丁语条目给出本地人名词、生育动词与古体前缀。三者合起来拼出“生于其内”。"},"items":[{"word":"indigenous","structure":"Latin indigena + -ous","meaning":"native to a place","meaningCN":"某地原生的","example":"The olive is indigenous to the region.","exampleCN":"油橄榄原产于该地区。"},{"word":"indigene","structure":"Latin indigena, noun use","meaning":"a native person or organism","meaningCN":"本地人或原生生物","example":"The indigenes were consulted first.","exampleCN":"最先征询的是本地居民。"},{"word":"indigeneity","structure":"indigenous + -ity","meaning":"the quality of being native","meaningCN":"原住性；本土性","example":"The court debated the meaning of indigeneity.","exampleCN":"法庭辩论了原住性的含义。"},{"word":"indigenously","structure":"indigenous + -ly","meaning":"in a native way","meaningCN":"以本地方式","example":"The crop was indigenously developed.","exampleCN":"这一作物是本地培育的。"},{"word":"indigenize","structure":"indigenous + -ize","meaning":"to make local in character","meaningCN":"使本土化","example":"They indigenized the curriculum.","exampleCN":"他们使课程本土化。"},{"word":"indigenization","structure":"indigenize + -ation","meaning":"the process of making local","meaningCN":"本土化的过程","example":"Indigenization of the syllabus took years.","exampleCN":"教学大纲的本土化花了多年。"},{"word":"indigenousness","structure":"indigenous + -ness","meaning":"the state of being native","meaningCN":"本地原生的状态","example":"They questioned the indigenousness of the breed.","exampleCN":"他们质疑这一品种的原生性。"},{"word":"native","structure":"Latin nativus, from nasci 'to be born'","meaning":"born in a place","meaningCN":"出生于某地的","example":"She is a native speaker of the language.","exampleCN":"她是这门语言的母语者。"}],"latinEntries":[{"word":"indigena","structure":"indu- (old form of in-) + gignere","meaning":"native, born in the place","meaningCN":"本地的；在此出生的"},{"word":"gignere","structure":"3rd conjugation verb","meaning":"to beget, to give birth","meaningCN":"生育；产生"},{"word":"indu-","structure":"archaic prefix, related to in-","meaning":"in, within","meaningCN":"在内"}]}}]);
